/* Vade Mecum — Lei 14.133/2021. Texto compilado conferido no Planalto (arquivo salvo em 2026-10-31). Gerado por tools/vade-extrair.py */
(window.NEXO_VADE = window.NEXO_VADE || {})["l14133"] = {"id":"l14133","nome":"Lei 14.133/2021","prefixo":"Lei 14.133/2021","titulo":"LEI Nº 14.133, DE 1º DE ABRIL DE 2021","ementa":"Lei de Licitações e Contratos Administrativos.","fonte":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","extraido":"2026-10-31","itens":[{"k":"cap","t":"TÍTULO I","s":"DISPOSIÇÕES PRELIMINARES"},{"k":"cap","t":"CAPÍTULO I","s":"DO ÂMBITO DE APLICAÇÃO DESTA LEI"},{"k":"art","n":"1º","id":"a1","p":[{"k":"cap","r":"","t":"Esta Lei estabelece normas gerais de licitação e contratação para as Administrações Públicas diretas, autárquicas e fundacionais da União, dos Estados, do Distrito Federal e dos Municípios, e abrange:"},{"k":"inc","r":"I","t":"os órgãos dos Poderes Legislativo e Judiciário da União, dos Estados e do Distrito Federal e os órgãos do Poder Legislativo dos Municípios, quando no desempenho de função administrativa;"},{"k":"inc","r":"II","t":"os fundos especiais e as demais entidades controladas direta ou indiretamente pela Administração Pública."},{"k":"par","r":"§ 1º","t":"Não são abrangidas por esta Lei as empresas públicas, as sociedades de economia mista e as suas subsidiárias, regidas pela Lei nº 13.303, de 30 de junho de 2016, ressalvado o disposto no art. 178 desta Lei."},{"k":"par","r":"§ 2º","t":"As contratações realizadas no âmbito das repartições públicas sediadas no exterior obedecerão às peculiaridades locais e aos princípios básicos estabelecidos nesta Lei, na forma de regulamentação específica a ser editada por ministro de Estado."},{"k":"par","r":"§ 3º","t":"Nas licitações e contratações que envolvam recursos provenientes de empréstimo ou doação oriundos de agência oficial de cooperação estrangeira ou de organismo financeiro de que o Brasil seja parte, podem ser admitidas:"},{"k":"inc","r":"I","t":"condições decorrentes de acordos internacionais aprovados pelo Congresso Nacional e ratificados pelo Presidente da República;"},{"k":"inc","r":"II","t":"condições peculiares à seleção e à contratação constantes de normas e procedimentos das agências ou dos organismos, desde que:"},{"k":"ali","r":"a)","t":"sejam exigidas para a obtenção do empréstimo ou doação;"},{"k":"ali","r":"b)","t":"não conflitem com os princípios constitucionais em vigor;"},{"k":"ali","r":"c)","t":"sejam indicadas no respectivo contrato de empréstimo ou doação e tenham sido objeto de parecer favorável do órgão jurídico do contratante do financiamento previamente à celebração do referido contrato;"},{"k":"ali","r":"d)","t":"","n":["(VETADO)"],"rev":1},{"k":"par","r":"§ 4º","t":"A documentação encaminhada ao Senado Federal para autorização do empréstimo de que trata o § 3º deste artigo deverá fazer referência às condições contratuais que incidam na hipótese do referido parágrafo."},{"k":"par","r":"§ 5º","t":"As contratações relativas à gestão, direta e indireta, das reservas internacionais do País, inclusive as de serviços conexos ou acessórios a essa atividade, serão disciplinadas em ato normativo próprio do Banco Central do Brasil, assegurada a observância dos princípios estabelecidos no caput do art. 37 da Constituição Federal."}]},{"k":"art","n":"2º","id":"a2","p":[{"k":"cap","r":"","t":"Esta Lei aplica-se a:"},{"k":"inc","r":"I","t":"alienação e concessão de direito real de uso de bens;"},{"k":"inc","r":"II","t":"compra, inclusive por encomenda;"},{"k":"inc","r":"III","t":"locação;"},{"k":"inc","r":"IV","t":"concessão e permissão de uso de bens públicos;"},{"k":"inc","r":"V","t":"prestação de serviços, inclusive os técnico-profissionais especializados;"},{"k":"inc","r":"VI","t":"obras e serviços de arquitetura e engenharia;"},{"k":"inc","r":"VII","t":"contratações de tecnologia da informação e de comunicação."}]},{"k":"art","n":"3º","id":"a3","p":[{"k":"cap","r":"","t":"Não se subordinam ao regime desta Lei:"},{"k":"inc","r":"I","t":"contratos que tenham por objeto operação de crédito, interno ou externo, e gestão de dívida pública, incluídas as contratações de agente financeiro e a concessão de garantia relacionadas a esses contratos;"},{"k":"inc","r":"II","t":"contratações sujeitas a normas previstas em legislação própria."}]},{"k":"art","n":"4º","id":"a4","p":[{"k":"cap","r":"","t":"Aplicam-se às licitações e contratos disciplinados por esta Lei as disposições constantes dos arts. 42 a 49 da Lei Complementar nº 123, de 14 de dezembro de 2006."},{"k":"par","r":"§ 1º","t":"As disposições a que se refere o caput deste artigo não são aplicadas:"},{"k":"inc","r":"I","t":"no caso de licitação para aquisição de bens ou contratação de serviços em geral, ao item cujo valor estimado for superior à receita bruta máxima admitida para fins de enquadramento como empresa de pequeno porte;"},{"k":"inc","r":"II","t":"no caso de contratação de obras e serviços de engenharia, às licitações cujo valor estimado for superior à receita bruta máxima admitida para fins de enquadramento como empresa de pequeno porte."},{"k":"par","r":"§ 2º","t":"A obtenção de benefícios a que se refere o caput deste artigo fica limitada às microempresas e às empresas de pequeno porte que, no ano-calendário de realização da licitação, ainda não tenham celebrado contratos com a Administração Pública cujos valores somados extrapolem a receita bruta máxima admitida para fins de enquadramento como empresa de pequeno porte, devendo o órgão ou entidade exigir do licitante declaração de observância desse limite na licitação."},{"k":"par","r":"§ 3º","t":"Nas contratações com prazo de vigência superior a 1 (um) ano, será considerado o valor anual do contrato na aplicação dos limites previstos nos §§ 1º e 2º deste artigo."}]},{"k":"cap","t":"CAPÍTULO II","s":"DOS PRINCÍPIOS"},{"k":"art","n":"5º","id":"a5","p":[{"k":"cap","r":"","t":"Na aplicação desta Lei, serão observados os princípios da legalidade, da impessoalidade, da moralidade, da publicidade, da eficiência, do interesse público, da probidade administrativa, da igualdade, do planejamento, da transparência, da eficácia, da segregação de funções, da motivação, da vinculação ao edital, do julgamento objetivo, da segurança jurídica, da razoabilidade, da competitividade, da proporcionalidade, da celeridade, da economicidade e do desenvolvimento nacional sustentável, assim como as disposições do Decreto-Lei nº 4.657, de 4 de setembro de 1942 (Lei de Introdução às Normas do Direito Brasileiro)."}]},{"k":"cap","t":"CAPÍTULO III","s":"DAS DEFINIÇÕES"},{"k":"art","n":"6º","id":"a6","p":[{"k":"cap","r":"","t":"Para os fins desta Lei, consideram-se:"},{"k":"inc","r":"I","t":"órgão: unidade de atuação integrante da estrutura da Administração Pública;"},{"k":"inc","r":"II","t":"entidade: unidade de atuação dotada de personalidade jurídica;"},{"k":"inc","r":"III","t":"Administração Pública: administração direta e indireta da União, dos Estados, do Distrito Federal e dos Municípios, inclusive as entidades com personalidade jurídica de direito privado sob controle do poder público e as fundações por ele instituídas ou mantidas;"},{"k":"inc","r":"IV","t":"Administração: órgão ou entidade por meio do qual a Administração Pública atua;"},{"k":"inc","r":"V","t":"agente público: indivíduo que, em virtude de eleição, nomeação, designação, contratação ou qualquer outra forma de investidura ou vínculo, exerce mandato, cargo, emprego ou função em pessoa jurídica integrante da Administração Pública;"},{"k":"inc","r":"VI","t":"autoridade: agente público dotado de poder de decisão;"},{"k":"inc","r":"VII","t":"contratante: pessoa jurídica integrante da Administração Pública responsável pela contratação;"},{"k":"inc","r":"VIII","t":"contratado: pessoa física ou jurídica, ou consórcio de pessoas jurídicas, signatária de contrato com a Administração;"},{"k":"inc","r":"IX","t":"licitante: pessoa física ou jurídica, ou consórcio de pessoas jurídicas, que participa ou manifesta a intenção de participar de processo licitatório, sendo-lhe equiparável, para os fins desta Lei, o fornecedor ou o prestador de serviço que, em atendimento à solicitação da Administração, oferece proposta;"},{"k":"inc","r":"X","t":"compra: aquisição remunerada de bens para fornecimento de uma só vez ou parceladamente, considerada imediata aquela com prazo de entrega de até 30 (trinta) dias da ordem de fornecimento;"},{"k":"inc","r":"XI","t":"serviço: atividade ou conjunto de atividades destinadas a obter determinada utilidade, intelectual ou material, de interesse da Administração;"},{"k":"inc","r":"XII","t":"obra: toda atividade estabelecida, por força de lei, como privativa das profissões de arquiteto e engenheiro que implica intervenção no meio ambiente por meio de um conjunto harmônico de ações que, agregadas, formam um todo que inova o espaço físico da natureza ou acarreta alteração substancial das características originais de bem imóvel;"},{"k":"inc","r":"XIII","t":"bens e serviços comuns: aqueles cujos padrões de desempenho e qualidade podem ser objetivamente definidos pelo edital, por meio de especificações usuais de mercado;"},{"k":"inc","r":"XIV","t":"bens e serviços especiais: aqueles que, por sua alta heterogeneidade ou complexidade, não podem ser descritos na forma do inciso XIII do caput deste artigo, exigida justificativa prévia do contratante;"},{"k":"inc","r":"XV","t":"serviços e fornecimentos contínuos: serviços contratados e compras realizadas pela Administração Pública para a manutenção da atividade administrativa, decorrentes de necessidades permanentes ou prolongadas;"},{"k":"inc","r":"XVI","t":"serviços contínuos com regime de dedicação exclusiva de mão de obra: aqueles cujo modelo de execução contratual exige, entre outros requisitos, que:"},{"k":"ali","r":"a)","t":"os empregados do contratado fiquem à disposição nas dependências do contratante para a prestação dos serviços;"},{"k":"ali","r":"b)","t":"o contratado não compartilhe os recursos humanos e materiais disponíveis de uma contratação para execução simultânea de outros contratos;"},{"k":"ali","r":"c)","t":"o contratado possibilite a fiscalização pelo contratante quanto à distribuição, controle e supervisão dos recursos humanos alocados aos seus contratos;"},{"k":"inc","r":"XVII","t":"serviços não contínuos ou contratados por escopo: aqueles que impõem ao contratado o dever de realizar a prestação de um serviço específico em período predeterminado, podendo ser prorrogado, desde que justificadamente, pelo prazo necessário à conclusão do objeto;"},{"k":"inc","r":"XVIII","t":"serviços técnicos especializados de natureza predominantemente intelectual: aqueles realizados em trabalhos relativos a:"},{"k":"ali","r":"a)","t":"estudos técnicos, planejamentos, projetos básicos e projetos executivos;"},{"k":"ali","r":"b)","t":"pareceres, perícias e avaliações em geral;"},{"k":"ali","r":"c)","t":"assessorias e consultorias técnicas e auditorias financeiras e tributárias;"},{"k":"ali","r":"d)","t":"fiscalização, supervisão e gerenciamento de obras e serviços;"},{"k":"ali","r":"e)","t":"patrocínio ou defesa de causas judiciais e administrativas;"},{"k":"ali","r":"f)","t":"treinamento e aperfeiçoamento de pessoal;"},{"k":"ali","r":"g)","t":"restauração de obras de arte e de bens de valor histórico;"},{"k":"ali","r":"h)","t":"controles de qualidade e tecnológico, análises, testes e ensaios de campo e laboratoriais, instrumentação e monitoramento de parâmetros específicos de obras e do meio ambiente e demais serviços de engenharia que se enquadrem na definição deste inciso;"},{"k":"inc","r":"XIX","t":"notória especialização: qualidade de profissional ou de empresa cujo conceito, no campo de sua especialidade, decorrente de desempenho anterior, estudos, experiência, publicações, organização, aparelhamento, equipe técnica ou outros requisitos relacionados com suas atividades, permite inferir que o seu trabalho é essencial e reconhecidamente adequado à plena satisfação do objeto do contrato;"},{"k":"inc","r":"XX","t":"estudo técnico preliminar: documento constitutivo da primeira etapa do planejamento de uma contratação que caracteriza o interesse público envolvido e a sua melhor solução e dá base ao anteprojeto, ao termo de referência ou ao projeto básico a serem elaborados caso se conclua pela viabilidade da contratação;"},{"k":"inc","r":"XXI","t":"serviço de engenharia: toda atividade ou conjunto de atividades destinadas a obter determinada utilidade, intelectual ou material, de interesse para a Administração e que, não enquadradas no conceito de obra a que se refere o inciso XII do caput deste artigo, são estabelecidas, por força de lei, como privativas das profissões de arquiteto e engenheiro ou de técnicos especializados, que compreendem:"},{"k":"ali","r":"a)","t":"serviço comum de engenharia: todo serviço de engenharia que tem por objeto ações, objetivamente padronizáveis em termos de desempenho e qualidade, de manutenção, de adequação e de adaptação de bens móveis e imóveis, com preservação das características originais dos bens;"},{"k":"ali","r":"b)","t":"serviço especial de engenharia: aquele que, por sua alta heterogeneidade ou complexidade, não pode se enquadrar na definição constante da alínea “a” deste inciso;"},{"k":"inc","r":"XXII","t":"obras, serviços e fornecimentos de grande vulto: aqueles cujo valor estimado supera R$ 200.000.000,00 (duzentos milhões de reais);","n":["(Vide Decreto nº 12.343, de 2024)","(Vide Decreto nº 12.807, de 2025)"]},{"k":"inc","r":"XXIII","t":"termo de referência: documento necessário para a contratação de bens e serviços, que deve conter os seguintes parâmetros e elementos descritivos:"},{"k":"ali","r":"a)","t":"definição do objeto, incluídos sua natureza, os quantitativos, o prazo do contrato e, se for o caso, a possibilidade de sua prorrogação;"},{"k":"ali","r":"b)","t":"fundamentação da contratação, que consiste na referência aos estudos técnicos preliminares correspondentes ou, quando não for possível divulgar esses estudos, no extrato das partes que não contiverem informações sigilosas;"},{"k":"ali","r":"c)","t":"descrição da solução como um todo, considerado todo o ciclo de vida do objeto;"},{"k":"ali","r":"d)","t":"requisitos da contratação;"},{"k":"ali","r":"e)","t":"modelo de execução do objeto, que consiste na definição de como o contrato deverá produzir os resultados pretendidos desde o seu início até o seu encerramento;"},{"k":"ali","r":"f)","t":"modelo de gestão do contrato, que descreve como a execução do objeto será acompanhada e fiscalizada pelo órgão ou entidade;"},{"k":"ali","r":"g)","t":"critérios de medição e de pagamento;"},{"k":"ali","r":"h)","t":"forma e critérios de seleção do fornecedor;"},{"k":"ali","r":"i)","t":"estimativas do valor da contratação, acompanhadas dos preços unitários referenciais, das memórias de cálculo e dos documentos que lhe dão suporte, com os parâmetros utilizados para a obtenção dos preços e para os respectivos cálculos, que devem constar de documento separado e classificado;"},{"k":"ali","r":"j)","t":"adequação orçamentária;"},{"k":"inc","r":"XXIV","t":"anteprojeto: peça técnica com todos os subsídios necessários à elaboração do projeto básico, que deve conter, no mínimo, os seguintes elementos:"},{"k":"ali","r":"a)","t":"demonstração e justificativa do programa de necessidades, avaliação de demanda do público-alvo, motivação técnico-econômico-social do empreendimento, visão global dos investimentos e definições relacionadas ao nível de serviço desejado;"},{"k":"ali","r":"b)","t":"condições de solidez, de segurança e de durabilidade;"},{"k":"ali","r":"c)","t":"prazo de entrega;"},{"k":"ali","r":"d)","t":"estética do projeto arquitetônico, traçado geométrico e/ou projeto da área de influência, quando cabível;"},{"k":"ali","r":"e)","t":"parâmetros de adequação ao interesse público, de economia na utilização, de facilidade na execução, de impacto ambiental e de acessibilidade;"},{"k":"ali","r":"f)","t":"proposta de concepção da obra ou do serviço de engenharia;"},{"k":"ali","r":"g)","t":"projetos anteriores ou estudos preliminares que embasaram a concepção proposta;"},{"k":"ali","r":"h)","t":"levantamento topográfico e cadastral;"},{"k":"ali","r":"i)","t":"pareceres de sondagem;"},{"k":"ali","r":"j)","t":"memorial descritivo dos elementos da edificação, dos componentes construtivos e dos materiais de construção, de forma a estabelecer padrões mínimos para a contratação;"},{"k":"inc","r":"XXV","t":"projeto básico: conjunto de elementos necessários e suficientes, com nível de precisão adequado para definir e dimensionar a obra ou o serviço, ou o complexo de obras ou de serviços objeto da licitação, elaborado com base nas indicações dos estudos técnicos preliminares, que assegure a viabilidade técnica e o adequado tratamento do impacto ambiental do empreendimento e que possibilite a avaliação do custo da obra e a definição dos métodos e do prazo de execução, devendo conter os seguintes elementos:"},{"k":"ali","r":"a)","t":"levantamentos topográficos e cadastrais, sondagens e ensaios geotécnicos, ensaios e análises laboratoriais, estudos socioambientais e demais dados e levantamentos necessários para execução da solução escolhida;"},{"k":"ali","r":"b)","t":"soluções técnicas globais e localizadas, suficientemente detalhadas, de forma a evitar, por ocasião da elaboração do projeto executivo e da realização das obras e montagem, a necessidade de reformulações ou variantes quanto à qualidade, ao preço e ao prazo inicialmente definidos;"},{"k":"ali","r":"c)","t":"identificação dos tipos de serviços a executar e dos materiais e equipamentos a incorporar à obra, bem como das suas especificações, de modo a assegurar os melhores resultados para o empreendimento e a segurança executiva na utilização do objeto, para os fins a que se destina, considerados os riscos e os perigos identificáveis, sem frustrar o caráter competitivo para a sua execução;"},{"k":"ali","r":"d)","t":"informações que possibilitem o estudo e a definição de métodos construtivos, de instalações provisórias e de condições organizacionais para a obra, sem frustrar o caráter competitivo para a sua execução;"},{"k":"ali","r":"e)","t":"subsídios para montagem do plano de licitação e gestão da obra, compreendidos a sua programação, a estratégia de suprimentos, as normas de fiscalização e outros dados necessários em cada caso;"},{"k":"ali","r":"f)","t":"orçamento detalhado do custo global da obra, fundamentado em quantitativos de serviços e fornecimentos propriamente avaliados, obrigatório exclusivamente para os regimes de execução previstos nos incisos I, II, III, IV e VII do caput do art. 46 desta Lei;"},{"k":"inc","r":"XXVI","t":"projeto executivo: conjunto de elementos necessários e suficientes à execução completa da obra, com o detalhamento das soluções previstas no projeto básico, a identificação de serviços, de materiais e de equipamentos a serem incorporados à obra, bem como suas especificações técnicas, de acordo com as normas técnicas pertinentes;"},{"k":"inc","r":"XXVII","t":"matriz de riscos: cláusula contratual definidora de riscos e de responsabilidades entre as partes e caracterizadora do equilíbrio econômico-financeiro inicial do contrato, em termos de ônus financeiro decorrente de eventos supervenientes à contratação, contendo, no mínimo, as seguintes informações:"},{"k":"ali","r":"a)","t":"listagem de possíveis eventos supervenientes à assinatura do contrato que possam causar impacto em seu equilíbrio econômico-financeiro e previsão de eventual necessidade de prolação de termo aditivo por ocasião de sua ocorrência;"},{"k":"ali","r":"b)","t":"no caso de obrigações de resultado, estabelecimento das frações do objeto com relação às quais haverá liberdade para os contratados inovarem em soluções metodológicas ou tecnológicas, em termos de modificação das soluções previamente delineadas no anteprojeto ou no projeto básico;"},{"k":"ali","r":"c)","t":"no caso de obrigações de meio, estabelecimento preciso das frações do objeto com relação às quais não haverá liberdade para os contratados inovarem em soluções metodológicas ou tecnológicas, devendo haver obrigação de aderência entre a execução e a solução predefinida no anteprojeto ou no projeto básico, consideradas as características do regime de execução no caso de obras e serviços de engenharia;"},{"k":"inc","r":"XXVIII","t":"empreitada por preço unitário: contratação da execução da obra ou do serviço por preço certo de unidades determinadas;"},{"k":"inc","r":"XXIX","t":"empreitada por preço global: contratação da execução da obra ou do serviço por preço certo e total;"},{"k":"inc","r":"XXX","t":"empreitada integral: contratação de empreendimento em sua integralidade, compreendida a totalidade das etapas de obras, serviços e instalações necessárias, sob inteira responsabilidade do contratado até sua entrega ao contratante em condições de entrada em operação, com características adequadas às finalidades para as quais foi contratado e atendidos os requisitos técnicos e legais para sua utilização com segurança estrutural e operacional;"},{"k":"inc","r":"XXXI","t":"contratação por tarefa: regime de contratação de mão de obra para pequenos trabalhos por preço certo, com ou sem fornecimento de materiais;"},{"k":"inc","r":"XXXII","t":"contratação integrada: regime de contratação de obras e serviços de engenharia em que o contratado é responsável por elaborar e desenvolver os projetos básico e executivo, executar obras e serviços de engenharia, fornecer bens ou prestar serviços especiais e realizar montagem, teste, pré-operação e as demais operações necessárias e suficientes para a entrega final do objeto;"},{"k":"inc","r":"XXXIII","t":"contratação semi-integrada: regime de contratação de obras e serviços de engenharia em que o contratado é responsável por elaborar e desenvolver o projeto executivo, executar obras e serviços de engenharia, fornecer bens ou prestar serviços especiais e realizar montagem, teste, pré-operação e as demais operações necessárias e suficientes para a entrega final do objeto;"},{"k":"inc","r":"XXXIV","t":"fornecimento e prestação de serviço associado: regime de contratação em que, além do fornecimento do objeto, o contratado responsabiliza-se por sua operação, manutenção ou ambas, por tempo determinado;"},{"k":"inc","r":"XXXV","t":"licitação internacional: licitação processada em território nacional na qual é admitida a participação de licitantes estrangeiros, com a possibilidade de cotação de preços em moeda estrangeira, ou licitação na qual o objeto contratual pode ou deve ser executado no todo ou em parte em território estrangeiro;"},{"k":"inc","r":"XXXVI","t":"serviço nacional: serviço prestado em território nacional, nas condições estabelecidas pelo Poder Executivo federal;"},{"k":"inc","r":"XXXVII","t":"produto manufaturado nacional: produto manufaturado produzido no território nacional de acordo com o processo produtivo básico ou com as regras de origem estabelecidas pelo Poder Executivo federal;"},{"k":"inc","r":"XXXVIII","t":"concorrência: modalidade de licitação para contratação de bens e serviços especiais e de obras e serviços comuns e especiais de engenharia, cujo critério de julgamento poderá ser:"},{"k":"ali","r":"a)","t":"menor preço;"},{"k":"ali","r":"b)","t":"melhor técnica ou conteúdo artístico;"},{"k":"ali","r":"c)","t":"técnica e preço;"},{"k":"ali","r":"d)","t":"maior retorno econômico;"},{"k":"ali","r":"e)","t":"maior desconto;"},{"k":"inc","r":"XXXIX","t":"concurso: modalidade de licitação para escolha de trabalho técnico, científico ou artístico, cujo critério de julgamento será o de melhor técnica ou conteúdo artístico, e para concessão de prêmio ou remuneração ao vencedor;"},{"k":"inc","r":"XL","t":"leilão: modalidade de licitação para alienação de bens imóveis ou de bens móveis inservíveis ou legalmente apreendidos a quem oferecer o maior lance;"},{"k":"inc","r":"XLI","t":"pregão: modalidade de licitação obrigatória para aquisição de bens e serviços comuns, cujo critério de julgamento poderá ser o de menor preço ou o de maior desconto;"},{"k":"inc","r":"XLII","t":"diálogo competitivo: modalidade de licitação para contratação de obras, serviços e compras em que a Administração Pública realiza diálogos com licitantes previamente selecionados mediante critérios objetivos, com o intuito de desenvolver uma ou mais alternativas capazes de atender às suas necessidades, devendo os licitantes apresentar proposta final após o encerramento dos diálogos;"},{"k":"inc","r":"XLIII","t":"credenciamento: processo administrativo de chamamento público em que a Administração Pública convoca interessados em prestar serviços ou fornecer bens para que, preenchidos os requisitos necessários, se credenciem no órgão ou na entidade para executar o objeto quando convocados;"},{"k":"inc","r":"XLIV","t":"pré-qualificação: procedimento seletivo prévio à licitação, convocado por meio de edital, destinado à análise das condições de habilitação, total ou parcial, dos interessados ou do objeto;"},{"k":"inc","r":"XLV","t":"sistema de registro de preços: conjunto de procedimentos para realização, mediante contratação direta ou licitação nas modalidades pregão ou concorrência, de registro formal de preços relativos a prestação de serviços, a obras e a aquisição e locação de bens para contratações futuras;"},{"k":"inc","r":"XLVI","t":"ata de registro de preços: documento vinculativo e obrigacional, com característica de compromisso para futura contratação, no qual são registrados o objeto, os preços, os fornecedores, os órgãos participantes e as condições a serem praticadas, conforme as disposições contidas no edital da licitação, no aviso ou instrumento de contratação direta e nas propostas apresentadas;"},{"k":"inc","r":"XLVII","t":"órgão ou entidade gerenciadora: órgão ou entidade da Administração Pública responsável pela condução do conjunto de procedimentos para registro de preços e pelo gerenciamento da ata de registro de preços dele decorrente;"},{"k":"inc","r":"XLVIII","t":"órgão ou entidade participante: órgão ou entidade da Administração Pública que participa dos procedimentos iniciais da contratação para registro de preços e integra a ata de registro de preços;"},{"k":"inc","r":"XLIX","t":"órgão ou entidade não participante: órgão ou entidade da Administração Pública que não participa dos procedimentos iniciais da licitação para registro de preços e não integra a ata de registro de preços;"},{"k":"inc","r":"L","t":"comissão de contratação: conjunto de agentes públicos indicados pela Administração, em caráter permanente ou especial, com a função de receber, examinar e julgar documentos relativos às licitações e aos procedimentos auxiliares;"},{"k":"inc","r":"LI","t":"catálogo eletrônico de padronização de compras, serviços e obras: sistema informatizado, de gerenciamento centralizado e com indicação de preços, destinado a permitir a padronização de itens a serem adquiridos pela Administração Pública e que estarão disponíveis para a licitação;"},{"k":"inc","r":"LII","t":"sítio eletrônico oficial: sítio da internet, certificado digitalmente por autoridade certificadora, no qual o ente federativo divulga de forma centralizada as informações e os serviços de governo digital dos seus órgãos e entidades;"},{"k":"inc","r":"LIII","t":"contrato de eficiência: contrato cujo objeto é a prestação de serviços, que pode incluir a realização de obras e o fornecimento de bens, com o objetivo de proporcionar economia ao contratante, na forma de redução de despesas correntes, remunerado o contratado com base em percentual da economia gerada;"},{"k":"inc","r":"LIV","t":"seguro-garantia: seguro que garante o fiel cumprimento das obrigações assumidas pelo contratado;"},{"k":"inc","r":"LV","t":"produtos para pesquisa e desenvolvimento: bens, insumos, serviços e obras necessários para atividade de pesquisa científica e tecnológica, desenvolvimento de tecnologia ou inovação tecnológica, discriminados em projeto de pesquisa;"},{"k":"inc","r":"LVI","t":"sobrepreço: preço orçado para licitação ou contratado em valor expressivamente superior aos preços referenciais de mercado, seja de apenas 1 (um) item, se a licitação ou a contratação for por preços unitários de serviço, seja do valor global do objeto, se a licitação ou a contratação for por tarefa, empreitada por preço global ou empreitada integral, semi-integrada ou integrada;"},{"k":"inc","r":"LVII","t":"superfaturamento: dano provocado ao patrimônio da Administração, caracterizado, entre outras situações, por:"},{"k":"ali","r":"a)","t":"medição de quantidades superiores às efetivamente executadas ou fornecidas;"},{"k":"ali","r":"b)","t":"deficiência na execução de obras e de serviços de engenharia que resulte em diminuição da sua qualidade, vida útil ou segurança;"},{"k":"ali","r":"c)","t":"alterações no orçamento de obras e de serviços de engenharia que causem desequilíbrio econômico- financeiro do contrato em favor do contratado;"},{"k":"ali","r":"d)","t":"outras alterações de cláusulas financeiras que gerem recebimentos contratuais antecipados, distorção do cronograma físico-financeiro, prorrogação injustificada do prazo contratual com custos adicionais para a Administração ou reajuste irregular de preços;"},{"k":"inc","r":"LVIII","t":"reajustamento em sentido estrito: forma de manutenção do equilíbrio econômico-financeiro de contrato consistente na aplicação do índice de correção monetária previsto no contrato, que deve retratar a variação efetiva do custo de produção, admitida a adoção de índices específicos ou setoriais;"},{"k":"inc","r":"LIX","t":"repactuação: forma de manutenção do equilíbrio econômico-financeiro de contrato utilizada para serviços contínuos com regime de dedicação exclusiva de mão de obra ou predominância de mão de obra, por meio da análise da variação dos custos contratuais, devendo estar prevista no edital com data vinculada à apresentação das propostas, para os custos decorrentes do mercado, e com data vinculada ao acordo, à convenção coletiva ou ao dissídio coletivo ao qual o orçamento esteja vinculado, para os custos decorrentes da mão de obra;"},{"k":"inc","r":"LX","t":"agente de contratação: pessoa designada pela autoridade competente, entre servidores efetivos ou empregados públicos dos quadros permanentes da Administração Pública, para tomar decisões, acompanhar o trâmite da licitação, dar impulso ao procedimento licitatório e executar quaisquer outras atividades necessárias ao bom andamento do certame até a homologação."}]},{"k":"cap","t":"CAPÍTULO IV","s":"DOS AGENTES PÚBLICOS"},{"k":"art","n":"7º","id":"a7","p":[{"k":"cap","r":"","t":"Caberá à autoridade máxima do órgão ou da entidade, ou a quem as normas de organização administrativa indicarem, promover gestão por competências e designar agentes públicos para o desempenho das funções essenciais à execução desta Lei que preencham os seguintes requisitos:"},{"k":"inc","r":"I","t":"sejam, preferencialmente, servidor efetivo ou empregado público dos quadros permanentes da Administração Pública;"},{"k":"inc","r":"II","t":"tenham atribuições relacionadas a licitações e contratos ou possuam formação compatível ou qualificação atestada por certificação profissional emitida por escola de governo criada e mantida pelo poder público; e"},{"k":"inc","r":"III","t":"não sejam cônjuge ou companheiro de licitantes ou contratados habituais da Administração nem tenham com eles vínculo de parentesco, colateral ou por afinidade, até o terceiro grau, ou de natureza técnica, comercial, econômica, financeira, trabalhista e civil."},{"k":"par","r":"§ 1º","t":"A autoridade referida no caput deste artigo deverá observar o princípio da segregação de funções, vedada a designação do mesmo agente público para atuação simultânea em funções mais suscetíveis a riscos, de modo a reduzir a possibilidade de ocultação de erros e de ocorrência de fraudes na respectiva contratação."},{"k":"par","r":"§ 2º","t":"O disposto no caput e no § 1º deste artigo, inclusive os requisitos estabelecidos, também se aplica aos órgãos de assessoramento jurídico e de controle interno da Administração."}]},{"k":"art","n":"8º","id":"a8","p":[{"k":"cap","r":"","t":"A licitação será conduzida por agente de contratação, pessoa designada pela autoridade competente, entre servidores efetivos ou empregados públicos dos quadros permanentes da Administração Pública, para tomar decisões, acompanhar o trâmite da licitação, dar impulso ao procedimento licitatório e executar quaisquer outras atividades necessárias ao bom andamento do certame até a homologação."},{"k":"par","r":"§ 1º","t":"O agente de contratação será auxiliado por equipe de apoio e responderá individualmente pelos atos que praticar, salvo quando induzido a erro pela atuação da equipe."},{"k":"par","r":"§ 2º","t":"Em licitação que envolva bens ou serviços especiais, desde que observados os requisitos estabelecidos no art. 7º desta Lei, o agente de contratação poderá ser substituído por comissão de contratação formada por, no mínimo, 3 (três) membros, que responderão solidariamente por todos os atos praticados pela comissão, ressalvado o membro que expressar posição individual divergente fundamentada e registrada em ata lavrada na reunião em que houver sido tomada a decisão."},{"k":"par","r":"§ 3º","t":"As regras relativas à atuação do agente de contratação e da equipe de apoio, ao funcionamento da comissão de contratação e à atuação de fiscais e gestores de contratos de que trata esta Lei serão estabelecidas em regulamento, e deverá ser prevista a possibilidade de eles contarem com o apoio dos órgãos de assessoramento jurídico e de controle interno para o desempenho das funções essenciais à execução do disposto nesta Lei.","n":["(Regulamento)"]},{"k":"par","r":"§ 4º","t":"Em licitação que envolva bens ou serviços especiais cujo objeto não seja rotineiramente contratado pela Administração, poderá ser contratado, por prazo determinado, serviço de empresa ou de profissional especializado para assessorar os agentes públicos responsáveis pela condução da licitação."},{"k":"par","r":"§ 5º","t":"Em licitação na modalidade pregão, o agente responsável pela condução do certame será designado pregoeiro."}]},{"k":"art","n":"9º","id":"a9","p":[{"k":"cap","r":"","t":"É vedado ao agente público designado para atuar na área de licitações e contratos, ressalvados os casos previstos em lei:"},{"k":"inc","r":"I","t":"admitir, prever, incluir ou tolerar, nos atos que praticar, situações que:"},{"k":"ali","r":"a)","t":"comprometam, restrinjam ou frustrem o caráter competitivo do processo licitatório, inclusive nos casos de participação de sociedades cooperativas;"},{"k":"ali","r":"b)","t":"estabeleçam preferências ou distinções em razão da naturalidade, da sede ou do domicílio dos licitantes;"},{"k":"ali","r":"c)","t":"sejam impertinentes ou irrelevantes para o objeto específico do contrato;"},{"k":"inc","r":"II","t":"estabelecer tratamento diferenciado de natureza comercial, legal, trabalhista, previdenciária ou qualquer outra entre empresas brasileiras e estrangeiras, inclusive no que se refere a moeda, modalidade e local de pagamento, mesmo quando envolvido financiamento de agência internacional;"},{"k":"inc","r":"III","t":"opor resistência injustificada ao andamento dos processos e, indevidamente, retardar ou deixar de praticar ato de ofício, ou praticá-lo contra disposição expressa em lei."},{"k":"par","r":"§ 1º","t":"Não poderá participar, direta ou indiretamente, da licitação ou da execução do contrato agente público de órgão ou entidade licitante ou contratante, devendo ser observadas as situações que possam configurar conflito de interesses no exercício ou após o exercício do cargo ou emprego, nos termos da legislação que disciplina a matéria."},{"k":"par","r":"§ 2º","t":"As vedações de que trata este artigo estendem-se a terceiro que auxilie a condução da contratação na qualidade de integrante de equipe de apoio, profissional especializado ou funcionário ou representante de empresa que preste assessoria técnica."}]},{"k":"art","n":"10","id":"a10","p":[{"k":"cap","r":"","t":"Se as autoridades competentes e os servidores públicos que tiverem participado dos procedimentos relacionados às licitações e aos contratos de que trata esta Lei precisarem defender-se nas esferas administrativa, controladora ou judicial em razão de ato praticado com estrita observância de orientação constante em parecer jurídico elaborado na forma do § 1º do art. 53 desta Lei, a advocacia pública promoverá, a critério do agente público, sua representação judicial ou extrajudicial."},{"k":"par","r":"§ 1º","t":"Não se aplica o disposto no caput deste artigo quando:"},{"k":"inc","r":"I","t":"","n":["(VETADO)"],"rev":1},{"k":"inc","r":"II","t":"provas da prática de atos ilícitos dolosos constarem nos autos do processo administrativo ou judicial."},{"k":"par","r":"§ 2º","t":"Aplica-se o disposto no caput deste artigo inclusive na hipótese de o agente público não mais ocupar o cargo, emprego ou função em que foi praticado o ato questionado."}]},{"k":"cap","t":"TÍTULO II","s":"DAS LICITAÇÕES"},{"k":"cap","t":"CAPÍTULO I","s":"DO PROCESSO LICITATÓRIO"},{"k":"art","n":"11","id":"a11","p":[{"k":"cap","r":"","t":"O processo licitatório tem por objetivos:"},{"k":"inc","r":"I","t":"assegurar a seleção da proposta apta a gerar o resultado de contratação mais vantajoso para a Administração Pública, inclusive no que se refere ao ciclo de vida do objeto;"},{"k":"inc","r":"II","t":"assegurar tratamento isonômico entre os licitantes, bem como a justa competição;"},{"k":"inc","r":"III","t":"evitar contratações com sobrepreço ou com preços manifestamente inexequíveis e superfaturamento na execução dos contratos;"},{"k":"inc","r":"IV","t":"incentivar a inovação e o desenvolvimento nacional sustentável."},{"k":"par","r":"Parágrafo único","t":"A alta administração do órgão ou entidade é responsável pela governança das contratações e deve implementar processos e estruturas, inclusive de gestão de riscos e controles internos, para avaliar, direcionar e monitorar os processos licitatórios e os respectivos contratos, com o intuito de alcançar os objetivos estabelecidos no caput deste artigo, promover um ambiente íntegro e confiável, assegurar o alinhamento das contratações ao planejamento estratégico e às leis orçamentárias e promover eficiência, efetividade e eficácia em suas contratações."}]},{"k":"art","n":"12","id":"a12","p":[{"k":"cap","r":"","t":"No processo licitatório, observar-se-á o seguinte:"},{"k":"inc","r":"I","t":"os documentos serão produzidos por escrito, com data e local de sua realização e assinatura dos responsáveis;"},{"k":"inc","r":"II","t":"os valores, os preços e os custos utilizados terão como expressão monetária a moeda corrente nacional, ressalvado o disposto no art. 52 desta Lei;"},{"k":"inc","r":"III","t":"o desatendimento de exigências meramente formais que não comprometam a aferição da qualificação do licitante ou a compreensão do conteúdo de sua proposta não importará seu afastamento da licitação ou a invalidação do processo;"},{"k":"inc","r":"IV","t":"a prova de autenticidade de cópia de documento público ou particular poderá ser feita perante agente da Administração, mediante apresentação de original ou de declaração de autenticidade por advogado, sob sua responsabilidade pessoal;"},{"k":"inc","r":"V","t":"o reconhecimento de firma somente será exigido quando houver dúvida de autenticidade, salvo imposição legal;"},{"k":"inc","r":"VI","t":"os atos serão preferencialmente digitais, de forma a permitir que sejam produzidos, comunicados, armazenados e validados por meio eletrônico;"},{"k":"inc","r":"VII","t":"a partir de documentos de formalização de demandas, os órgãos responsáveis pelo planejamento de cada ente federativo poderão, na forma de regulamento, elaborar plano de contratações anual, com o objetivo de racionalizar as contratações dos órgãos e entidades sob sua competência, garantir o alinhamento com o seu planejamento estratégico e subsidiar a elaboração das respectivas leis orçamentárias.","n":["(Regulamento)"]},{"k":"par","r":"§ 1º","t":"O plano de contratações anual de que trata o inciso VII do caput deste artigo deverá ser divulgado e mantido à disposição do público em sítio eletrônico oficial e será observado pelo ente federativo na realização de licitações e na execução dos contratos."},{"k":"par","r":"§ 2º","t":"É permitida a identificação e assinatura digital por pessoa física ou jurídica em meio eletrônico, mediante certificado digital emitido em âmbito da Infraestrutura de Chaves Públicas Brasileira (ICP-Brasil)."}]},{"k":"art","n":"13","id":"a13","p":[{"k":"cap","r":"","t":"Os atos praticados no processo licitatório são públicos, ressalvadas as hipóteses de informações cujo sigilo seja imprescindível à segurança da sociedade e do Estado, na forma da lei."},{"k":"par","r":"Parágrafo único","t":"A publicidade será diferida:"},{"k":"inc","r":"I","t":"quanto ao conteúdo das propostas, até a respectiva abertura;"},{"k":"inc","r":"II","t":"quanto ao orçamento da Administração, nos termos do art. 24 desta Lei."}]},{"k":"art","n":"14","id":"a14","p":[{"k":"cap","r":"","t":"Não poderão disputar licitação ou participar da execução de contrato, direta ou indiretamente:"},{"k":"inc","r":"I","t":"autor do anteprojeto, do projeto básico ou do projeto executivo, pessoa física ou jurídica, quando a licitação versar sobre obra, serviços ou fornecimento de bens a ele relacionados;"},{"k":"inc","r":"II","t":"empresa, isoladamente ou em consórcio, responsável pela elaboração do projeto básico ou do projeto executivo, ou empresa da qual o autor do projeto seja dirigente, gerente, controlador, acionista ou detentor de mais de 5% (cinco por cento) do capital com direito a voto, responsável técnico ou subcontratado, quando a licitação versar sobre obra, serviços ou fornecimento de bens a ela necessários;"},{"k":"inc","r":"III","t":"pessoa física ou jurídica que se encontre, ao tempo da licitação, impossibilitada de participar da licitação em decorrência de sanção que lhe foi imposta;"},{"k":"inc","r":"IV","t":"aquele que mantenha vínculo de natureza técnica, comercial, econômica, financeira, trabalhista ou civil com dirigente do órgão ou entidade contratante ou com agente público que desempenhe função na licitação ou atue na fiscalização ou na gestão do contrato, ou que deles seja cônjuge, companheiro ou parente em linha reta, colateral ou por afinidade, até o terceiro grau, devendo essa proibição constar expressamente do edital de licitação;"},{"k":"inc","r":"V","t":"empresas controladoras, controladas ou coligadas, nos termos da Lei nº 6.404, de 15 de dezembro de 1976, concorrendo entre si;"},{"k":"inc","r":"VI","t":"pessoa física ou jurídica que, nos 5 (cinco) anos anteriores à divulgação do edital, tenha sido condenada judicialmente, com trânsito em julgado, por exploração de trabalho infantil, por submissão de trabalhadores a condições análogas às de escravo ou por contratação de adolescentes nos casos vedados pela legislação trabalhista."},{"k":"par","r":"§ 1º","t":"O impedimento de que trata o inciso III do caput deste artigo será também aplicado ao licitante que atue em substituição a outra pessoa, física ou jurídica, com o intuito de burlar a efetividade da sanção a ela aplicada, inclusive a sua controladora, controlada ou coligada, desde que devidamente comprovado o ilícito ou a utilização fraudulenta da personalidade jurídica do licitante."},{"k":"par","r":"§ 2º","t":"A critério da Administração e exclusivamente a seu serviço, o autor dos projetos e a empresa a que se referem os incisos I e II do caput deste artigo poderão participar no apoio das atividades de planejamento da contratação, de execução da licitação ou de gestão do contrato, desde que sob supervisão exclusiva de agentes públicos do órgão ou entidade."},{"k":"par","r":"§ 3º","t":"Equiparam-se aos autores do projeto as empresas integrantes do mesmo grupo econômico."},{"k":"par","r":"§ 4º","t":"O disposto neste artigo não impede a licitação ou a contratação de obra ou serviço que inclua como encargo do contratado a elaboração do projeto básico e do projeto executivo, nas contratações integradas, e do projeto executivo, nos demais regimes de execução."},{"k":"par","r":"§ 5º","t":"Em licitações e contratações realizadas no âmbito de projetos e programas parcialmente financiados por agência oficial de cooperação estrangeira ou por organismo financeiro internacional com recursos do financiamento ou da contrapartida nacional, não poderá participar pessoa física ou jurídica que integre o rol de pessoas sancionadas por essas entidades ou que seja declarada inidônea nos termos desta Lei."}]},{"k":"art","n":"15","id":"a15","p":[{"k":"cap","r":"","t":"Salvo vedação devidamente justificada no processo licitatório, pessoa jurídica poderá participar de licitação em consórcio, observadas as seguintes normas:"},{"k":"inc","r":"I","t":"comprovação de compromisso público ou particular de constituição de consórcio, subscrito pelos consorciados;"},{"k":"inc","r":"II","t":"indicação da empresa líder do consórcio, que será responsável por sua representação perante a Administração;"},{"k":"inc","r":"III","t":"admissão, para efeito de habilitação técnica, do somatório dos quantitativos de cada consorciado e, para efeito de habilitação econômico-financeira, do somatório dos valores de cada consorciado;"},{"k":"inc","r":"IV","t":"impedimento de a empresa consorciada participar, na mesma licitação, de mais de um consórcio ou de forma isolada;"},{"k":"inc","r":"V","t":"responsabilidade solidária dos integrantes pelos atos praticados em consórcio, tanto na fase de licitação quanto na de execução do contrato."},{"k":"par","r":"§ 1º","t":"O edital deverá estabelecer para o consórcio acréscimo de 10% (dez por cento) a 30% (trinta por cento) sobre o valor exigido de licitante individual para a habilitação econômico-financeira, salvo justificação."},{"k":"par","r":"§ 2º","t":"O acréscimo previsto no § 1º deste artigo não se aplica aos consórcios compostos, em sua totalidade, de microempresas e pequenas empresas, assim definidas em lei."},{"k":"par","r":"§ 3º","t":"O licitante vencedor é obrigado a promover, antes da celebração do contrato, a constituição e o registro do consórcio, nos termos do compromisso referido no inciso I do caput deste artigo."},{"k":"par","r":"§ 4º","t":"Desde que haja justificativa técnica aprovada pela autoridade competente, o edital de licitação poderá estabelecer limite máximo para o número de empresas consorciadas."},{"k":"par","r":"§ 5º","t":"A substituição de consorciado deverá ser expressamente autorizada pelo órgão ou entidade contratante e condicionada à comprovação de que a nova empresa do consórcio possui, no mínimo, os mesmos quantitativos para efeito de habilitação técnica e os mesmos valores para efeito de qualificação econômico-financeira apresentados pela empresa substituída para fins de habilitação do consórcio no processo licitatório que originou o contrato."}]},{"k":"art","n":"16","id":"a16","p":[{"k":"cap","r":"","t":"Os profissionais organizados sob a forma de cooperativa poderão participar de licitação quando:"},{"k":"inc","r":"I","t":"a constituição e o funcionamento da cooperativa observarem as regras estabelecidas na legislação aplicável, em especial a Lei nº 5.764, de 16 de dezembro de 1971, a Lei nº 12.690, de 19 de julho de 2012, e a Lei Complementar nº 130, de 17 de abril de 2009;"},{"k":"inc","r":"II","t":"a cooperativa apresentar demonstrativo de atuação em regime cooperado, com repartição de receitas e despesas entre os cooperados;"},{"k":"inc","r":"III","t":"qualquer cooperado, com igual qualificação, for capaz de executar o objeto contratado, vedado à Administração indicar nominalmente pessoas;"},{"k":"inc","r":"IV","t":"o objeto da licitação referir-se, em se tratando de cooperativas enquadradas na Lei nº 12.690, de 19 de julho de 2012, a serviços especializados constantes do objeto social da cooperativa, a serem executados de forma complementar à sua atuação."}]},{"k":"art","n":"17","id":"a17","p":[{"k":"cap","r":"","t":"O processo de licitação observará as seguintes fases, em sequência:"},{"k":"inc","r":"I","t":"preparatória;"},{"k":"inc","r":"II","t":"de divulgação do edital de licitação;"},{"k":"inc","r":"III","t":"de apresentação de propostas e lances, quando for o caso;"},{"k":"inc","r":"IV","t":"de julgamento;"},{"k":"inc","r":"V","t":"de habilitação;"},{"k":"inc","r":"VI","t":"recursal;"},{"k":"inc","r":"VII","t":"de homologação."},{"k":"par","r":"§ 1º","t":"A fase referida no inciso V do caput deste artigo poderá, mediante ato motivado com explicitação dos benefícios decorrentes, anteceder as fases referidas nos incisos III e IV do caput deste artigo, desde que expressamente previsto no edital de licitação."},{"k":"par","r":"§ 2º","t":"As licitações serão realizadas preferencialmente sob a forma eletrônica, admitida a utilização da forma presencial, desde que motivada, devendo a sessão pública ser registrada em ata e gravada em áudio e vídeo."},{"k":"par","r":"§ 3º","t":"Desde que previsto no edital, na fase a que se refere o inciso IV do caput deste artigo, o órgão ou entidade licitante poderá, em relação ao licitante provisoriamente vencedor, realizar análise e avaliação da conformidade da proposta, mediante homologação de amostras, exame de conformidade e prova de conceito, entre outros testes de interesse da Administração, de modo a comprovar sua aderência às especificações definidas no termo de referência ou no projeto básico."},{"k":"par","r":"§ 4º","t":"Nos procedimentos realizados por meio eletrônico, a Administração poderá determinar, como condição de validade e eficácia, que os licitantes pratiquem seus atos em formato eletrônico."},{"k":"par","r":"§ 5º","t":"Na hipótese excepcional de licitação sob a forma presencial a que refere o § 2º deste artigo, a sessão pública de apresentação de propostas deverá ser gravada em áudio e vídeo, e a gravação será juntada aos autos do processo licitatório depois de seu encerramento."},{"k":"par","r":"§ 6º","t":"A Administração poderá exigir certificação por organização independente acreditada pelo Instituto Nacional de Metrologia, Qualidade e Tecnologia (Inmetro) como condição para aceitação de:"},{"k":"inc","r":"I","t":"estudos, anteprojetos, projetos básicos e projetos executivos;"},{"k":"inc","r":"II","t":"conclusão de fases ou de objetos de contratos;"},{"k":"inc","r":"III","t":"material e corpo técnico apresentados por empresa para fins de habilitação."}]},{"k":"cap","t":"CAPÍTULO II","s":"DA FASE PREPARATÓRIA"},{"k":"sec","t":"Seção I","s":"Da Instrução do Processo Licitatório"},{"k":"art","n":"18","id":"a18","p":[{"k":"cap","r":"","t":"A fase preparatória do processo licitatório é caracterizada pelo planejamento e deve compatibilizar-se com o plano de contratações anual de que trata o inciso VII do caput do art. 12 desta Lei, sempre que elaborado, e com as leis orçamentárias, bem como abordar todas as considerações técnicas, mercadológicas e de gestão que podem interferir na contratação, compreendidos:"},{"k":"inc","r":"I","t":"a descrição da necessidade da contratação fundamentada em estudo técnico preliminar que caracterize o interesse público envolvido;"},{"k":"inc","r":"II","t":"a definição do objeto para o atendimento da necessidade, por meio de termo de referência, anteprojeto, projeto básico ou projeto executivo, conforme o caso;"},{"k":"inc","r":"III","t":"a definição das condições de execução e pagamento, das garantias exigidas e ofertadas e das condições de recebimento;"},{"k":"inc","r":"IV","t":"o orçamento estimado, com as composições dos preços utilizados para sua formação;"},{"k":"inc","r":"V","t":"a elaboração do edital de licitação;"},{"k":"inc","r":"VI","t":"a elaboração de minuta de contrato, quando necessária, que constará obrigatoriamente como anexo do edital de licitação;"},{"k":"inc","r":"VII","t":"o regime de fornecimento de bens, de prestação de serviços ou de execução de obras e serviços de engenharia, observados os potenciais de economia de escala;"},{"k":"inc","r":"VIII","t":"a modalidade de licitação, o critério de julgamento, o modo de disputa e a adequação e eficiência da forma de combinação desses parâmetros, para os fins de seleção da proposta apta a gerar o resultado de contratação mais vantajoso para a Administração Pública, considerado todo o ciclo de vida do objeto;"},{"k":"inc","r":"IX","t":"a motivação circunstanciada das condições do edital, tais como justificativa de exigências de qualificação técnica, mediante indicação das parcelas de maior relevância técnica ou valor significativo do objeto, e de qualificação econômico-financeira, justificativa dos critérios de pontuação e julgamento das propostas técnicas, nas licitações com julgamento por melhor técnica ou técnica e preço, e justificativa das regras pertinentes à participação de empresas em consórcio;"},{"k":"inc","r":"X","t":"a análise dos riscos que possam comprometer o sucesso da licitação e a boa execução contratual;"},{"k":"inc","r":"XI","t":"a motivação sobre o momento da divulgação do orçamento da licitação, observado o art. 24 desta Lei."},{"k":"par","r":"§ 1º","t":"O estudo técnico preliminar a que se refere o inciso I do caput deste artigo deverá evidenciar o problema a ser resolvido e a sua melhor solução, de modo a permitir a avaliação da viabilidade técnica e econômica da contratação, e conterá os seguintes elementos:"},{"k":"inc","r":"I","t":"descrição da necessidade da contratação, considerado o problema a ser resolvido sob a perspectiva do interesse público;"},{"k":"inc","r":"II","t":"demonstração da previsão da contratação no plano de contratações anual, sempre que elaborado, de modo a indicar o seu alinhamento com o planejamento da Administração;"},{"k":"inc","r":"III","t":"requisitos da contratação;"},{"k":"inc","r":"IV","t":"estimativas das quantidades para a contratação, acompanhadas das memórias de cálculo e dos documentos que lhes dão suporte, que considerem interdependências com outras contratações, de modo a possibilitar economia de escala;"},{"k":"inc","r":"V","t":"levantamento de mercado, que consiste na análise das alternativas possíveis, e justificativa técnica e econômica da escolha do tipo de solução a contratar;"},{"k":"inc","r":"VI","t":"estimativa do valor da contratação, acompanhada dos preços unitários referenciais, das memórias de cálculo e dos documentos que lhe dão suporte, que poderão constar de anexo classificado, se a Administração optar por preservar o seu sigilo até a conclusão da licitação;"},{"k":"inc","r":"VII","t":"descrição da solução como um todo, inclusive das exigências relacionadas à manutenção e à assistência técnica, quando for o caso;"},{"k":"inc","r":"VIII","t":"justificativas para o parcelamento ou não da contratação;"},{"k":"inc","r":"IX","t":"demonstrativo dos resultados pretendidos em termos de economicidade e de melhor aproveitamento dos recursos humanos, materiais e financeiros disponíveis;"},{"k":"inc","r":"X","t":"providências a serem adotadas pela Administração previamente à celebração do contrato, inclusive quanto à capacitação de servidores ou de empregados para fiscalização e gestão contratual;"},{"k":"inc","r":"XI","t":"contratações correlatas e/ou interdependentes;"},{"k":"inc","r":"XII","t":"descrição de possíveis impactos ambientais e respectivas medidas mitigadoras, incluídos requisitos de baixo consumo de energia e de outros recursos, bem como logística reversa para desfazimento e reciclagem de bens e refugos, quando aplicável;"},{"k":"inc","r":"XIII","t":"posicionamento conclusivo sobre a adequação da contratação para o atendimento da necessidade a que se destina."},{"k":"par","r":"§ 2º","t":"O estudo técnico preliminar deverá conter ao menos os elementos previstos nos incisos I, IV, VI, VIII e XIII do § 1º deste artigo e, quando não contemplar os demais elementos previstos no referido parágrafo, apresentar as devidas justificativas."},{"k":"par","r":"§ 3º","t":"Em se tratando de estudo técnico preliminar para contratação de obras e serviços comuns de engenharia, se demonstrada a inexistência de prejuízo para a aferição dos padrões de desempenho e qualidade almejados, a especificação do objeto poderá ser realizada apenas em termo de referência ou em projeto básico, dispensada a elaboração de projetos."}]},{"k":"art","n":"19","id":"a19","p":[{"k":"cap","r":"","t":"Os órgãos da Administração com competências regulamentares relativas às atividades de administração de materiais, de obras e serviços e de licitações e contratos deverão:"},{"k":"inc","r":"I","t":"instituir instrumentos que permitam, preferencialmente, a centralização dos procedimentos de aquisição e contratação de bens e serviços;"},{"k":"inc","r":"II","t":"criar catálogo eletrônico de padronização de compras, serviços e obras, admitida a adoção do catálogo do Poder Executivo federal por todos os entes federativos;"},{"k":"inc","r":"III","t":"instituir sistema informatizado de acompanhamento de obras, inclusive com recursos de imagem e vídeo;"},{"k":"inc","r":"IV","t":"instituir, com auxílio dos órgãos de assessoramento jurídico e de controle interno, modelos de minutas de editais, de termos de referência, de contratos padronizados e de outros documentos, admitida a adoção das minutas do Poder Executivo federal por todos os entes federativos;"},{"k":"inc","r":"V","t":"promover a adoção gradativa de tecnologias e processos integrados que permitam a criação, a utilização e a atualização de modelos digitais de obras e serviços de engenharia."},{"k":"par","r":"§ 1º","t":"O catálogo referido no inciso II do caput deste artigo poderá ser utilizado em licitações cujo critério de julgamento seja o de menor preço ou o de maior desconto e conterá toda a documentação e os procedimentos próprios da fase interna de licitações, assim como as especificações dos respectivos objetos, conforme disposto em regulamento."},{"k":"par","r":"§ 2º","t":"A não utilização do catálogo eletrônico de padronização de que trata o inciso II do caput ou dos modelos de minutas de que trata o inciso IV do caput deste artigo deverá ser justificada por escrito e anexada ao respectivo processo licitatório."},{"k":"par","r":"§ 3º","t":"Nas licitações de obras e serviços de engenharia e arquitetura, sempre que adequada ao objeto da licitação, será preferencialmente adotada a Modelagem da Informação da Construção (Building Information Modelling - BIM) ou tecnologias e processos integrados similares ou mais avançados que venham a substituí-la."}]},{"k":"art","n":"20","id":"a20","p":[{"k":"cap","r":"","t":"Os itens de consumo adquiridos para suprir as demandas das estruturas da Administração Pública deverão ser de qualidade comum, não superior à necessária para cumprir as finalidades às quais se destinam, vedada a aquisição de artigos de luxo.","n":["(Vigência)"]},{"k":"par","r":"§ 1º","t":"Os Poderes Executivo, Legislativo e Judiciário definirão em regulamento os limites para o enquadramento dos bens de consumo nas categorias comum e luxo."},{"k":"par","r":"§ 2º","t":"A partir de 180 (cento e oitenta) dias contados da promulgação desta Lei, novas compras de bens de consumo só poderão ser efetivadas com a edição, pela autoridade competente, do regulamento a que se refere o § 1º deste artigo."},{"k":"par","r":"§ 3º","t":"","n":["(VETADO)"],"rev":1}]},{"k":"art","n":"21","id":"a21","p":[{"k":"cap","r":"","t":"A Administração poderá convocar, com antecedência mínima de 8 (oito) dias úteis, audiência pública, presencial ou a distância, na forma eletrônica, sobre licitação que pretenda realizar, com disponibilização prévia de informações pertinentes, inclusive de estudo técnico preliminar e elementos do edital de licitação, e com possibilidade de manifestação de todos os interessados."},{"k":"par","r":"Parágrafo único","t":"A Administração também poderá submeter a licitação a prévia consulta pública, mediante a disponibilização de seus elementos a todos os interessados, que poderão formular sugestões no prazo fixado."}]},{"k":"art","n":"22","id":"a22","p":[{"k":"cap","r":"","t":"O edital poderá contemplar matriz de alocação de riscos entre o contratante e o contratado, hipótese em que o cálculo do valor estimado da contratação poderá considerar taxa de risco compatível com o objeto da licitação e com os riscos atribuídos ao contratado, de acordo com metodologia predefinida pelo ente federativo."},{"k":"par","r":"§ 1º","t":"A matriz de que trata o caput deste artigo deverá promover a alocação eficiente dos riscos de cada contrato e estabelecer a responsabilidade que caiba a cada parte contratante, bem como os mecanismos que afastem a ocorrência do sinistro e mitiguem os seus efeitos, caso este ocorra durante a execução contratual."},{"k":"par","r":"§ 2º","t":"O contrato deverá refletir a alocação realizada pela matriz de riscos, especialmente quanto:"},{"k":"inc","r":"I","t":"às hipóteses de alteração para o restabelecimento da equação econômico-financeira do contrato nos casos em que o sinistro seja considerado na matriz de riscos como causa de desequilíbrio não suportada pela parte que pretenda o restabelecimento;"},{"k":"inc","r":"II","t":"à possibilidade de resolução quando o sinistro majorar excessivamente ou impedir a continuidade da execução contratual;"},{"k":"inc","r":"III","t":"à contratação de seguros obrigatórios previamente definidos no contrato, integrado o custo de contratação ao preço ofertado."},{"k":"par","r":"§ 3º","t":"Quando a contratação se referir a obras e serviços de grande vulto ou forem adotados os regimes de contratação integrada e semi-integrada, o edital obrigatoriamente contemplará matriz de alocação de riscos entre o contratante e o contratado."},{"k":"par","r":"§ 4º","t":"Nas contratações integradas ou semi-integradas, os riscos decorrentes de fatos supervenientes à contratação associados à escolha da solução de projeto básico pelo contratado deverão ser alocados como de sua responsabilidade na matriz de riscos."}]},{"k":"art","n":"23","id":"a23","p":[{"k":"cap","r":"","t":"O valor previamente estimado da contratação deverá ser compatível com os valores praticados pelo mercado, considerados os preços constantes de bancos de dados públicos e as quantidades a serem contratadas, observadas a potencial economia de escala e as peculiaridades do local de execução do objeto."},{"k":"par","r":"§ 1º","t":"No processo licitatório para aquisição de bens e contratação de serviços em geral, conforme regulamento, o valor estimado será definido com base no melhor preço aferido por meio da utilização dos seguintes parâmetros, adotados de forma combinada ou não:"},{"k":"inc","r":"I","t":"composição de custos unitários menores ou iguais à mediana do item correspondente no painel para consulta de preços ou no banco de preços em saúde disponíveis no Portal Nacional de Contratações Públicas (PNCP);"},{"k":"inc","r":"II","t":"contratações similares feitas pela Administração Pública, em execução ou concluídas no período de 1 (um) ano anterior à data da pesquisa de preços, inclusive mediante sistema de registro de preços, observado o índice de atualização de preços correspondente;"},{"k":"inc","r":"III","t":"utilização de dados de pesquisa publicada em mídia especializada, de tabela de referência formalmente aprovada pelo Poder Executivo federal e de sítios eletrônicos especializados ou de domínio amplo, desde que contenham a data e hora de acesso;"},{"k":"inc","r":"IV","t":"pesquisa direta com no mínimo 3 (três) fornecedores, mediante solicitação formal de cotação, desde que seja apresentada justificativa da escolha desses fornecedores e que não tenham sido obtidos os orçamentos com mais de 6 (seis) meses de antecedência da data de divulgação do edital;"},{"k":"inc","r":"V","t":"pesquisa na base nacional de notas fiscais eletrônicas, na forma de regulamento."},{"k":"par","r":"§ 2º","t":"No processo licitatório para contratação de obras e serviços de engenharia, conforme regulamento, o valor estimado, acrescido do percentual de Benefícios e Despesas Indiretas (BDI) de referência e dos Encargos Sociais (ES) cabíveis, será definido por meio da utilização de parâmetros na seguinte ordem:"},{"k":"inc","r":"I","t":"composição de custos unitários menores ou iguais à mediana do item correspondente do Sistema de Custos Referenciais de Obras (Sicro), para serviços e obras de infraestrutura de transportes, ou do Sistema Nacional de Pesquisa de Custos e Índices de Construção Civil (Sinapi), para as demais obras e serviços de engenharia;"},{"k":"inc","r":"II","t":"utilização de dados de pesquisa publicada em mídia especializada, de tabela de referência formalmente aprovada pelo Poder Executivo federal e de sítios eletrônicos especializados ou de domínio amplo, desde que contenham a data e a hora de acesso;"},{"k":"inc","r":"III","t":"contratações similares feitas pela Administração Pública, em execução ou concluídas no período de 1 (um) ano anterior à data da pesquisa de preços, observado o índice de atualização de preços correspondente;"},{"k":"inc","r":"IV","t":"pesquisa na base nacional de notas fiscais eletrônicas, na forma de regulamento."},{"k":"par","r":"§ 3º","t":"Nas contratações realizadas por Municípios, Estados e Distrito Federal, desde que não envolvam recursos da União, o valor previamente estimado da contratação, a que se refere o caput deste artigo, poderá ser definido por meio da utilização de outros sistemas de custos adotados pelo respectivo ente federativo."},{"k":"par","r":"§ 4º","t":"Nas contratações diretas por inexigibilidade ou por dispensa, quando não for possível estimar o valor do objeto na forma estabelecida nos §§ 1º, 2º e 3º deste artigo, o contratado deverá comprovar previamente que os preços estão em conformidade com os praticados em contratações semelhantes de objetos de mesma natureza, por meio da apresentação de notas fiscais emitidas para outros contratantes no período de até 1 (um) ano anterior à data da contratação pela Administração, ou por outro meio idôneo."},{"k":"par","r":"§ 5º","t":"No processo licitatório para contratação de obras e serviços de engenharia sob os regimes de contratação integrada ou semi-integrada, o valor estimado da contratação será calculado nos termos do § 2º deste artigo, acrescido ou não de parcela referente à remuneração do risco, e, sempre que necessário e o anteprojeto o permitir, a estimativa de preço será baseada em orçamento sintético, balizado em sistema de custo definido no inciso I do § 2º deste artigo, devendo a utilização de metodologia expedita ou paramétrica e de avaliação aproximada baseada em outras contratações similares ser reservada às frações do empreendimento não suficientemente detalhadas no anteprojeto."},{"k":"par","r":"§ 6º","t":"Na hipótese do § 5º deste artigo, será exigido dos licitantes ou contratados, no orçamento que compuser suas respectivas propostas, no mínimo, o mesmo nível de detalhamento do orçamento sintético referido no mencionado parágrafo."}]},{"k":"art","n":"24","id":"a24","p":[{"k":"cap","r":"","t":"Desde que justificado, o orçamento estimado da contratação poderá ter caráter sigiloso, sem prejuízo da divulgação do detalhamento dos quantitativos e das demais informações necessárias para a elaboração das propostas, e, nesse caso:"},{"k":"inc","r":"I","t":"o sigilo não prevalecerá para os órgãos de controle interno e externo;"},{"k":"inc","r":"II","t":"","n":["(VETADO)"],"rev":1},{"k":"par","r":"Parágrafo único","t":"Na hipótese de licitação em que for adotado o critério de julgamento por maior desconto, o preço estimado ou o máximo aceitável constará do edital da licitação."}]},{"k":"art","n":"25","id":"a25","p":[{"k":"cap","r":"","t":"O edital deverá conter o objeto da licitação e as regras relativas à convocação, ao julgamento, à habilitação, aos recursos e às penalidades da licitação, à fiscalização e à gestão do contrato, à entrega do objeto e às condições de pagamento."},{"k":"par","r":"§ 1º","t":"Sempre que o objeto permitir, a Administração adotará minutas padronizadas de edital e de contrato com cláusulas uniformes."},{"k":"par","r":"§ 2º","t":"Desde que, conforme demonstrado em estudo técnico preliminar, não sejam causados prejuízos à competitividade do processo licitatório e à eficiência do respectivo contrato, o edital poderá prever a utilização de mão de obra, materiais, tecnologias e matérias-primas existentes no local da execução, conservação e operação do bem, serviço ou obra."},{"k":"par","r":"§ 3º","t":"Todos os elementos do edital, incluídos minuta de contrato, termos de referência, anteprojeto, projetos e outros anexos, deverão ser divulgados em sítio eletrônico oficial na mesma data de divulgação do edital, sem necessidade de registro ou de identificação para acesso."},{"k":"par","r":"§ 4º","t":"Nas contratações de obras, serviços e fornecimentos de grande vulto, o edital deverá prever a obrigatoriedade de implantação de programa de integridade pelo licitante vencedor, no prazo de 6 (seis) meses, contado da celebração do contrato, conforme regulamento que disporá sobre as medidas a serem adotadas, a forma de comprovação e as penalidades pelo seu descumprimento.","n":["(Regulamento)"]},{"k":"par","r":"§ 5º","t":"O edital poderá prever a responsabilidade do contratado pela:"},{"k":"inc","r":"I","t":"obtenção do licenciamento ambiental;"},{"k":"inc","r":"II","t":"realização da desapropriação autorizada pelo poder público."},{"k":"par","r":"§ 6º","t":"Os licenciamentos ambientais de obras e serviços de engenharia licitados e contratados nos termos desta Lei terão prioridade de tramitação nos órgãos e entidades integrantes do Sistema Nacional do Meio Ambiente (Sisnama) e deverão ser orientados pelos princípios da celeridade, da cooperação, da economicidade e da eficiência."},{"k":"par","r":"§ 7º","t":"Independentemente do prazo de duração do contrato, será obrigatória a previsão no edital de índice de reajustamento de preço, com data-base vinculada à data do orçamento estimado e com a possibilidade de ser estabelecido mais de um índice específico ou setorial, em conformidade com a realidade de mercado dos respectivos insumos."},{"k":"par","r":"§ 8º","t":"Nas licitações de serviços contínuos, observado o interregno mínimo de 1 (um) ano, o critério de reajustamento será por:"},{"k":"inc","r":"I","t":"reajustamento em sentido estrito, quando não houver regime de dedicação exclusiva de mão de obra ou predominância de mão de obra, mediante previsão de índices específicos ou setoriais;"},{"k":"inc","r":"II","t":"repactuação, quando houver regime de dedicação exclusiva de mão de obra ou predominância de mão de obra, mediante demonstração analítica da variação dos custos."},{"k":"par","r":"§ 9º","t":"O edital poderá, na forma disposta em regulamento, exigir que percentual mínimo da mão de obra responsável pela execução do objeto da contratação seja constituído por:"},{"k":"inc","r":"I","t":"mulheres vítimas de violência doméstica;","n":["(Vide Decreto nº 11.430, de 2023)"]},{"k":"inc","r":"II","t":"oriundos ou egressos do sistema prisional."}]},{"k":"art","n":"26","id":"a26","p":[{"k":"cap","r":"","t":"No processo de licitação, poderá ser estabelecida margem de preferência para:","n":["(Regulamento)"]},{"k":"inc","r":"I","t":"bens manufaturados e serviços nacionais que atendam a normas técnicas brasileiras;"},{"k":"inc","r":"II","t":"bens reciclados, recicláveis ou biodegradáveis, conforme regulamento."},{"k":"par","r":"§ 1º","t":"A margem de preferência de que trata o caput deste artigo:"},{"k":"inc","r":"I","t":"será definida em decisão fundamentada do Poder Executivo federal, no caso do inciso I do caput deste artigo;"},{"k":"inc","r":"II","t":"poderá ser de até 10% (dez por cento) sobre o preço dos bens e serviços que não se enquadrem no disposto nos incisos I ou II do caput deste artigo;"},{"k":"inc","r":"III","t":"poderá ser estendida a bens manufaturados e serviços originários de Estados Partes do Mercado Comum do Sul (Mercosul), desde que haja reciprocidade com o País prevista em acordo internacional aprovado pelo Congresso Nacional e ratificado pelo Presidente da República."},{"k":"par","r":"§ 2º","t":"Para os bens manufaturados nacionais e serviços nacionais resultantes de desenvolvimento e inovação tecnológica no País, definidos conforme regulamento do Poder Executivo federal, a margem de preferência a que se refere o caput deste artigo poderá ser de até 20% (vinte por cento)."},{"k":"par","r":"§ 3º","t":"","n":["(VETADO)"],"rev":1},{"k":"par","r":"§ 4º","t":"","n":["(VETADO)"],"rev":1},{"k":"par","r":"§ 5º","t":"A margem de preferência não se aplica aos bens manufaturados nacionais e aos serviços nacionais se a capacidade de produção desses bens ou de prestação desses serviços no País for inferior:"},{"k":"inc","r":"I","t":"à quantidade a ser adquirida ou contratada; ou"},{"k":"inc","r":"II","t":"aos quantitativos fixados em razão do parcelamento do objeto, quando for o caso."},{"k":"par","r":"§ 6º","t":"Os editais de licitação para a contratação de bens, serviços e obras poderão, mediante prévia justificativa da autoridade competente, exigir que o contratado promova, em favor de órgão ou entidade integrante da Administração Pública ou daqueles por ela indicados a partir de processo isonômico, medidas de compensação comercial, industrial ou tecnológica ou acesso a condições vantajosas de financiamento, cumulativamente ou não, na forma estabelecida pelo Poder Executivo federal."},{"k":"par","r":"§ 7º","t":"Nas contratações destinadas à implantação, à manutenção e ao aperfeiçoamento dos sistemas de tecnologia de informação e comunicação considerados estratégicos em ato do Poder Executivo federal, a licitação poderá ser restrita a bens e serviços com tecnologia desenvolvida no País produzidos de acordo com o processo produtivo básico de que trata a Lei nº 10.176, de 11 de janeiro de 2001."}]},{"k":"art","n":"27","id":"a27","p":[{"k":"cap","r":"","t":"Será divulgada, em sítio eletrônico oficial, a cada exercício financeiro, a relação de empresas favorecidas em decorrência do disposto no art. 26 desta Lei, com indicação do volume de recursos destinados a cada uma delas."}]},{"k":"sec","t":"Seção II","s":"Das Modalidades de Licitação"},{"k":"art","n":"28","id":"a28","p":[{"k":"cap","r":"","t":"São modalidades de licitação:"},{"k":"inc","r":"I","t":"pregão;"},{"k":"inc","r":"II","t":"concorrência;"},{"k":"inc","r":"III","t":"concurso;"},{"k":"inc","r":"IV","t":"leilão;"},{"k":"inc","r":"V","t":"diálogo competitivo."},{"k":"par","r":"§ 1º","t":"Além das modalidades referidas no caput deste artigo, a Administração pode servir-se dos procedimentos auxiliares previstos no art. 78 desta Lei."},{"k":"par","r":"§ 2º","t":"É vedada a criação de outras modalidades de licitação ou, ainda, a combinação daquelas referidas no caput deste artigo."}]},{"k":"art","n":"29","id":"a29","p":[{"k":"cap","r":"","t":"A concorrência e o pregão seguem o rito procedimental comum a que se refere o art. 17 desta Lei, adotando-se o pregão sempre que o objeto possuir padrões de desempenho e qualidade que possam ser objetivamente definidos pelo edital, por meio de especificações usuais de mercado."},{"k":"par","r":"Parágrafo único","t":"O pregão não se aplica às contratações de serviços técnicos especializados de natureza predominantemente intelectual e de obras e serviços de engenharia, exceto os serviços de engenharia de que trata a alínea “a” do inciso XXI do caput do art. 6º desta Lei."}]},{"k":"art","n":"30","id":"a30","p":[{"k":"cap","r":"","t":"O concurso observará as regras e condições previstas em edital, que indicará:"},{"k":"inc","r":"I","t":"a qualificação exigida dos participantes;"},{"k":"inc","r":"II","t":"as diretrizes e formas de apresentação do trabalho;"},{"k":"inc","r":"III","t":"as condições de realização e o prêmio ou remuneração a ser concedida ao vencedor."},{"k":"par","r":"Parágrafo único","t":"Nos concursos destinados à elaboração de projeto, o vencedor deverá ceder à Administração Pública, nos termos do art. 93 desta Lei, todos os direitos patrimoniais relativos ao projeto e autorizar sua execução conforme juízo de conveniência e oportunidade das autoridades competentes."}]},{"k":"art","n":"31","id":"a31","p":[{"k":"cap","r":"","t":"O leilão poderá ser cometido a leiloeiro oficial ou a servidor designado pela autoridade competente da Administração, e regulamento deverá dispor sobre seus procedimentos operacionais."},{"k":"par","r":"§ 1º","t":"Se optar pela realização de leilão por intermédio de leiloeiro oficial, a Administração deverá selecioná-lo mediante credenciamento ou licitação na modalidade pregão e adotar o critério de julgamento de maior desconto para as comissões a serem cobradas, utilizados como parâmetro máximo os percentuais definidos na lei que regula a referida profissão e observados os valores dos bens a serem leiloados."},{"k":"par","r":"§ 2º","t":"O leilão será precedido da divulgação do edital em sítio eletrônico oficial, que conterá:"},{"k":"inc","r":"I","t":"a descrição do bem, com suas características, e, no caso de imóvel, sua situação e suas divisas, com remissão à matrícula e aos registros;"},{"k":"inc","r":"II","t":"o valor pelo qual o bem foi avaliado, o preço mínimo pelo qual poderá ser alienado, as condições de pagamento e, se for o caso, a comissão do leiloeiro designado;"},{"k":"inc","r":"III","t":"a indicação do lugar onde estiverem os móveis, os veículos e os semoventes;"},{"k":"inc","r":"IV","t":"o sítio da internet e o período em que ocorrerá o leilão, salvo se excepcionalmente for realizado sob a forma presencial por comprovada inviabilidade técnica ou desvantagem para a Administração, hipótese em que serão indicados o local, o dia e a hora de sua realização;"},{"k":"inc","r":"V","t":"a especificação de eventuais ônus, gravames ou pendências existentes sobre os bens a serem leiloados."},{"k":"par","r":"§ 3º","t":"Além da divulgação no sítio eletrônico oficial, o edital do leilão será afixado em local de ampla circulação de pessoas na sede da Administração e poderá, ainda, ser divulgado por outros meios necessários para ampliar a publicidade e a competitividade da licitação."},{"k":"par","r":"§ 4º","t":"O leilão não exigirá registro cadastral prévio, não terá fase de habilitação e deverá ser homologado assim que concluída a fase de lances, superada a fase recursal e efetivado o pagamento pelo licitante vencedor, na forma definida no edital."}]},{"k":"art","n":"32","id":"a32","p":[{"k":"cap","r":"","t":"A modalidade diálogo competitivo é restrita a contratações em que a Administração:"},{"k":"inc","r":"I","t":"vise a contratar objeto que envolva as seguintes condições:"},{"k":"ali","r":"a)","t":"inovação tecnológica ou técnica;"},{"k":"ali","r":"b)","t":"impossibilidade de o órgão ou entidade ter sua necessidade satisfeita sem a adaptação de soluções disponíveis no mercado; e"},{"k":"ali","r":"c)","t":"impossibilidade de as especificações técnicas serem definidas com precisão suficiente pela Administração;"},{"k":"inc","r":"II","t":"verifique a necessidade de definir e identificar os meios e as alternativas que possam satisfazer suas necessidades, com destaque para os seguintes aspectos:"},{"k":"ali","r":"a)","t":"a solução técnica mais adequada;"},{"k":"ali","r":"b)","t":"os requisitos técnicos aptos a concretizar a solução já definida;"},{"k":"ali","r":"c)","t":"a estrutura jurídica ou financeira do contrato;"},{"k":"inc","r":"III","t":"","n":["(VETADO)"],"rev":1},{"k":"par","r":"§ 1º","t":"Na modalidade diálogo competitivo, serão observadas as seguintes disposições:"},{"k":"inc","r":"I","t":"a Administração apresentará, por ocasião da divulgação do edital em sítio eletrônico oficial, suas necessidades e as exigências já definidas e estabelecerá prazo mínimo de 25 (vinte e cinco) dias úteis para manifestação de interesse na participação da licitação;"},{"k":"inc","r":"II","t":"os critérios empregados para pré-seleção dos licitantes deverão ser previstos em edital, e serão admitidos todos os interessados que preencherem os requisitos objetivos estabelecidos;"},{"k":"inc","r":"III","t":"a divulgação de informações de modo discriminatório que possa implicar vantagem para algum licitante será vedada;"},{"k":"inc","r":"IV","t":"a Administração não poderá revelar a outros licitantes as soluções propostas ou as informações sigilosas comunicadas por um licitante sem o seu consentimento;"},{"k":"inc","r":"V","t":"a fase de diálogo poderá ser mantida até que a Administração, em decisão fundamentada, identifique a solução ou as soluções que atendam às suas necessidades;"},{"k":"inc","r":"VI","t":"as reuniões com os licitantes pré-selecionados serão registradas em ata e gravadas mediante utilização de recursos tecnológicos de áudio e vídeo;"},{"k":"inc","r":"VII","t":"o edital poderá prever a realização de fases sucessivas, caso em que cada fase poderá restringir as soluções ou as propostas a serem discutidas;"},{"k":"inc","r":"VIII","t":"a Administração deverá, ao declarar que o diálogo foi concluído, juntar aos autos do processo licitatório os registros e as gravações da fase de diálogo, iniciar a fase competitiva com a divulgação de edital contendo a especificação da solução que atenda às suas necessidades e os critérios objetivos a serem utilizados para seleção da proposta mais vantajosa e abrir prazo, não inferior a 60 (sessenta) dias úteis, para todos os licitantes pré-selecionados na forma do inciso II deste parágrafo apresentarem suas propostas, que deverão conter os elementos necessários para a realização do projeto;"},{"k":"inc","r":"IX","t":"a Administração poderá solicitar esclarecimentos ou ajustes às propostas apresentadas, desde que não impliquem discriminação nem distorçam a concorrência entre as propostas;"},{"k":"inc","r":"X","t":"a Administração definirá a proposta vencedora de acordo com critérios divulgados no início da fase competitiva, assegurada a contratação mais vantajosa como resultado;"},{"k":"inc","r":"XI","t":"o diálogo competitivo será conduzido por comissão de contratação composta de pelo menos 3 (três) servidores efetivos ou empregados públicos pertencentes aos quadros permanentes da Administração, admitida a contratação de profissionais para assessoramento técnico da comissão;"},{"k":"inc","r":"XII","t":"","n":["(VETADO)"],"rev":1},{"k":"par","r":"§ 2º","t":"Os profissionais contratados para os fins do inciso XI do § 1º deste artigo assinarão termo de confidencialidade e abster-se-ão de atividades que possam configurar conflito de interesses."}]},{"k":"sec","t":"Seção III","s":"Dos Critérios de Julgamento"},{"k":"art","n":"33","id":"a33","p":[{"k":"cap","r":"","t":"O julgamento das propostas será realizado de acordo com os seguintes critérios:"},{"k":"inc","r":"I","t":"menor preço;"},{"k":"inc","r":"II","t":"maior desconto;"},{"k":"inc","r":"III","t":"melhor técnica ou conteúdo artístico;"},{"k":"inc","r":"IV","t":"técnica e preço;"},{"k":"inc","r":"V","t":"maior lance, no caso de leilão;"},{"k":"inc","r":"VI","t":"maior retorno econômico."}]},{"k":"art","n":"34","id":"a34","p":[{"k":"cap","r":"","t":"O julgamento por menor preço ou maior desconto e, quando couber, por técnica e preço considerará o menor dispêndio para a Administração, atendidos os parâmetros mínimos de qualidade definidos no edital de licitação."},{"k":"par","r":"§ 1º","t":"Os custos indiretos, relacionados com as despesas de manutenção, utilização, reposição, depreciação e impacto ambiental do objeto licitado, entre outros fatores vinculados ao seu ciclo de vida, poderão ser considerados para a definição do menor dispêndio, sempre que objetivamente mensuráveis, conforme disposto em regulamento."},{"k":"par","r":"§ 2º","t":"O julgamento por maior desconto terá como referência o preço global fixado no edital de licitação, e o desconto será estendido aos eventuais termos aditivos."}]},{"k":"art","n":"35","id":"a35","p":[{"k":"cap","r":"","t":"O julgamento por melhor técnica ou conteúdo artístico considerará exclusivamente as propostas técnicas ou artísticas apresentadas pelos licitantes, e o edital deverá definir o prêmio ou a remuneração que será atribuída aos vencedores."},{"k":"par","r":"Parágrafo único","t":"O critério de julgamento de que trata o caput deste artigo poderá ser utilizado para a contratação de projetos e trabalhos de natureza técnica, científica ou artística."}]},{"k":"art","n":"36","id":"a36","p":[{"k":"cap","r":"","t":"O julgamento por técnica e preço considerará a maior pontuação obtida a partir da ponderação, segundo fatores objetivos previstos no edital, das notas atribuídas aos aspectos de técnica e de preço da proposta."},{"k":"par","r":"§ 1º","t":"O critério de julgamento de que trata o caput deste artigo será escolhido quando estudo técnico preliminar demonstrar que a avaliação e a ponderação da qualidade técnica das propostas que superarem os requisitos mínimos estabelecidos no edital forem relevantes aos fins pretendidos pela Administração nas licitações para contratação de:"},{"k":"inc","r":"I","t":"serviços técnicos especializados de natureza predominantemente intelectual, caso em que o critério de julgamento de técnica e preço deverá ser preferencialmente empregado;"},{"k":"inc","r":"II","t":"serviços majoritariamente dependentes de tecnologia sofisticada e de domínio restrito, conforme atestado por autoridades técnicas de reconhecida qualificação;"},{"k":"inc","r":"III","t":"bens e serviços especiais de tecnologia da informação e de comunicação;"},{"k":"inc","r":"IV","t":"obras e serviços especiais de engenharia;"},{"k":"inc","r":"V","t":"objetos que admitam soluções específicas e alternativas e variações de execução, com repercussões significativas e concretamente mensuráveis sobre sua qualidade, produtividade, rendimento e durabilidade, quando essas soluções e variações puderem ser adotadas à livre escolha dos licitantes, conforme critérios objetivamente definidos no edital de licitação."},{"k":"par","r":"§ 2º","t":"No julgamento por técnica e preço, deverão ser avaliadas e ponderadas as propostas técnicas e, em seguida, as propostas de preço apresentadas pelos licitantes, na proporção máxima de 70% (setenta por cento) de valoração para a proposta técnica."},{"k":"par","r":"§ 3º","t":"O desempenho pretérito na execução de contratos com a Administração Pública deverá ser considerado na pontuação técnica, observado o disposto nos §§ 3º e 4º do art. 88 desta Lei e em regulamento."}]},{"k":"art","n":"37","id":"a37","p":[{"k":"cap","r":"","t":"O julgamento por melhor técnica ou por técnica e preço deverá ser realizado por:"},{"k":"inc","r":"I","t":"verificação da capacitação e da experiência do licitante, comprovadas por meio da apresentação de atestados de obras, produtos ou serviços previamente realizados;"},{"k":"inc","r":"II","t":"atribuição de notas a quesitos de natureza qualitativa por banca designada para esse fim, de acordo com orientações e limites definidos em edital, considerados a demonstração de conhecimento do objeto, a metodologia e o programa de trabalho, a qualificação das equipes técnicas e a relação dos produtos que serão entregues;"},{"k":"inc","r":"III","t":"atribuição de notas por desempenho do licitante em contratações anteriores aferida nos documentos comprobatórios de que trata o § 3º do art. 88 desta Lei e em registro cadastral unificado disponível no Portal Nacional de Contratações Públicas (PNCP)."},{"k":"par","r":"§ 1º","t":"A banca referida no inciso II do caput deste artigo terá no mínimo 3 (três) membros e poderá ser composta de:"},{"k":"inc","r":"I","t":"servidores efetivos ou empregados públicos pertencentes aos quadros permanentes da Administração Pública;"},{"k":"inc","r":"II","t":"profissionais contratados por conhecimento técnico, experiência ou renome na avaliação dos quesitos especificados em edital, desde que seus trabalhos sejam supervisionados por profissionais designados conforme o disposto no art. 7º desta Lei."},{"k":"par","r":"§ 2º","t":"Ressalvados os casos de inexigibilidade de licitação, na licitação para contratação dos serviços técnicos especializados de natureza predominantemente intelectual previstos nas alíneas “a”, “d” e “h” do inciso XVIII do caput do art. 6º desta Lei cujo valor estimado da contratação seja superior a R$ 300.000,00 (trezentos mil reais), o julgamento será por:","n":["(Promulgação partes vetadas)","(Vide Decreto nº 12.343, de 2024)","(Vide Decreto nº 12.807, de 2025)"]},{"k":"inc","r":"I","t":"melhor técnica; ou"},{"k":"inc","r":"II","t":"técnica e preço, na proporção de 70% (setenta por cento) de valoração da proposta técnica.”"}]},{"k":"art","n":"38","id":"a38","p":[{"k":"cap","r":"","t":"No julgamento por melhor técnica ou por técnica e preço, a obtenção de pontuação devido à capacitação técnico-profissional exigirá que a execução do respectivo contrato tenha participação direta e pessoal do profissional correspondente."}]},{"k":"art","n":"39","id":"a39","p":[{"k":"cap","r":"","t":"O julgamento por maior retorno econômico, utilizado exclusivamente para a celebração de contrato de eficiência, considerará a maior economia para a Administração, e a remuneração deverá ser fixada em percentual que incidirá de forma proporcional à economia efetivamente obtida na execução do contrato."},{"k":"par","r":"§ 1º","t":"Nas licitações que adotarem o critério de julgamento de que trata o caput deste artigo, os licitantes apresentarão:"},{"k":"inc","r":"I","t":"proposta de trabalho, que deverá contemplar:"},{"k":"ali","r":"a)","t":"as obras, os serviços ou os bens, com os respectivos prazos de realização ou fornecimento;"},{"k":"ali","r":"b)","t":"a economia que se estima gerar, expressa em unidade de medida associada à obra, ao bem ou ao serviço e em unidade monetária;"},{"k":"inc","r":"II","t":"proposta de preço, que corresponderá a percentual sobre a economia que se estima gerar durante determinado período, expressa em unidade monetária."},{"k":"par","r":"§ 2º","t":"O edital de licitação deverá prever parâmetros objetivos de mensuração da economia gerada com a execução do contrato, que servirá de base de cálculo para a remuneração devida ao contratado."},{"k":"par","r":"§ 3º","t":"Para efeito de julgamento da proposta, o retorno econômico será o resultado da economia que se estima gerar com a execução da proposta de trabalho, deduzida a proposta de preço."},{"k":"par","r":"§ 4º","t":"Nos casos em que não for gerada a economia prevista no contrato de eficiência:"},{"k":"inc","r":"I","t":"a diferença entre a economia contratada e a efetivamente obtida será descontada da remuneração do contratado;"},{"k":"inc","r":"II","t":"se a diferença entre a economia contratada e a efetivamente obtida for superior ao limite máximo estabelecido no contrato, o contratado sujeitar-se-á, ainda, a outras sanções cabíveis."}]},{"k":"sec","t":"Seção IV","s":"Disposições Setoriais"},{"k":"sec","t":"Subseção I","s":"Das Compras"},{"k":"art","n":"40","id":"a40","p":[{"k":"cap","r":"","t":"O planejamento de compras deverá considerar a expectativa de consumo anual e observar o seguinte:"},{"k":"inc","r":"I","t":"condições de aquisição e pagamento semelhantes às do setor privado;"},{"k":"inc","r":"II","t":"processamento por meio de sistema de registro de preços, quando pertinente;"},{"k":"inc","r":"III","t":"determinação de unidades e quantidades a serem adquiridas em função de consumo e utilização prováveis, cuja estimativa será obtida, sempre que possível, mediante adequadas técnicas quantitativas, admitido o fornecimento contínuo;"},{"k":"inc","r":"IV","t":"condições de guarda e armazenamento que não permitam a deterioração do material;"},{"k":"inc","r":"V","t":"atendimento aos princípios:"},{"k":"ali","r":"a)","t":"da padronização, considerada a compatibilidade de especificações estéticas, técnicas ou de desempenho;"},{"k":"ali","r":"b)","t":"do parcelamento, quando for tecnicamente viável e economicamente vantajoso;"},{"k":"ali","r":"c)","t":"da responsabilidade fiscal, mediante a comparação da despesa estimada com a prevista no orçamento."},{"k":"par","r":"§ 1º","t":"O termo de referência deverá conter os elementos previstos no inciso XXIII do caput do art. 6º desta Lei, além das seguintes informações:"},{"k":"inc","r":"I","t":"especificação do produto, preferencialmente conforme catálogo eletrônico de padronização, observados os requisitos de qualidade, rendimento, compatibilidade, durabilidade e segurança;"},{"k":"inc","r":"II","t":"indicação dos locais de entrega dos produtos e das regras para recebimentos provisório e definitivo, quando for o caso;"},{"k":"inc","r":"III","t":"especificação da garantia exigida e das condições de manutenção e assistência técnica, quando for o caso."},{"k":"par","r":"§ 2º","t":"Na aplicação do princípio do parcelamento, referente às compras, deverão ser considerados:"},{"k":"inc","r":"I","t":"a viabilidade da divisão do objeto em lotes;"},{"k":"inc","r":"II","t":"o aproveitamento das peculiaridades do mercado local, com vistas à economicidade, sempre que possível, desde que atendidos os parâmetros de qualidade; e"},{"k":"inc","r":"III","t":"o dever de buscar a ampliação da competição e de evitar a concentração de mercado."},{"k":"par","r":"§ 3º","t":"O parcelamento não será adotado quando:"},{"k":"inc","r":"I","t":"a economia de escala, a redução de custos de gestão de contratos ou a maior vantagem na contratação recomendar a compra do item do mesmo fornecedor;"},{"k":"inc","r":"II","t":"o objeto a ser contratado configurar sistema único e integrado e houver a possibilidade de risco ao conjunto do objeto pretendido;"},{"k":"inc","r":"III","t":"o processo de padronização ou de escolha de marca levar a fornecedor exclusivo."},{"k":"par","r":"§ 4º","t":"Em relação à informação de que trata o inciso III do § 1º deste artigo, desde que fundamentada em estudo técnico preliminar, a Administração poderá exigir que os serviços de manutenção e assistência técnica sejam prestados mediante deslocamento de técnico ou disponibilizados em unidade de prestação de serviços localizada em distância compatível com suas necessidades."}]},{"k":"art","n":"41","id":"a41","p":[{"k":"cap","r":"","t":"No caso de licitação que envolva o fornecimento de bens, a Administração poderá excepcionalmente:"},{"k":"inc","r":"I","t":"indicar uma ou mais marcas ou modelos, desde que formalmente justificado, nas seguintes hipóteses:"},{"k":"ali","r":"a)","t":"em decorrência da necessidade de padronização do objeto;"},{"k":"ali","r":"b)","t":"em decorrência da necessidade de manter a compatibilidade com plataformas e padrões já adotados pela Administração;"},{"k":"ali","r":"c)","t":"quando determinada marca ou modelo comercializados por mais de um fornecedor forem os únicos capazes de atender às necessidades do contratante;"},{"k":"ali","r":"d)","t":"quando a descrição do objeto a ser licitado puder ser mais bem compreendida pela identificação de determinada marca ou determinado modelo aptos a servir apenas como referência;"},{"k":"inc","r":"II","t":"exigir amostra ou prova de conceito do bem no procedimento de pré-qualificação permanente, na fase de julgamento das propostas ou de lances, ou no período de vigência do contrato ou da ata de registro de preços, desde que previsto no edital da licitação e justificada a necessidade de sua apresentação;"},{"k":"inc","r":"III","t":"vedar a contratação de marca ou produto, quando, mediante processo administrativo, restar comprovado que produtos adquiridos e utilizados anteriormente pela Administração não atendem a requisitos indispensáveis ao pleno adimplemento da obrigação contratual;"},{"k":"inc","r":"IV","t":"solicitar, motivadamente, carta de solidariedade emitida pelo fabricante, que assegure a execução do contrato, no caso de licitante revendedor ou distribuidor."},{"k":"par","r":"Parágrafo único","t":"A exigência prevista no inciso II do caput deste artigo restringir-se-á ao licitante provisoriamente vencedor quando realizada na fase de julgamento das propostas ou de lances."}]},{"k":"art","n":"42","id":"a42","p":[{"k":"cap","r":"","t":"A prova de qualidade de produto apresentado pelos proponentes como similar ao das marcas eventualmente indicadas no edital será admitida por qualquer um dos seguintes meios:"},{"k":"inc","r":"I","t":"comprovação de que o produto está de acordo com as normas técnicas determinadas pelos órgãos oficiais competentes, pela Associação Brasileira de Normas Técnicas (ABNT) ou por outra entidade credenciada pelo Inmetro;"},{"k":"inc","r":"II","t":"declaração de atendimento satisfatório emitida por outro órgão ou entidade de nível federativo equivalente ou superior que tenha adquirido o produto;"},{"k":"inc","r":"III","t":"certificação, certificado, laudo laboratorial ou documento similar que possibilite a aferição da qualidade e da conformidade do produto ou do processo de fabricação, inclusive sob o aspecto ambiental, emitido por instituição oficial competente ou por entidade credenciada."},{"k":"par","r":"§ 1º","t":"O edital poderá exigir, como condição de aceitabilidade da proposta, certificação de qualidade do produto por instituição credenciada pelo Conselho Nacional de Metrologia, Normalização e Qualidade Industrial (Conmetro)."},{"k":"par","r":"§ 2º","t":"A Administração poderá, nos termos do edital de licitação, oferecer protótipo do objeto pretendido e exigir, na fase de julgamento das propostas, amostras do licitante provisoriamente vencedor, para atender a diligência ou, após o julgamento, como condição para firmar contrato."},{"k":"par","r":"§ 3º","t":"No interesse da Administração, as amostras a que se refere o § 2º deste artigo poderão ser examinadas por instituição com reputação ético-profissional na especialidade do objeto, previamente indicada no edital."}]},{"k":"art","n":"43","id":"a43","p":[{"k":"cap","r":"","t":"O processo de padronização deverá conter:"},{"k":"inc","r":"I","t":"parecer técnico sobre o produto, considerados especificações técnicas e estéticas, desempenho, análise de contratações anteriores, custo e condições de manutenção e garantia;"},{"k":"inc","r":"II","t":"despacho motivado da autoridade superior, com a adoção do padrão;"},{"k":"inc","r":"III","t":"síntese da justificativa e descrição sucinta do padrão definido, divulgadas em sítio eletrônico oficial."},{"k":"par","r":"§ 1º","t":"É permitida a padronização com base em processo de outro órgão ou entidade de nível federativo igual ou superior ao do órgão adquirente, devendo o ato que decidir pela adesão a outra padronização ser devidamente motivado, com indicação da necessidade da Administração e dos riscos decorrentes dessa decisão, e divulgado em sítio eletrônico oficial."},{"k":"par","r":"§ 2º","t":"As contratações de soluções baseadas em software de uso disseminado serão disciplinadas em regulamento que defina processo de gestão estratégica das contratações desse tipo de solução."}]},{"k":"art","n":"44","id":"a44","p":[{"k":"cap","r":"","t":"Quando houver a possibilidade de compra ou de locação de bens, o estudo técnico preliminar deverá considerar os custos e os benefícios de cada opção, com indicação da alternativa mais vantajosa."}]},{"k":"art","n":"44-A","id":"a44A","p":[{"k":"cap","r":"","t":"O processo licitatório para compra de equipamento destinado a procedimento diagnóstico ou terapêutico no âmbito do Sistema Único de Saúde (SUS) que tenha valor superior ao previsto no inciso II do art. 75 desta Lei deve levar em consideração o seu adequado aproveitamento ao longo de sua vida útil.","n":["(Incluído pela Lei nº 15.210, de 2025)"]},{"k":"par","r":"§ 1º","t":"No edital de licitação, deve constar a demonstração da capacidade instalada para operação do equipamento ou o plano de atendimento aos requisitos necessários à operação.","n":["(Incluído pela Lei nº 15.210, de 2025)"]},{"k":"par","r":"§ 2º","t":"","n":["(VETADO)","(Incluído pela Lei nº 15.210, de 2025)"],"rev":1},{"k":"par","r":"§ 3º","t":"","n":["(VETADO)","(Incluído pela Lei nº 15.210, de 2025)"],"rev":1},{"k":"par","r":"§ 4º","t":"","n":["(VETADO)","(Incluído pela Lei nº 15.210, de 2025)"],"rev":1},{"k":"par","r":"§ 5º","t":"","n":["(VETADO)","(Incluído pela Lei nº 15.210, de 2025)"],"rev":1}]},{"k":"sec","t":"Subseção II","s":"Das Obras e Serviços de Engenharia"},{"k":"art","n":"45","id":"a45","p":[{"k":"cap","r":"","t":"As licitações de obras e serviços de engenharia devem respeitar, especialmente, as normas relativas a:"},{"k":"inc","r":"I","t":"disposição final ambientalmente adequada dos resíduos sólidos gerados pelas obras contratadas;"},{"k":"inc","r":"II","t":"mitigação por condicionantes e compensação ambiental, que serão definidas no procedimento de licenciamento ambiental;"},{"k":"inc","r":"III","t":"utilização de produtos, de equipamentos e de serviços que, comprovadamente, favoreçam a redução do consumo de energia e de recursos naturais;"},{"k":"inc","r":"IV","t":"avaliação de impacto de vizinhança, na forma da legislação urbanística;"},{"k":"inc","r":"V","t":"proteção do patrimônio histórico, cultural, arqueológico e imaterial, inclusive por meio da avaliação do impacto direto ou indireto causado pelas obras contratadas;"},{"k":"inc","r":"VI","t":"acessibilidade para pessoas com deficiência ou com mobilidade reduzida."}]},{"k":"art","n":"46","id":"a46","p":[{"k":"cap","r":"","t":"Na execução indireta de obras e serviços de engenharia, são admitidos os seguintes regimes:"},{"k":"inc","r":"I","t":"empreitada por preço unitário;"},{"k":"inc","r":"II","t":"empreitada por preço global;"},{"k":"inc","r":"III","t":"empreitada integral;"},{"k":"inc","r":"IV","t":"contratação por tarefa;"},{"k":"inc","r":"V","t":"contratação integrada;"},{"k":"inc","r":"VI","t":"contratação semi-integrada;"},{"k":"inc","r":"VII","t":"fornecimento e prestação de serviço associado."},{"k":"par","r":"§ 1º","t":"É vedada a realização de obras e serviços de engenharia sem projeto executivo, ressalvada a hipótese prevista no § 3º do art. 18 desta Lei."},{"k":"par","r":"§ 2º","t":"A Administração é dispensada da elaboração de projeto básico nos casos de contratação integrada, hipótese em que deverá ser elaborado anteprojeto de acordo com metodologia definida em ato do órgão competente, observados os requisitos estabelecidos no inciso XXIV do art. 6º desta Lei."},{"k":"par","r":"§ 3º","t":"Na contratação integrada, após a elaboração do projeto básico pelo contratado, o conjunto de desenhos, especificações, memoriais e cronograma físico-financeiro deverá ser submetido à aprovação da Administração, que avaliará sua adequação em relação aos parâmetros definidos no edital e conformidade com as normas técnicas, vedadas alterações que reduzam a qualidade ou a vida útil do empreendimento e mantida a responsabilidade integral do contratado pelos riscos associados ao projeto básico."},{"k":"par","r":"§ 4º","t":"Nos regimes de contratação integrada e semi-integrada, o edital e o contrato, sempre que for o caso, deverão prever as providências necessárias para a efetivação de desapropriação autorizada pelo poder público, bem como:"},{"k":"inc","r":"I","t":"o responsável por cada fase do procedimento expropriatório;"},{"k":"inc","r":"II","t":"a responsabilidade pelo pagamento das indenizações devidas;"},{"k":"inc","r":"III","t":"a estimativa do valor a ser pago a título de indenização pelos bens expropriados, inclusive de custos correlatos;"},{"k":"inc","r":"IV","t":"a distribuição objetiva de riscos entre as partes, incluído o risco pela diferença entre o custo da desapropriação e a estimativa de valor e pelos eventuais danos e prejuízos ocasionados por atraso na disponibilização dos bens expropriados;"},{"k":"inc","r":"V","t":"em nome de quem deverá ser promovido o registro de imissão provisória na posse e o registro de propriedade dos bens a serem desapropriados."},{"k":"par","r":"§ 5º","t":"Na contratação semi-integrada, mediante prévia autorização da Administração, o projeto básico poderá ser alterado, desde que demonstrada a superioridade das inovações propostas pelo contratado em termos de redução de custos, de aumento da qualidade, de redução do prazo de execução ou de facilidade de manutenção ou operação, assumindo o contratado a responsabilidade integral pelos riscos associados à alteração do projeto básico."},{"k":"par","r":"§ 6º","t":"A execução de cada etapa será obrigatoriamente precedida da conclusão e da aprovação, pela autoridade competente, dos trabalhos relativos às etapas anteriores."},{"k":"par","r":"§ 7º","t":"","n":["(VETADO)"],"rev":1},{"k":"par","r":"§ 8º","t":"","n":["(VETADO)"],"rev":1},{"k":"par","r":"§ 9º","t":"Os regimes de execução a que se referem os incisos II, III, IV, V e VI do caput deste artigo serão licitados por preço global e adotarão sistemática de medição e pagamento associada à execução de etapas do cronograma físico-financeiro vinculadas ao cumprimento de metas de resultado, vedada a adoção de sistemática de remuneração orientada por preços unitários ou referenciada pela execução de quantidades de itens unitários."}]},{"k":"sec","t":"Subseção III","s":"Dos Serviços em Geral"},{"k":"art","n":"47","id":"a47","p":[{"k":"cap","r":"","t":"As licitações de serviços atenderão aos princípios:"},{"k":"inc","r":"I","t":"da padronização, considerada a compatibilidade de especificações estéticas, técnicas ou de desempenho;"},{"k":"inc","r":"II","t":"do parcelamento, quando for tecnicamente viável e economicamente vantajoso."},{"k":"par","r":"§ 1º","t":"Na aplicação do princípio do parcelamento deverão ser considerados:"},{"k":"inc","r":"I","t":"a responsabilidade técnica;"},{"k":"inc","r":"II","t":"o custo para a Administração de vários contratos frente às vantagens da redução de custos, com divisão do objeto em itens;"},{"k":"inc","r":"III","t":"o dever de buscar a ampliação da competição e de evitar a concentração de mercado."},{"k":"par","r":"§ 2º","t":"Na licitação de serviços de manutenção e assistência técnica, o edital deverá definir o local de realização dos serviços, admitida a exigência de deslocamento de técnico ao local da repartição ou a exigência de que o contratado tenha unidade de prestação de serviços em distância compatível com as necessidades da Administração."}]},{"k":"art","n":"48","id":"a48","p":[{"k":"cap","r":"","t":"Poderão ser objeto de execução por terceiros as atividades materiais acessórias, instrumentais ou complementares aos assuntos que constituam área de competência legal do órgão ou da entidade, vedado à Administração ou a seus agentes, na contratação do serviço terceirizado:"},{"k":"inc","r":"I","t":"indicar pessoas expressamente nominadas para executar direta ou indiretamente o objeto contratado;"},{"k":"inc","r":"II","t":"fixar salário inferior ao definido em lei ou em ato normativo a ser pago pelo contratado;"},{"k":"inc","r":"III","t":"estabelecer vínculo de subordinação com funcionário de empresa prestadora de serviço terceirizado;"},{"k":"inc","r":"IV","t":"definir forma de pagamento mediante exclusivo reembolso dos salários pagos;"},{"k":"inc","r":"V","t":"demandar a funcionário de empresa prestadora de serviço terceirizado a execução de tarefas fora do escopo do objeto da contratação;"},{"k":"inc","r":"VI","t":"prever em edital exigências que constituam intervenção indevida da Administração na gestão interna do contratado."},{"k":"par","r":"Parágrafo único","t":"Durante a vigência do contrato, é vedado ao contratado contratar cônjuge, companheiro ou parente em linha reta, colateral ou por afinidade, até o terceiro grau, de dirigente do órgão ou entidade contratante ou de agente público que desempenhe função na licitação ou atue na fiscalização ou na gestão do contrato, devendo essa proibição constar expressamente do edital de licitação."}]},{"k":"art","n":"49","id":"a49","p":[{"k":"cap","r":"","t":"A Administração poderá, mediante justificativa expressa, contratar mais de uma empresa ou instituição para executar o mesmo serviço, desde que essa contratação não implique perda de economia de escala, quando:"},{"k":"inc","r":"I","t":"o objeto da contratação puder ser executado de forma concorrente e simultânea por mais de um contratado; e"},{"k":"inc","r":"II","t":"a múltipla execução for conveniente para atender à Administração."},{"k":"par","r":"Parágrafo único","t":"Na hipótese prevista no caput deste artigo, a Administração deverá manter o controle individualizado da execução do objeto contratual relativamente a cada um dos contratados."}]},{"k":"art","n":"50","id":"a50","p":[{"k":"cap","r":"","t":"Nas contratações de serviços com regime de dedicação exclusiva de mão de obra, o contratado deverá apresentar, quando solicitado pela Administração, sob pena de multa, comprovação do cumprimento das obrigações trabalhistas e com o Fundo de Garantia do Tempo de Serviço (FGTS) em relação aos empregados diretamente envolvidos na execução do contrato, em especial quanto ao:"},{"k":"inc","r":"I","t":"registro de ponto;"},{"k":"inc","r":"II","t":"recibo de pagamento de salários, adicionais, horas extras, repouso semanal remunerado e décimo terceiro salário;"},{"k":"inc","r":"III","t":"comprovante de depósito do FGTS;"},{"k":"inc","r":"IV","t":"recibo de concessão e pagamento de férias e do respectivo adicional;"},{"k":"inc","r":"V","t":"recibo de quitação de obrigações trabalhistas e previdenciárias dos empregados dispensados até a data da extinção do contrato;"},{"k":"inc","r":"VI","t":"recibo de pagamento de vale-transporte e vale-alimentação, na forma prevista em norma coletiva."}]},{"k":"sec","t":"Subseção IV","s":"Da Locação de Imóveis"},{"k":"art","n":"51","id":"a51","p":[{"k":"cap","r":"","t":"Ressalvado o disposto no inciso V do caput do art. 74 desta Lei, a locação de imóveis deverá ser precedida de licitação e avaliação prévia do bem, do seu estado de conservação, dos custos de adaptações e do prazo de amortização dos investimentos necessários."}]},{"k":"sec","t":"Subseção V","s":"Das Licitações Internacionais"},{"k":"art","n":"52","id":"a52","p":[{"k":"cap","r":"","t":"Nas licitações de âmbito internacional, o edital deverá ajustar-se às diretrizes da política monetária e do comércio exterior e atender às exigências dos órgãos competentes."},{"k":"par","r":"§ 1º","t":"Quando for permitido ao licitante estrangeiro cotar preço em moeda estrangeira, o licitante brasileiro igualmente poderá fazê-lo."},{"k":"par","r":"§ 2º","t":"O pagamento feito ao licitante brasileiro eventualmente contratado em virtude de licitação nas condições de que trata o § 1º deste artigo será efetuado em moeda corrente nacional."},{"k":"par","r":"§ 3º","t":"As garantias de pagamento ao licitante brasileiro serão equivalentes àquelas oferecidas ao licitante estrangeiro."},{"k":"par","r":"§ 4º","t":"Os gravames incidentes sobre os preços constarão do edital e serão definidos a partir de estimativas ou médias dos tributos."},{"k":"par","r":"§ 5º","t":"As propostas de todos os licitantes estarão sujeitas às mesmas regras e condições, na forma estabelecida no edital."},{"k":"par","r":"§ 6º","t":"Observados os termos desta Lei, o edital não poderá prever condições de habilitação, classificação e julgamento que constituam barreiras de acesso ao licitante estrangeiro, admitida a previsão de margem de preferência para bens produzidos no País e serviços nacionais que atendam às normas técnicas brasileiras, na forma definida no art. 26 desta Lei."}]},{"k":"cap","t":"CAPÍTULO III","s":"DA DIVULGAÇÃO DO EDITAL DE LICITAÇÃO"},{"k":"art","n":"53","id":"a53","p":[{"k":"cap","r":"","t":"Ao final da fase preparatória, o processo licitatório seguirá para o órgão de assessoramento jurídico da Administração, que realizará controle prévio de legalidade mediante análise jurídica da contratação."},{"k":"par","r":"§ 1º","t":"Na elaboração do parecer jurídico, o órgão de assessoramento jurídico da Administração deverá:"},{"k":"inc","r":"I","t":"apreciar o processo licitatório conforme critérios objetivos prévios de atribuição de prioridade;"},{"k":"inc","r":"II","t":"redigir sua manifestação em linguagem simples e compreensível e de forma clara e objetiva, com apreciação de todos os elementos indispensáveis à contratação e com exposição dos pressupostos de fato e de direito levados em consideração na análise jurídica;"},{"k":"inc","r":"III","t":"","n":["(VETADO)"],"rev":1},{"k":"par","r":"§ 2º","t":"","n":["(VETADO)"],"rev":1},{"k":"par","r":"§ 3º","t":"Encerrada a instrução do processo sob os aspectos técnico e jurídico, a autoridade determinará a divulgação do edital de licitação conforme disposto no art. 54."},{"k":"par","r":"§ 4º","t":"Na forma deste artigo, o órgão de assessoramento jurídico da Administração também realizará controle prévio de legalidade de contratações diretas, acordos, termos de cooperação, convênios, ajustes, adesões a atas de registro de preços, outros instrumentos congêneres e de seus termos aditivos."},{"k":"par","r":"§ 5º","t":"É dispensável a análise jurídica nas hipóteses previamente definidas em ato da autoridade jurídica máxima competente, que deverá considerar o baixo valor, a baixa complexidade da contratação, a entrega imediata do bem ou a utilização de minutas de editais e instrumentos de contrato, convênio ou outros ajustes previamente padronizados pelo órgão de assessoramento jurídico."},{"k":"par","r":"§ 6º","t":"","n":["(VETADO)"],"rev":1}]},{"k":"art","n":"54","id":"a54","p":[{"k":"cap","r":"","t":"A publicidade do edital de licitação será realizada mediante divulgação e manutenção do inteiro teor do ato convocatório e de seus anexos no Portal Nacional de Contratações Públicas (PNCP)."},{"k":"par","r":"§ 1º","t":"Sem prejuízo do disposto no caput, é obrigatória a publicação de extrato do edital no Diário Oficial da União, do Estado, do Distrito Federal ou do Município, ou, no caso de consórcio público, do ente de maior nível entre eles, bem como em jornal diário de grande circulação.","n":["(Promulgação partes vetadas)"]},{"k":"par","r":"§ 2º","t":"É facultada a divulgação adicional e a manutenção do inteiro teor do edital e de seus anexos em sítio eletrônico oficial do ente federativo do órgão ou entidade responsável pela licitação ou, no caso de consórcio público, do ente de maior nível entre eles, admitida, ainda, a divulgação direta a interessados devidamente cadastrados para esse fim."},{"k":"par","r":"§ 3º","t":"Após a homologação do processo licitatório, serão disponibilizados no Portal Nacional de Contratações Públicas (PNCP) e, se o órgão ou entidade responsável pela licitação entender cabível, também no sítio referido no § 2º deste artigo, os documentos elaborados na fase preparatória que porventura não tenham integrado o edital e seus anexos."}]},{"k":"cap","t":"CAPÍTULO IV","s":"DA APRESENTAÇÃO DE PROPOSTAS E LANCES"},{"k":"art","n":"55","id":"a55","p":[{"k":"cap","r":"","t":"Os prazos mínimos para apresentação de propostas e lances, contados a partir da data de divulgação do edital de licitação, são de:"},{"k":"inc","r":"I","t":"para aquisição de bens:"},{"k":"ali","r":"a)","t":"8 (oito) dias úteis, quando adotados os critérios de julgamento de menor preço ou de maior desconto;"},{"k":"ali","r":"b)","t":"15 (quinze) dias úteis, nas hipóteses não abrangidas pela alínea “a” deste inciso;"},{"k":"inc","r":"II","t":"no caso de serviços e obras:"},{"k":"ali","r":"a)","t":"10 (dez) dias úteis, quando adotados os critérios de julgamento de menor preço ou de maior desconto, no caso de serviços comuns e de obras e serviços comuns de engenharia;"},{"k":"ali","r":"b)","t":"25 (vinte e cinco) dias úteis, quando adotados os critérios de julgamento de menor preço ou de maior desconto, no caso de serviços especiais e de obras e serviços especiais de engenharia;"},{"k":"ali","r":"c)","t":"60 (sessenta) dias úteis, quando o regime de execução for de contratação integrada;"},{"k":"ali","r":"d)","t":"35 (trinta e cinco) dias úteis, quando o regime de execução for o de contratação semi-integrada ou nas hipóteses não abrangidas pelas alíneas “a”, “b” e “c” deste inciso;"},{"k":"inc","r":"III","t":"para licitação em que se adote o critério de julgamento de maior lance, 15 (quinze) dias úteis;"},{"k":"inc","r":"IV","t":"para licitação em que se adote o critério de julgamento de técnica e preço ou de melhor técnica ou conteúdo artístico, 35 (trinta e cinco) dias úteis.","n":["(Regulamento)"]},{"k":"par","r":"§ 1º","t":"Eventuais modificações no edital implicarão nova divulgação na mesma forma de sua divulgação inicial, além do cumprimento dos mesmos prazos dos atos e procedimentos originais, exceto quando a alteração não comprometer a formulação das propostas."},{"k":"par","r":"§ 2º","t":"Os prazos previstos neste artigo poderão, mediante decisão fundamentada, ser reduzidos até a metade nas licitações realizadas pelo Ministério da Saúde, no âmbito do Sistema Único de Saúde (SUS)."}]},{"k":"art","n":"56","id":"a56","p":[{"k":"cap","r":"","t":"O modo de disputa poderá ser, isolada ou conjuntamente:"},{"k":"inc","r":"I","t":"aberto, hipótese em que os licitantes apresentarão suas propostas por meio de lances públicos e sucessivos, crescentes ou decrescentes;"},{"k":"inc","r":"II","t":"fechado, hipótese em que as propostas permanecerão em sigilo até a data e hora designadas para sua divulgação."},{"k":"par","r":"§ 1º","t":"A utilização isolada do modo de disputa fechado será vedada quando adotados os critérios de julgamento de menor preço ou de maior desconto."},{"k":"par","r":"§ 2º","t":"A utilização do modo de disputa aberto será vedada quando adotado o critério de julgamento de técnica e preço."},{"k":"par","r":"§ 3º","t":"Serão considerados intermediários os lances:"},{"k":"inc","r":"I","t":"iguais ou inferiores ao maior já ofertado, quando adotado o critério de julgamento de maior lance;"},{"k":"inc","r":"II","t":"iguais ou superiores ao menor já ofertado, quando adotados os demais critérios de julgamento."},{"k":"par","r":"§ 4º","t":"Após a definição da melhor proposta, se a diferença em relação à proposta classificada em segundo lugar for de pelo menos 5% (cinco por cento), a Administração poderá admitir o reinício da disputa aberta, nos termos estabelecidos no instrumento convocatório, para a definição das demais colocações."},{"k":"par","r":"§ 5º","t":"Nas licitações de obras ou serviços de engenharia, após o julgamento, o licitante vencedor deverá reelaborar e apresentar à Administração, por meio eletrônico, as planilhas com indicação dos quantitativos e dos custos unitários, bem como com detalhamento das Bonificações e Despesas Indiretas (BDI) e dos Encargos Sociais (ES), com os respectivos valores adequados ao valor final da proposta vencedora, admitida a utilização dos preços unitários, no caso de empreitada por preço global, empreitada integral, contratação semi-integrada e contratação integrada, exclusivamente para eventuais adequações indispensáveis no cronograma físico-financeiro e para balizar excepcional aditamento posterior do contrato."}]},{"k":"art","n":"57","id":"a57","p":[{"k":"cap","r":"","t":"O edital de licitação poderá estabelecer intervalo mínimo de diferença de valores entre os lances, que incidirá tanto em relação aos lances intermediários quanto em relação à proposta que cobrir a melhor oferta."}]},{"k":"art","n":"58","id":"a58","p":[{"k":"cap","r":"","t":"Poderá ser exigida, no momento da apresentação da proposta, a comprovação do recolhimento de quantia a título de garantia de proposta, como requisito de pré-habilitação."},{"k":"par","r":"§ 1º","t":"A garantia de proposta não poderá ser superior a 1% (um por cento) do valor estimado para a contratação."},{"k":"par","r":"§ 2º","t":"A garantia de proposta será devolvida aos licitantes no prazo de 10 (dez) dias úteis, contado da assinatura do contrato ou da data em que for declarada fracassada a licitação."},{"k":"par","r":"§ 3º","t":"Implicará execução do valor integral da garantia de proposta a recusa em assinar o contrato ou a não apresentação dos documentos para a contratação."},{"k":"par","r":"§ 4º","t":"A garantia de proposta poderá ser prestada nas modalidades de que trata o § 1º do art. 96 desta Lei."}]},{"k":"cap","t":"CAPÍTULO V","s":"DO JULGAMENTO"},{"k":"art","n":"59","id":"a59","p":[{"k":"cap","r":"","t":"Serão desclassificadas as propostas que:"},{"k":"inc","r":"I","t":"contiverem vícios insanáveis;"},{"k":"inc","r":"II","t":"não obedecerem às especificações técnicas pormenorizadas no edital;"},{"k":"inc","r":"III","t":"apresentarem preços inexequíveis ou permanecerem acima do orçamento estimado para a contratação;"},{"k":"inc","r":"IV","t":"não tiverem sua exequibilidade demonstrada, quando exigido pela Administração;"},{"k":"inc","r":"V","t":"apresentarem desconformidade com quaisquer outras exigências do edital, desde que insanável."},{"k":"par","r":"§ 1º","t":"A verificação da conformidade das propostas poderá ser feita exclusivamente em relação à proposta mais bem classificada."},{"k":"par","r":"§ 2º","t":"A Administração poderá realizar diligências para aferir a exequibilidade das propostas ou exigir dos licitantes que ela seja demonstrada, conforme disposto no inciso IV do caput deste artigo."},{"k":"par","r":"§ 3º","t":"No caso de obras e serviços de engenharia e arquitetura, para efeito de avaliação da exequibilidade e de sobrepreço, serão considerados o preço global, os quantitativos e os preços unitários tidos como relevantes, observado o critério de aceitabilidade de preços unitário e global a ser fixado no edital, conforme as especificidades do mercado correspondente."},{"k":"par","r":"§ 4º","t":"No caso de obras e serviços de engenharia, serão consideradas inexequíveis as propostas cujos valores forem inferiores a 75% (setenta e cinco por cento) do valor orçado pela Administração."},{"k":"par","r":"§ 5º","t":"Nas contratações de obras e serviços de engenharia, será exigida garantia adicional do licitante vencedor cuja proposta for inferior a 85% (oitenta e cinco por cento) do valor orçado pela Administração, equivalente à diferença entre este último e o valor da proposta, sem prejuízo das demais garantias exigíveis de acordo com esta Lei."}]},{"k":"art","n":"60","id":"a60","p":[{"k":"cap","r":"","t":"Em caso de empate entre duas ou mais propostas, serão utilizados os seguintes critérios de desempate, nesta ordem:"},{"k":"inc","r":"I","t":"disputa final, hipótese em que os licitantes empatados poderão apresentar nova proposta em ato contínuo à classificação;"},{"k":"inc","r":"II","t":"avaliação do desempenho contratual prévio dos licitantes, para a qual deverão preferencialmente ser utilizados registros cadastrais para efeito de atesto de cumprimento de obrigações previstos nesta Lei;"},{"k":"inc","r":"III","t":"desenvolvimento pelo licitante de ações de equidade entre homens e mulheres no ambiente de trabalho, conforme regulamento;","n":["(Vide Decreto nº 11.430, de 2023)"]},{"k":"inc","r":"IV","t":"desenvolvimento pelo licitante de programa de integridade, conforme orientações dos órgãos de controle."},{"k":"par","r":"§ 1º","t":"Em igualdade de condições, se não houver desempate, será assegurada preferência, sucessivamente, aos bens e serviços produzidos ou prestados por:"},{"k":"inc","r":"I","t":"empresas estabelecidas no território do Estado ou do Distrito Federal do órgão ou entidade da Administração Pública estadual ou distrital licitante ou, no caso de licitação realizada por órgão ou entidade de Município, no território do Estado em que este se localize;"},{"k":"inc","r":"II","t":"empresas brasileiras;"},{"k":"inc","r":"III","t":"empresas que invistam em pesquisa e no desenvolvimento de tecnologia no País;"},{"k":"inc","r":"IV","t":"empresas que comprovem a prática de mitigação, nos termos da Lei nº 12.187, de 29 de dezembro de 2009."},{"k":"par","r":"§ 2º","t":"As regras previstas no caput deste artigo não prejudicarão a aplicação do disposto no art. 44 da Lei Complementar nº 123, de 14 de dezembro de 2006."}]},{"k":"art","n":"61","id":"a61","p":[{"k":"cap","r":"","t":"Definido o resultado do julgamento, a Administração poderá negociar condições mais vantajosas com o primeiro colocado."},{"k":"par","r":"§ 1º","t":"A negociação poderá ser feita com os demais licitantes, segundo a ordem de classificação inicialmente estabelecida, quando o primeiro colocado, mesmo após a negociação, for desclassificado em razão de sua proposta permanecer acima do preço máximo definido pela Administração."},{"k":"par","r":"§ 2º","t":"A negociação será conduzida por agente de contratação ou comissão de contratação, na forma de regulamento, e, depois de concluída, terá seu resultado divulgado a todos os licitantes e anexado aos autos do processo licitatório."}]},{"k":"cap","t":"CAPÍTULO VI","s":"DA HABILITAÇÃO"},{"k":"art","n":"62","id":"a62","p":[{"k":"cap","r":"","t":"A habilitação é a fase da licitação em que se verifica o conjunto de informações e documentos necessários e suficientes para demonstrar a capacidade do licitante de realizar o objeto da licitação, dividindo-se em:"},{"k":"inc","r":"I","t":"jurídica;"},{"k":"inc","r":"II","t":"técnica;"},{"k":"inc","r":"III","t":"fiscal, social e trabalhista;"},{"k":"inc","r":"IV","t":"econômico-financeira."}]},{"k":"art","n":"63","id":"a63","p":[{"k":"cap","r":"","t":"Na fase de habilitação das licitações serão observadas as seguintes disposições:"},{"k":"inc","r":"I","t":"poderá ser exigida dos licitantes a declaração de que atendem aos requisitos de habilitação, e o declarante responderá pela veracidade das informações prestadas, na forma da lei;"},{"k":"inc","r":"II","t":"será exigida a apresentação dos documentos de habilitação apenas pelo licitante vencedor, exceto quando a fase de habilitação anteceder a de julgamento;"},{"k":"inc","r":"III","t":"serão exigidos os documentos relativos à regularidade fiscal, em qualquer caso, somente em momento posterior ao julgamento das propostas, e apenas do licitante mais bem classificado;"},{"k":"inc","r":"IV","t":"será exigida do licitante declaração de que cumpre as exigências de reserva de cargos para pessoa com deficiência e para reabilitado da Previdência Social, previstas em lei e em outras normas específicas."},{"k":"par","r":"§ 1º","t":"Constará do edital de licitação cláusula que exija dos licitantes, sob pena de desclassificação, declaração de que suas propostas econômicas compreendem a integralidade dos custos para atendimento dos direitos trabalhistas assegurados na Constituição Federal, nas leis trabalhistas, nas normas infralegais, nas convenções coletivas de trabalho e nos termos de ajustamento de conduta vigentes na data de entrega das propostas."},{"k":"par","r":"§ 2º","t":"Quando a avaliação prévia do local de execução for imprescindível para o conhecimento pleno das condições e peculiaridades do objeto a ser contratado, o edital de licitação poderá prever, sob pena de inabilitação, a necessidade de o licitante atestar que conhece o local e as condições de realização da obra ou serviço, assegurado a ele o direito de realização de vistoria prévia."},{"k":"par","r":"§ 3º","t":"Para os fins previstos no § 2º deste artigo, o edital de licitação sempre deverá prever a possibilidade de substituição da vistoria por declaração formal assinada pelo responsável técnico do licitante acerca do conhecimento pleno das condições e peculiaridades da contratação."},{"k":"par","r":"§ 4º","t":"Para os fins previstos no § 2º deste artigo, se os licitantes optarem por realizar vistoria prévia, a Administração deverá disponibilizar data e horário diferentes para os eventuais interessados."}]},{"k":"art","n":"64","id":"a64","p":[{"k":"cap","r":"","t":"Após a entrega dos documentos para habilitação, não será permitida a substituição ou a apresentação de novos documentos, salvo em sede de diligência, para:"},{"k":"inc","r":"I","t":"complementação de informações acerca dos documentos já apresentados pelos licitantes e desde que necessária para apurar fatos existentes à época da abertura do certame;"},{"k":"inc","r":"II","t":"atualização de documentos cuja validade tenha expirado após a data de recebimento das propostas."},{"k":"par","r":"§ 1º","t":"Na análise dos documentos de habilitação, a comissão de licitação poderá sanar erros ou falhas que não alterem a substância dos documentos e sua validade jurídica, mediante despacho fundamentado registrado e acessível a todos, atribuindo-lhes eficácia para fins de habilitação e classificação."},{"k":"par","r":"§ 2º","t":"Quando a fase de habilitação anteceder a de julgamento e já tiver sido encerrada, não caberá exclusão de licitante por motivo relacionado à habilitação, salvo em razão de fatos supervenientes ou só conhecidos após o julgamento."}]},{"k":"art","n":"65","id":"a65","p":[{"k":"cap","r":"","t":"As condições de habilitação serão definidas no edital."},{"k":"par","r":"§ 1º","t":"As empresas criadas no exercício financeiro da licitação deverão atender a todas as exigências da habilitação e ficarão autorizadas a substituir os demonstrativos contábeis pelo balanço de abertura."},{"k":"par","r":"§ 2º","t":"A habilitação poderá ser realizada por processo eletrônico de comunicação a distância, nos termos dispostos em regulamento."}]},{"k":"art","n":"66","id":"a66","p":[{"k":"cap","r":"","t":"A habilitação jurídica visa a demonstrar a capacidade de o licitante exercer direitos e assumir obrigações, e a documentação a ser apresentada por ele limita-se à comprovação de existência jurídica da pessoa e, quando cabível, de autorização para o exercício da atividade a ser contratada."}]},{"k":"art","n":"67","id":"a67","p":[{"k":"cap","r":"","t":"A documentação relativa à qualificação técnico-profissional e técnico-operacional será restrita a:"},{"k":"inc","r":"I","t":"apresentação de profissional, devidamente registrado no conselho profissional competente, quando for o caso, detentor de atestado de responsabilidade técnica por execução de obra ou serviço de características semelhantes, para fins de contratação;"},{"k":"inc","r":"II","t":"certidões ou atestados, regularmente emitidos pelo conselho profissional competente, quando for o caso, que demonstrem capacidade operacional na execução de serviços similares de complexidade tecnológica e operacional equivalente ou superior, bem como documentos comprobatórios emitidos na forma do § 3º do art. 88 desta Lei;"},{"k":"inc","r":"III","t":"indicação do pessoal técnico, das instalações e do aparelhamento adequados e disponíveis para a realização do objeto da licitação, bem como da qualificação de cada membro da equipe técnica que se responsabilizará pelos trabalhos;"},{"k":"inc","r":"IV","t":"prova do atendimento de requisitos previstos em lei especial, quando for o caso;"},{"k":"inc","r":"V","t":"registro ou inscrição na entidade profissional competente, quando for o caso;"},{"k":"inc","r":"VI","t":"declaração de que o licitante tomou conhecimento de todas as informações e das condições locais para o cumprimento das obrigações objeto da licitação."},{"k":"par","r":"§ 1º","t":"A exigência de atestados será restrita às parcelas de maior relevância ou valor significativo do objeto da licitação, assim consideradas as que tenham valor individual igual ou superior a 4% (quatro por cento) do valor total estimado da contratação."},{"k":"par","r":"§ 2º","t":"Observado o disposto no caput e no § 1º deste artigo, será admitida a exigência de atestados com quantidades mínimas de até 50% (cinquenta por cento) das parcelas de que trata o referido parágrafo, vedadas limitações de tempo e de locais específicos relativas aos atestados."},{"k":"par","r":"§ 3º","t":"Salvo na contratação de obras e serviços de engenharia, as exigências a que se referem os incisos I e II do caput deste artigo, a critério da Administração, poderão ser substituídas por outra prova de que o profissional ou a empresa possui conhecimento técnico e experiência prática na execução de serviço de características semelhantes, hipótese em que as provas alternativas aceitáveis deverão ser previstas em regulamento."},{"k":"par","r":"§ 4º","t":"Serão aceitos atestados ou outros documentos hábeis emitidos por entidades estrangeiras quando acompanhados de tradução para o português, salvo se comprovada a inidoneidade da entidade emissora."},{"k":"par","r":"§ 5º","t":"Em se tratando de serviços contínuos, o edital poderá exigir certidão ou atestado que demonstre que o licitante tenha executado serviços similares ao objeto da licitação, em períodos sucessivos ou não, por um prazo mínimo, que não poderá ser superior a 3 (três) anos."},{"k":"par","r":"§ 6º","t":"Os profissionais indicados pelo licitante na forma dos incisos I e III do caput deste artigo deverão participar da obra ou serviço objeto da licitação, e será admitida a sua substituição por profissionais de experiência equivalente ou superior, desde que aprovada pela Administração."},{"k":"par","r":"§ 7º","t":"Sociedades empresárias estrangeiras atenderão à exigência prevista no inciso V do caput deste artigo por meio da apresentação, no momento da assinatura do contrato, da solicitação de registro perante a entidade profissional competente no Brasil."},{"k":"par","r":"§ 8º","t":"Será admitida a exigência da relação dos compromissos assumidos pelo licitante que importem em diminuição da disponibilidade do pessoal técnico referido nos incisos I e III do caput deste artigo."},{"k":"par","r":"§ 9º","t":"O edital poderá prever, para aspectos técnicos específicos, que a qualificação técnica seja demonstrada por meio de atestados relativos a potencial subcontratado, limitado a 25% (vinte e cinco por cento) do objeto a ser licitado, hipótese em que mais de um licitante poderá apresentar atestado relativo ao mesmo potencial subcontratado."},{"k":"par","r":"§ 10","t":"Em caso de apresentação por licitante de atestado de desempenho anterior emitido em favor de consórcio do qual tenha feito parte, se o atestado ou o contrato de constituição do consórcio não identificar a atividade desempenhada por cada consorciado individualmente, serão adotados os seguintes critérios na avaliação de sua qualificação técnica:"},{"k":"inc","r":"I","t":"caso o atestado tenha sido emitido em favor de consórcio homogêneo, as experiências atestadas deverão ser reconhecidas para cada empresa consorciada na proporção quantitativa de sua participação no consórcio, salvo nas licitações para contratação de serviços técnicos especializados de natureza predominantemente intelectual, em que todas as experiências atestadas deverão ser reconhecidas para cada uma das empresas consorciadas;"},{"k":"inc","r":"II","t":"caso o atestado tenha sido emitido em favor de consórcio heterogêneo, as experiências atestadas deverão ser reconhecidas para cada consorciado de acordo com os respectivos campos de atuação, inclusive nas licitações para contratação de serviços técnicos especializados de natureza predominantemente intelectual."},{"k":"par","r":"§ 11","t":"Na hipótese do § 10 deste artigo, para fins de comprovação do percentual de participação do consorciado, caso este não conste expressamente do atestado ou da certidão, deverá ser juntada ao atestado ou à certidão cópia do instrumento de constituição do consórcio."},{"k":"par","r":"§ 12","t":"Na documentação de que trata o inciso I do caput deste artigo, não serão admitidos atestados de responsabilidade técnica de profissionais que, na forma de regulamento, tenham dado causa à aplicação das sanções previstas nos incisos III e IV do caput do art. 156 desta Lei em decorrência de orientação proposta, de prescrição técnica ou de qualquer ato profissional de sua responsabilidade."}]},{"k":"art","n":"68","id":"a68","p":[{"k":"cap","r":"","t":"As habilitações fiscal, social e trabalhista serão aferidas mediante a verificação dos seguintes requisitos:"},{"k":"inc","r":"I","t":"a inscrição no Cadastro de Pessoas Físicas (CPF) ou no Cadastro Nacional da Pessoa Jurídica (CNPJ);"},{"k":"inc","r":"II","t":"a inscrição no cadastro de contribuintes estadual e/ou municipal, se houver, relativo ao domicílio ou sede do licitante, pertinente ao seu ramo de atividade e compatível com o objeto contratual;"},{"k":"inc","r":"III","t":"a regularidade perante a Fazenda federal, estadual e/ou municipal do domicílio ou sede do licitante, ou outra equivalente, na forma da lei;"},{"k":"inc","r":"IV","t":"a regularidade relativa à Seguridade Social e ao FGTS, que demonstre cumprimento dos encargos sociais instituídos por lei;"},{"k":"inc","r":"V","t":"a regularidade perante a Justiça do Trabalho;"},{"k":"inc","r":"VI","t":"o cumprimento do disposto no inciso XXXIII do art. 7º da Constituição Federal."},{"k":"par","r":"§ 1º","t":"Os documentos referidos nos incisos do caput deste artigo poderão ser substituídos ou supridos, no todo ou em parte, por outros meios hábeis a comprovar a regularidade do licitante, inclusive por meio eletrônico."},{"k":"par","r":"§ 2º","t":"A comprovação de atendimento do disposto nos incisos III, IV e V do caput deste artigo deverá ser feita na forma da legislação específica."}]},{"k":"art","n":"69","id":"a69","p":[{"k":"cap","r":"","t":"A habilitação econômico-financeira visa a demonstrar a aptidão econômica do licitante para cumprir as obrigações decorrentes do futuro contrato, devendo ser comprovada de forma objetiva, por coeficientes e índices econômicos previstos no edital, devidamente justificados no processo licitatório, e será restrita à apresentação da seguinte documentação:"},{"k":"inc","r":"I","t":"balanço patrimonial, demonstração de resultado de exercício e demais demonstrações contábeis dos 2 (dois) últimos exercícios sociais;"},{"k":"inc","r":"II","t":"certidão negativa de feitos sobre falência expedida pelo distribuidor da sede do licitante."},{"k":"par","r":"§ 1º","t":"A critério da Administração, poderá ser exigida declaração, assinada por profissional habilitado da área contábil, que ateste o atendimento pelo licitante dos índices econômicos previstos no edital."},{"k":"par","r":"§ 2º","t":"Para o atendimento do disposto no caput deste artigo, é vedada a exigência de valores mínimos de faturamento anterior e de índices de rentabilidade ou lucratividade."},{"k":"par","r":"§ 3º","t":"É admitida a exigência da relação dos compromissos assumidos pelo licitante que importem em diminuição de sua capacidade econômico-financeira, excluídas parcelas já executadas de contratos firmados."},{"k":"par","r":"§ 4º","t":"A Administração, nas compras para entrega futura e na execução de obras e serviços, poderá estabelecer no edital a exigência de capital mínimo ou de patrimônio líquido mínimo equivalente a até 10% (dez por cento) do valor estimado da contratação."},{"k":"par","r":"§ 5º","t":"É vedada a exigência de índices e valores não usualmente adotados para a avaliação de situação econômico-financeira suficiente para o cumprimento das obrigações decorrentes da licitação."},{"k":"par","r":"§ 6º","t":"Os documentos referidos no inciso I do caput deste artigo limitar-se-ão ao último exercício no caso de a pessoa jurídica ter sido constituída há menos de 2 (dois) anos."}]},{"k":"art","n":"70","id":"a70","p":[{"k":"cap","r":"","t":"A documentação referida neste Capítulo poderá ser:"},{"k":"inc","r":"I","t":"apresentada em original, por cópia ou por qualquer outro meio expressamente admitido pela Administração;"},{"k":"inc","r":"II","t":"substituída por registro cadastral emitido por órgão ou entidade pública, desde que previsto no edital e que o registro tenha sido feito em obediência ao disposto nesta Lei;"},{"k":"inc","r":"III","t":"dispensada, total ou parcialmente, nas contratações para entrega imediata, nas contratações em valores inferiores a 1/4 (um quarto) do limite para dispensa de licitação para compras em geral e nas contratações de produto para pesquisa e desenvolvimento até o valor de R$ 300.000,00 (trezentos mil reais).","n":["(Vide Decreto nº 12.343, de 2024)","(Vide Decreto nº 12.807, de 2025)"]},{"k":"par","r":"Parágrafo único","t":"As empresas estrangeiras que não funcionem no País deverão apresentar documentos equivalentes, na forma de regulamento emitido pelo Poder Executivo federal."}]},{"k":"cap","t":"CAPÍTULO VII","s":"DO ENCERRAMENTO DA LICITAÇÃO"},{"k":"art","n":"71","id":"a71","p":[{"k":"cap","r":"","t":"Encerradas as fases de julgamento e habilitação, e exauridos os recursos administrativos, o processo licitatório será encaminhado à autoridade superior, que poderá:"},{"k":"inc","r":"I","t":"determinar o retorno dos autos para saneamento de irregularidades;"},{"k":"inc","r":"II","t":"revogar a licitação por motivo de conveniência e oportunidade;"},{"k":"inc","r":"III","t":"proceder à anulação da licitação, de ofício ou mediante provocação de terceiros, sempre que presente ilegalidade insanável;"},{"k":"inc","r":"IV","t":"adjudicar o objeto e homologar a licitação."},{"k":"par","r":"§ 1º","t":"Ao pronunciar a nulidade, a autoridade indicará expressamente os atos com vícios insanáveis, tornando sem efeito todos os subsequentes que deles dependam, e dará ensejo à apuração de responsabilidade de quem lhes tenha dado causa."},{"k":"par","r":"§ 2º","t":"O motivo determinante para a revogação do processo licitatório deverá ser resultante de fato superveniente devidamente comprovado."},{"k":"par","r":"§ 3º","t":"Nos casos de anulação e revogação, deverá ser assegurada a prévia manifestação dos interessados."},{"k":"par","r":"§ 4º","t":"O disposto neste artigo será aplicado, no que couber, à contratação direta e aos procedimentos auxiliares da licitação."}]},{"k":"cap","t":"CAPÍTULO VIII","s":"DA CONTRATAÇÃO DIRETA"},{"k":"sec","t":"Seção I","s":"Do Processo de Contratação Direta"},{"k":"art","n":"72","id":"a72","p":[{"k":"cap","r":"","t":"O processo de contratação direta, que compreende os casos de inexigibilidade e de dispensa de licitação, deverá ser instruído com os seguintes documentos:"},{"k":"inc","r":"I","t":"documento de formalização de demanda e, se for o caso, estudo técnico preliminar, análise de riscos, termo de referência, projeto básico ou projeto executivo;"},{"k":"inc","r":"II","t":"estimativa de despesa, que deverá ser calculada na forma estabelecida no art. 23 desta Lei;"},{"k":"inc","r":"III","t":"parecer jurídico e pareceres técnicos, se for o caso, que demonstrem o atendimento dos requisitos exigidos;"},{"k":"inc","r":"IV","t":"demonstração da compatibilidade da previsão de recursos orçamentários com o compromisso a ser assumido;"},{"k":"inc","r":"V","t":"comprovação de que o contratado preenche os requisitos de habilitação e qualificação mínima necessária;"},{"k":"inc","r":"VI","t":"razão da escolha do contratado;"},{"k":"inc","r":"VII","t":"justificativa de preço;"},{"k":"inc","r":"VIII","t":"autorização da autoridade competente."},{"k":"par","r":"Parágrafo único","t":"O ato que autoriza a contratação direta ou o extrato decorrente do contrato deverá ser divulgado e mantido à disposição do público em sítio eletrônico oficial."}]},{"k":"art","n":"73","id":"a73","p":[{"k":"cap","r":"","t":"Na hipótese de contratação direta indevida ocorrida com dolo, fraude ou erro grosseiro, o contratado e o agente público responsável responderão solidariamente pelo dano causado ao erário, sem prejuízo de outras sanções legais cabíveis."}]},{"k":"sec","t":"Seção II","s":"Da Inexigibilidade de Licitação"},{"k":"art","n":"74","id":"a74","p":[{"k":"cap","r":"","t":"É inexigível a licitação quando inviável a competição, em especial nos casos de:"},{"k":"inc","r":"I","t":"aquisição de materiais, de equipamentos ou de gêneros ou contratação de serviços que só possam ser fornecidos por produtor, empresa ou representante comercial exclusivos;"},{"k":"inc","r":"II","t":"contratação de profissional do setor artístico, diretamente ou por meio de empresário exclusivo, desde que consagrado pela crítica especializada ou pela opinião pública;"},{"k":"inc","r":"III","t":"contratação dos seguintes serviços técnicos especializados de natureza predominantemente intelectual com profissionais ou empresas de notória especialização, vedada a inexigibilidade para serviços de publicidade e divulgação:"},{"k":"ali","r":"a)","t":"estudos técnicos, planejamentos, projetos básicos ou projetos executivos;"},{"k":"ali","r":"b)","t":"pareceres, perícias e avaliações em geral;"},{"k":"ali","r":"c)","t":"assessorias ou consultorias técnicas e auditorias financeiras ou tributárias;"},{"k":"ali","r":"d)","t":"fiscalização, supervisão ou gerenciamento de obras ou serviços;"},{"k":"ali","r":"e)","t":"patrocínio ou defesa de causas judiciais ou administrativas;"},{"k":"ali","r":"f)","t":"treinamento e aperfeiçoamento de pessoal;"},{"k":"ali","r":"g)","t":"restauração de obras de arte e de bens de valor histórico;"},{"k":"ali","r":"h)","t":"controles de qualidade e tecnológico, análises, testes e ensaios de campo e laboratoriais, instrumentação e monitoramento de parâmetros específicos de obras e do meio ambiente e demais serviços de engenharia que se enquadrem no disposto neste inciso;"},{"k":"inc","r":"IV","t":"objetos que devam ou possam ser contratados por meio de credenciamento;"},{"k":"inc","r":"V","t":"aquisição ou locação de imóvel cujas características de instalações e de localização tornem necessária sua escolha."},{"k":"par","r":"§ 1º","t":"Para fins do disposto no inciso I do caput deste artigo, a Administração deverá demonstrar a inviabilidade de competição mediante atestado de exclusividade, contrato de exclusividade, declaração do fabricante ou outro documento idôneo capaz de comprovar que o objeto é fornecido ou prestado por produtor, empresa ou representante comercial exclusivos, vedada a preferência por marca específica."},{"k":"par","r":"§ 2º","t":"Para fins do disposto no inciso II do caput deste artigo, considera-se empresário exclusivo a pessoa física ou jurídica que possua contrato, declaração, carta ou outro documento que ateste a exclusividade permanente e contínua de representação, no País ou em Estado específico, do profissional do setor artístico, afastada a possibilidade de contratação direta por inexigibilidade por meio de empresário com representação restrita a evento ou local específico."},{"k":"par","r":"§ 3º","t":"Para fins do disposto no inciso III do caput deste artigo, considera-se de notória especialização o profissional ou a empresa cujo conceito no campo de sua especialidade, decorrente de desempenho anterior, estudos, experiência, publicações, organização, aparelhamento, equipe técnica ou outros requisitos relacionados com suas atividades, permita inferir que o seu trabalho é essencial e reconhecidamente adequado à plena satisfação do objeto do contrato."},{"k":"par","r":"§ 4º","t":"Nas contratações com fundamento no inciso III do caput deste artigo, é vedada a subcontratação de empresas ou a atuação de profissionais distintos daqueles que tenham justificado a inexigibilidade."},{"k":"par","r":"§ 5º","t":"Nas contratações com fundamento no inciso V do caput deste artigo, devem ser observados os seguintes requisitos:"},{"k":"inc","r":"I","t":"avaliação prévia do bem, do seu estado de conservação, dos custos de adaptações, quando imprescindíveis às necessidades de utilização, e do prazo de amortização dos investimentos;"},{"k":"inc","r":"II","t":"certificação da inexistência de imóveis públicos vagos e disponíveis que atendam ao objeto;"},{"k":"inc","r":"III","t":"justificativas que demonstrem a singularidade do imóvel a ser comprado ou locado pela Administração e que evidenciem vantagem para ela."}]},{"k":"sec","t":"Seção III","s":"Da Dispensa de Licitação"},{"k":"art","n":"75","id":"a75","p":[{"k":"cap","r":"","t":"É dispensável a licitação:"},{"k":"inc","r":"I","t":"para contratação que envolva valores inferiores a R$ 100.000,00 (cem mil reais), no caso de obras e serviços de engenharia ou de serviços de manutenção de veículos automotores;","n":["(Vide Decreto nº 12.343, de 2024)","(Vide Decreto nº 12.807, de 2025)"]},{"k":"inc","r":"II","t":"para contratação que envolva valores inferiores a R$ 50.000,00 (cinquenta mil reais), no caso de outros serviços e compras;","n":["(Vide Decreto nº 12.343, de 2024)","(Vide Decreto nº 12.807, de 2025)"]},{"k":"inc","r":"III","t":"para contratação que mantenha todas as condições definidas em edital de licitação realizada há menos de 1 (um) ano, quando se verificar que naquela licitação:"},{"k":"ali","r":"a)","t":"não surgiram licitantes interessados ou não foram apresentadas propostas válidas;"},{"k":"ali","r":"b)","t":"as propostas apresentadas consignaram preços manifestamente superiores aos praticados no mercado ou incompatíveis com os fixados pelos órgãos oficiais competentes;"},{"k":"inc","r":"IV","t":"para contratação que tenha por objeto:"},{"k":"ali","r":"a)","t":"bens, componentes ou peças de origem nacional ou estrangeira necessários à manutenção de equipamentos, a serem adquiridos do fornecedor original desses equipamentos durante o período de garantia técnica, quando essa condição de exclusividade for indispensável para a vigência da garantia;"},{"k":"ali","r":"b)","t":"bens, serviços, alienações ou obras, nos termos de acordo internacional específico aprovado pelo Congresso Nacional, quando as condições ofertadas forem manifestamente vantajosas para a Administração;"},{"k":"ali","r":"c)","t":"produtos para pesquisa e desenvolvimento, limitada a contratação, no caso de obras e serviços de engenharia, ao valor de R$ 300.000,00 (trezentos mil reais);","n":["(Vide Decreto nº 12.343, de 2024)","(Vide Decreto nº 12.807, de 2025)"]},{"k":"ali","r":"d)","t":"transferência de tecnologia ou licenciamento de direito de uso ou de exploração de criação protegida, nas contratações realizadas por instituição científica, tecnológica e de inovação (ICT) pública ou por agência de fomento, desde que demonstrada vantagem para a Administração;"},{"k":"ali","r":"e)","t":"hortifrutigranjeiros, pães e outros gêneros perecíveis, no período necessário para a realização dos processos licitatórios correspondentes, hipótese em que a contratação será realizada diretamente com base no preço do dia;"},{"k":"ali","r":"f)","t":"bens ou serviços produzidos ou prestados no País que envolvam, cumulativamente, alta complexidade tecnológica e defesa nacional;"},{"k":"ali","r":"g)","t":"materiais de uso das Forças Armadas, com exceção de materiais de uso pessoal e administrativo, quando houver necessidade de manter a padronização requerida pela estrutura de apoio logístico dos meios navais, aéreos e terrestres, mediante autorização por ato do comandante da força militar;"},{"k":"ali","r":"h)","t":"bens e serviços para atendimento dos contingentes militares das forças singulares brasileiras empregadas em operações de paz no exterior, hipótese em que a contratação deverá ser justificada quanto ao preço e à escolha do fornecedor ou executante e ratificada pelo comandante da força militar;"},{"k":"ali","r":"i)","t":"abastecimento ou suprimento de efetivos militares em estada eventual de curta duração em portos, aeroportos ou localidades diferentes de suas sedes, por motivo de movimentação operacional ou de adestramento;"},{"k":"ali","r":"j)","t":"coleta, processamento e comercialização de resíduos sólidos urbanos recicláveis ou reutilizáveis, em áreas com sistema de coleta seletiva de lixo, realizados por associações ou cooperativas formadas exclusivamente de pessoas físicas de baixa renda reconhecidas pelo poder público como catadores de materiais recicláveis, com o uso de equipamentos compatíveis com as normas técnicas, ambientais e de saúde pública;"},{"k":"ali","r":"k)","t":"aquisição ou restauração de obras de arte e objetos históricos, de autenticidade certificada, desde que inerente às finalidades do órgão ou com elas compatível;"},{"k":"ali","r":"l)","t":"serviços especializados ou aquisição ou locação de equipamentos destinados ao rastreamento e à obtenção de provas previstas nos incisos II e V do caput do art. 3º da Lei nº 12.850, de 2 de agosto de 2013, quando houver necessidade justificada de manutenção de sigilo sobre a investigação;"},{"k":"ali","r":"m)","t":"aquisição de medicamentos destinados exclusivamente ao tratamento de doenças raras definidas pelo Ministério da Saúde;"},{"k":"inc","r":"V","t":"para contratação com vistas ao cumprimento do disposto nos arts. 3º, 3º-A, 4º, 5º e 20 da Lei nº 10.973, de 2 de dezembro de 2004, observados os princípios gerais de contratação constantes da referida Lei;"},{"k":"inc","r":"VI","t":"para contratação que possa acarretar comprometimento da segurança nacional, nos casos estabelecidos pelo Ministro de Estado da Defesa, mediante demanda dos comandos das Forças Armadas ou dos demais ministérios;"},{"k":"inc","r":"VII","t":"nos casos de guerra, estado de defesa, estado de sítio, intervenção federal ou de grave perturbação da ordem;"},{"k":"inc","r":"VIII","t":"nos casos de emergência ou de calamidade pública, quando caracterizada urgência de atendimento de situação que possa ocasionar prejuízo ou comprometer a continuidade dos serviços públicos ou a segurança de pessoas, obras, serviços, equipamentos e outros bens, públicos ou particulares, e somente para aquisição dos bens necessários ao atendimento da situação emergencial ou calamitosa e para as parcelas de obras e serviços que possam ser concluídas no prazo máximo de 1 (um) ano, contado da data de ocorrência da emergência ou da calamidade, vedadas a prorrogação dos respectivos contratos e a recontratação de empresa já contratada com base no disposto neste inciso;","n":["(Vide ADI 6890)"]},{"k":"inc","r":"IX","t":"para a aquisição, por pessoa jurídica de direito público interno, de bens produzidos ou serviços prestados por órgão ou entidade que integrem a Administração Pública e que tenham sido criados para esse fim específico, desde que o preço contratado seja compatível com o praticado no mercado;"},{"k":"inc","r":"X","t":"quando a União tiver que intervir no domínio econômico para regular preços ou normalizar o abastecimento;"},{"k":"inc","r":"XI","t":"para celebração de contrato de programa com ente federativo ou com entidade de sua Administração Pública indireta que envolva prestação de serviços públicos de forma associada nos termos autorizados em contrato de consórcio público ou em convênio de cooperação;"},{"k":"inc","r":"XII","t":"para contratação em que houver transferência de tecnologia de produtos estratégicos para o Sistema Único de Saúde (SUS), conforme elencados em ato da direção nacional do SUS, inclusive por ocasião da aquisição desses produtos durante as etapas de absorção tecnológica, e em valores compatíveis com aqueles definidos no instrumento firmado para a transferência de tecnologia;"},{"k":"inc","r":"XIII","t":"para contratação de profissionais para compor a comissão de avaliação de critérios de técnica, quando se tratar de profissional técnico de notória especialização;"},{"k":"inc","r":"XIV","t":"para contratação de associação de pessoas com deficiência, sem fins lucrativos e de comprovada idoneidade, por órgão ou entidade da Administração Pública, para a prestação de serviços, desde que o preço contratado seja compatível com o praticado no mercado e os serviços contratados sejam prestados exclusivamente por pessoas com deficiência;"},{"k":"inc","r":"XV","t":"para contratação de instituição brasileira que tenha por finalidade estatutária apoiar, captar e executar atividades de ensino, pesquisa, extensão, desenvolvimento institucional, científico e tecnológico e estímulo à inovação, inclusive para gerir administrativa e financeiramente essas atividades, ou para contratação de instituição dedicada à recuperação social da pessoa presa, desde que o contratado tenha inquestionável reputação ética e profissional e não tenha fins lucrativos;"},{"k":"inc","r":"XVI","t":"para aquisição, por pessoa jurídica de direito público interno, de produtos estratégicos para a saúde fornecidos por produtores públicos por intermédio de fundação que, regimental ou estatutariamente, tenha por finalidade apoiar órgão da Administração Pública direta, sua autarquia ou fundação em projetos de ensino, pesquisa, extensão, desenvolvimento institucional, científico e tecnológico e de estímulo à inovação, inclusive na gestão administrativa e financeira necessária à execução desses projetos, ou em parcerias que envolvam transferência de tecnologia de produtos estratégicos para o SUS, nos termos do inciso XII deste caput, e que tenha sido criada para esse fim específico em data anterior à entrada em vigor desta Lei, desde que o preço contratado seja compatível com o praticado no mercado;","n":["(Redação dada pela Lei nº 15.471, de 2026)"]},{"k":"inc","r":"XVII","t":"para contratação de entidades privadas sem fins lucrativos para a implementação de cisternas ou outras tecnologias sociais de acesso à água para consumo humano e produção de alimentos, a fim de beneficiar as famílias rurais de baixa renda atingidas pela seca ou pela falta regular de água; e","n":["(Incluído pela Lei nº 14.628, de 2023)"]},{"k":"inc","r":"XVIII","t":"para contratação de entidades privadas sem fins lucrativos, para a implementação do Programa Cozinha Solidária, que tem como finalidade fornecer alimentação gratuita preferencialmente à população em situação de vulnerabilidade e risco social, incluída a população em situação de rua, com vistas à promoção de políticas de segurança alimentar e nutricional e de assistência social e à efetivação de direitos sociais, dignidade humana, resgate social e melhoria da qualidade de vida.","n":["(Incluído pela Lei nº 14.628, de 2023)"]},{"k":"par","r":"§ 1º","t":"Para fins de aferição dos valores que atendam aos limites referidos nos incisos I e II do caput deste artigo, deverão ser observados:"},{"k":"inc","r":"I","t":"o somatório do que for despendido no exercício financeiro pela respectiva unidade gestora;"},{"k":"inc","r":"II","t":"o somatório da despesa realizada com objetos de mesma natureza, entendidos como tais aqueles relativos a contratações no mesmo ramo de atividade."},{"k":"par","r":"§ 2º","t":"Os valores referidos nos incisos I e II do caput deste artigo serão duplicados para compras, obras e serviços contratados por consórcio público ou por autarquia ou fundação qualificadas como agências executivas na forma da lei."},{"k":"par","r":"§ 3º","t":"As contratações de que tratam os incisos I e II do caput deste artigo serão preferencialmente precedidas de divulgação de aviso em sítio eletrônico oficial, pelo prazo mínimo de 3 (três) dias úteis, com a especificação do objeto pretendido e com a manifestação de interesse da Administração em obter propostas adicionais de eventuais interessados, devendo ser selecionada a proposta mais vantajosa."},{"k":"par","r":"§ 4º","t":"As contratações de que tratam os incisos I e II do caput deste artigo serão preferencialmente pagas por meio de cartão de pagamento, cujo extrato deverá ser divulgado e mantido à disposição do público no Portal Nacional de Contratações Públicas (PNCP)."},{"k":"par","r":"§ 5º","t":"A dispensa prevista na alínea “c” do inciso IV do caput deste artigo, quando aplicada a obras e serviços de engenharia, seguirá procedimentos especiais instituídos em regulamentação específica."},{"k":"par","r":"§ 6º","t":"Para os fins do inciso VIII do caput deste artigo, considera-se emergencial a contratação por dispensa com objetivo de manter a continuidade do serviço público, e deverão ser observados os valores praticados pelo mercado na forma do art. 23 desta Lei e adotadas as providências necessárias para a conclusão do processo licitatório, sem prejuízo de apuração de responsabilidade dos agentes públicos que deram causa à situação emergencial."},{"k":"par","r":"§ 7º","t":"Não se aplica o disposto no § 1º deste artigo às contratações de até R$ 8.000,00 (oito mil reais) de serviços de manutenção de veículos automotores de propriedade do órgão ou entidade contratante, incluído o fornecimento de peças.","n":["(Vide Decreto nº 12.343, de 2024)","(Vide Decreto nº 12.807, de 2025)"]}]},{"k":"cap","t":"CAPÍTULO IX","s":"DAS ALIENAÇÕES"},{"k":"art","n":"76","id":"a76","p":[{"k":"cap","r":"","t":"A alienação de bens da Administração Pública, subordinada à existência de interesse público devidamente justificado, será precedida de avaliação e obedecerá às seguintes normas:"},{"k":"inc","r":"I","t":"tratando-se de bens imóveis, inclusive os pertencentes às autarquias e às fundações, exigirá autorização legislativa e dependerá de licitação na modalidade leilão, dispensada a realização de licitação nos casos de:"},{"k":"ali","r":"a)","t":"dação em pagamento;"},{"k":"ali","r":"b)","t":"doação, permitida exclusivamente para outro órgão ou entidade da Administração Pública, de qualquer esfera de governo, ressalvado o disposto nas alíneas “f”, “g” e “h” deste inciso;"},{"k":"ali","r":"c)","t":"permuta por outros imóveis que atendam aos requisitos relacionados às finalidades precípuas da Administração, desde que a diferença apurada não ultrapasse a metade do valor do imóvel que será ofertado pela União, segundo avaliação prévia, e ocorra a torna de valores, sempre que for o caso;"},{"k":"ali","r":"d)","t":"investidura;"},{"k":"ali","r":"e)","t":"venda a outro órgão ou entidade da Administração Pública de qualquer esfera de governo;"},{"k":"ali","r":"f)","t":"alienação gratuita ou onerosa, aforamento, concessão de direito real de uso, locação e permissão de uso de bens imóveis residenciais construídos, destinados ou efetivamente usados em programas de habitação ou de regularização fundiária de interesse social desenvolvidos por órgão ou entidade da Administração Pública;"},{"k":"ali","r":"g)","t":"alienação gratuita ou onerosa, aforamento, concessão de direito real de uso, locação e permissão de uso de bens imóveis comerciais de âmbito local, com área de até 250 m² (duzentos e cinquenta metros quadrados) e destinados a programas de regularização fundiária de interesse social desenvolvidos por órgão ou entidade da Administração Pública;"},{"k":"ali","r":"h)","t":"alienação e concessão de direito real de uso, gratuita ou onerosa, de terras públicas rurais da União e do Instituto Nacional de Colonização e Reforma Agrária (Incra) onde incidam ocupações até o limite de que trata o § 1º do art. 6º da Lei nº 11.952, de 25 de junho de 2009, para fins de regularização fundiária, atendidos os requisitos legais;"},{"k":"ali","r":"i)","t":"legitimação de posse de que trata o art. 29 da Lei nº 6.383, de 7 de dezembro de 1976, mediante iniciativa e deliberação dos órgãos da Administração Pública competentes;"},{"k":"ali","r":"j)","t":"legitimação fundiária e legitimação de posse de que trata a Lei nº 13.465, de 11 de julho de 2017;"},{"k":"inc","r":"II","t":"tratando-se de bens móveis, dependerá de licitação na modalidade leilão, dispensada a realização de licitação nos casos de:"},{"k":"ali","r":"a)","t":"doação, permitida exclusivamente para fins e uso de interesse social, após avaliação de oportunidade e conveniência socioeconômica em relação à escolha de outra forma de alienação;"},{"k":"ali","r":"b)","t":"permuta, permitida exclusivamente entre órgãos ou entidades da Administração Pública;"},{"k":"ali","r":"c)","t":"venda de ações, que poderão ser negociadas em bolsa, observada a legislação específica;"},{"k":"ali","r":"d)","t":"venda de títulos, observada a legislação pertinente;"},{"k":"ali","r":"e)","t":"venda de bens produzidos ou comercializados por entidades da Administração Pública, em virtude de suas finalidades;"},{"k":"ali","r":"f)","t":"venda de materiais e equipamentos sem utilização previsível por quem deles dispõe para outros órgãos ou entidades da Administração Pública."},{"k":"par","r":"§ 1º","t":"A alienação de bens imóveis da Administração Pública cuja aquisição tenha sido derivada de procedimentos judiciais ou de dação em pagamento dispensará autorização legislativa e exigirá apenas avaliação prévia e licitação na modalidade leilão."},{"k":"par","r":"§ 2º","t":"Os imóveis doados com base na alínea “b” do inciso I do caput deste artigo, cessadas as razões que justificaram sua doação, serão revertidos ao patrimônio da pessoa jurídica doadora, vedada sua alienação pelo beneficiário."},{"k":"par","r":"§ 3º","t":"A Administração poderá conceder título de propriedade ou de direito real de uso de imóvel, admitida a dispensa de licitação, quando o uso destinar-se a:"},{"k":"inc","r":"I","t":"outro órgão ou entidade da Administração Pública, qualquer que seja a localização do imóvel;"},{"k":"inc","r":"II","t":"pessoa natural que, nos termos de lei, regulamento ou ato normativo do órgão competente, haja implementado os requisitos mínimos de cultura, de ocupação mansa e pacífica e de exploração direta sobre área rural, observado o limite de que trata o § 1º do art. 6º da Lei nº 11.952, de 25 de junho de 2009."},{"k":"par","r":"§ 4º","t":"A aplicação do disposto no inciso II do § 3º deste artigo será dispensada de autorização legislativa e submeter-se-á aos seguintes condicionamentos:"},{"k":"inc","r":"I","t":"aplicação exclusiva às áreas em que a detenção por particular seja comprovadamente anterior a 1º de dezembro de 2004;"},{"k":"inc","r":"II","t":"submissão aos demais requisitos e impedimentos do regime legal e administrativo de destinação e de regularização fundiária de terras públicas;"},{"k":"inc","r":"III","t":"vedação de concessão para exploração não contemplada na lei agrária, nas leis de destinação de terras públicas ou nas normas legais ou administrativas de zoneamento ecológico-econômico;"},{"k":"inc","r":"IV","t":"previsão de extinção automática da concessão, dispensada notificação, em caso de declaração de utilidade pública, de necessidade pública ou de interesse social;"},{"k":"inc","r":"V","t":"aplicação exclusiva a imóvel situado em zona rural e não sujeito a vedação, impedimento ou inconveniente à exploração mediante atividade agropecuária;"},{"k":"inc","r":"VI","t":"limitação a áreas de que trata o § 1º do art. 6º da Lei nº 11.952, de 25 de junho de 2009, vedada a dispensa de licitação para áreas superiores;"},{"k":"inc","r":"VII","t":"acúmulo com o quantitativo de área decorrente do caso previsto na alínea “i” do inciso I do caput deste artigo até o limite previsto no inciso VI deste parágrafo."},{"k":"par","r":"§ 5º","t":"Entende-se por investidura, para os fins desta Lei, a:"},{"k":"inc","r":"I","t":"alienação, ao proprietário de imóvel lindeiro, de área remanescente ou resultante de obra pública que se tornar inaproveitável isoladamente, por preço que não seja inferior ao da avaliação nem superior a 50% (cinquenta por cento) do valor máximo permitido para dispensa de licitação de bens e serviços previsto nesta Lei;"},{"k":"inc","r":"II","t":"alienação, ao legítimo possuidor direto ou, na falta dele, ao poder público, de imóvel para fins residenciais construído em núcleo urbano anexo a usina hidrelétrica, desde que considerado dispensável na fase de operação da usina e que não integre a categoria de bens reversíveis ao final da concessão."},{"k":"par","r":"§ 6º","t":"A doação com encargo será licitada e de seu instrumento constarão, obrigatoriamente, os encargos, o prazo de seu cumprimento e a cláusula de reversão, sob pena de nulidade do ato, dispensada a licitação em caso de interesse público devidamente justificado."},{"k":"par","r":"§ 7º","t":"Na hipótese do § 6º deste artigo, caso o donatário necessite oferecer o imóvel em garantia de financiamento, a cláusula de reversão e as demais obrigações serão garantidas por hipoteca em segundo grau em favor do doador."}]},{"k":"art","n":"77","id":"a77","p":[{"k":"cap","r":"","t":"Para a venda de bens imóveis, será concedido direito de preferência ao licitante que, submetendo-se a todas as regras do edital, comprove a ocupação do imóvel objeto da licitação."}]},{"k":"cap","t":"CAPÍTULO X","s":"DOS INSTRUMENTOS AUXILIARES"},{"k":"sec","t":"Seção I","s":"Dos Procedimentos Auxiliares"},{"k":"art","n":"78","id":"a78","p":[{"k":"cap","r":"","t":"São procedimentos auxiliares das licitações e das contratações regidas por esta Lei:"},{"k":"inc","r":"I","t":"credenciamento;"},{"k":"inc","r":"II","t":"pré-qualificação;"},{"k":"inc","r":"III","t":"procedimento de manifestação de interesse;"},{"k":"inc","r":"IV","t":"sistema de registro de preços;"},{"k":"inc","r":"V","t":"registro cadastral."},{"k":"par","r":"§ 1º","t":"Os procedimentos auxiliares de que trata o caput deste artigo obedecerão a critérios claros e objetivos definidos em regulamento."},{"k":"par","r":"§ 2º","t":"O julgamento que decorrer dos procedimentos auxiliares das licitações previstos nos incisos II e III do caput deste artigo seguirá o mesmo procedimento das licitações."}]},{"k":"sec","t":"Seção II","s":"Do Credenciamento"},{"k":"art","n":"79","id":"a79","p":[{"k":"cap","r":"","t":"O credenciamento poderá ser usado nas seguintes hipóteses de contratação:"},{"k":"inc","r":"I","t":"paralela e não excludente: caso em que é viável e vantajosa para a Administração a realização de contratações simultâneas em condições padronizadas;"},{"k":"inc","r":"II","t":"com seleção a critério de terceiros: caso em que a seleção do contratado está a cargo do beneficiário direto da prestação;"},{"k":"inc","r":"III","t":"em mercados fluidos: caso em que a flutuação constante do valor da prestação e das condições de contratação inviabiliza a seleção de agente por meio de processo de licitação."},{"k":"inc","r":"IV","t":"comércio eletrônico: caso em que a Administração visa a contratar bens e serviços comuns padronizados ofertados no Sistema de Compras Expressas (Sicx).","n":["(Incluído pela Lei nº 15.266, de 2025)"]},{"k":"par","r":"§ 1º","t":"Os procedimentos de credenciamento serão definidos em regulamento, observadas as seguintes regras:","n":["(Redação dada pela Lei nº 15.266, de 2025)"]},{"k":"inc","r":"I","t":"a Administração deverá divulgar e manter à disposição do público, em sítio eletrônico oficial, edital de chamamento de interessados, de modo a permitir o cadastramento permanente de novos interessados;"},{"k":"inc","r":"II","t":"na hipótese do inciso I do caput deste artigo, quando o objeto não permitir a contratação imediata e simultânea de todos os credenciados, deverão ser adotados critérios objetivos de distribuição da demanda;"},{"k":"inc","r":"III","t":"o edital de chamamento de interessados deverá prever as condições padronizadas de contratação e, nas hipóteses dos incisos I e II do caput deste artigo, deverá definir o valor da contratação;"},{"k":"inc","r":"IV","t":"na hipótese do inciso III do caput deste artigo, a Administração deverá registrar as cotações de mercado vigentes no momento da contratação;"},{"k":"inc","r":"V","t":"não será permitido o cometimento a terceiros do objeto contratado sem autorização expressa da Administração;"},{"k":"inc","r":"VI","t":"será admitida a denúncia por qualquer das partes nos prazos fixados no edital."},{"k":"inc","r":"VII","t":"na hipótese do inciso IV do caput deste artigo, regulamento do Poder Executivo federal disporá sobre:","n":["(Incluído pela Lei nº 15.266, de 2025)"]},{"k":"ali","r":"a)","t":"as condições de admissão e de permanência dos fornecedores, observado o disposto no art. 87 desta Lei;","n":["(Incluído pela Lei nº 15.266, de 2025)"]},{"k":"ali","r":"b)","t":"as regras para inclusão de bens e serviços e para formação e alteração dos preços;","n":["(Incluído pela Lei nº 15.266, de 2025)"]},{"k":"ali","r":"c)","t":"os prazos e os métodos para entrega e recebimento dos bens e serviços;","n":["(Incluído pela Lei nº 15.266, de 2025)"]},{"k":"ali","r":"d)","t":"as regras de instrução processual e de uso da plataforma;","n":["(Incluído pela Lei nº 15.266, de 2025)"]},{"k":"ali","r":"e)","t":"as condições de pagamento, com prazo não superior a 30 (trinta) dias, contado do recebimento do bem ou serviço;","n":["(Incluído pela Lei nº 15.266, de 2025)"]},{"k":"ali","r":"f)","t":"as sanções aplicáveis ao responsável por infrações, observado o disposto nos arts. 155 a 163 desta Lei.","n":["(Incluído pela Lei nº 15.266, de 2025)"]},{"k":"par","r":"§ 2º","t":"O Sicx poderá ser disponibilizado para os órgãos e entidades de que trata o caput do art. 1º desta Lei, para empresas públicas, para sociedades de economia mista e suas subsidiárias e para entidades privadas sem fins lucrativos.","n":["(Incluído pela Lei nº 15.266, de 2025)"]}]},{"k":"sec","t":"Seção III","s":"Da Pré-Qualificação"},{"k":"art","n":"80","id":"a80","p":[{"k":"cap","r":"","t":"A pré-qualificação é o procedimento técnico-administrativo para selecionar previamente:"},{"k":"inc","r":"I","t":"licitantes que reúnam condições de habilitação para participar de futura licitação ou de licitação vinculada a programas de obras ou de serviços objetivamente definidos;"},{"k":"inc","r":"II","t":"bens que atendam às exigências técnicas ou de qualidade estabelecidas pela Administração."},{"k":"par","r":"§ 1º","t":"Na pré-qualificação observar-se-á o seguinte:"},{"k":"inc","r":"I","t":"quando aberta a licitantes, poderão ser dispensados os documentos que já constarem do registro cadastral;"},{"k":"inc","r":"II","t":"quando aberta a bens, poderá ser exigida a comprovação de qualidade."},{"k":"par","r":"§ 2º","t":"O procedimento de pré-qualificação ficará permanentemente aberto para a inscrição de interessados."},{"k":"par","r":"§ 3º","t":"Quanto ao procedimento de pré-qualificação, constarão do edital:"},{"k":"inc","r":"I","t":"as informações mínimas necessárias para definição do objeto;"},{"k":"inc","r":"II","t":"a modalidade, a forma da futura licitação e os critérios de julgamento."},{"k":"par","r":"§ 4º","t":"A apresentação de documentos far-se-á perante órgão ou comissão indicada pela Administração, que deverá examiná-los no prazo máximo de 10 (dez) dias úteis e determinar correção ou reapresentação de documentos, quando for o caso, com vistas à ampliação da competição."},{"k":"par","r":"§ 5º","t":"Os bens e os serviços pré-qualificados deverão integrar o catálogo de bens e serviços da Administração."},{"k":"par","r":"§ 6º","t":"A pré-qualificação poderá ser realizada em grupos ou segmentos, segundo as especialidades dos fornecedores."},{"k":"par","r":"§ 7º","t":"A pré-qualificação poderá ser parcial ou total, com alguns ou todos os requisitos técnicos ou de habilitação necessários à contratação, assegurada, em qualquer hipótese, a igualdade de condições entre os concorrentes."},{"k":"par","r":"§ 8º","t":"Quanto ao prazo, a pré-qualificação terá validade:"},{"k":"inc","r":"I","t":"de 1 (um) ano, no máximo, e poderá ser atualizada a qualquer tempo;"},{"k":"inc","r":"II","t":"não superior ao prazo de validade dos documentos apresentados pelos interessados."},{"k":"par","r":"§ 9º","t":"Os licitantes e os bens pré-qualificados serão obrigatoriamente divulgados e mantidos à disposição do público."},{"k":"par","r":"§ 10","t":"A licitação que se seguir ao procedimento da pré-qualificação poderá ser restrita a licitantes ou bens pré- qualificados."}]},{"k":"sec","t":"Seção IV","s":"Do Procedimento de Manifestação de Interesse"},{"k":"art","n":"81","id":"a81","p":[{"k":"cap","r":"","t":"A Administração poderá solicitar à iniciativa privada, mediante procedimento aberto de manifestação de interesse a ser iniciado com a publicação de edital de chamamento público, a propositura e a realização de estudos, investigações, levantamentos e projetos de soluções inovadoras que contribuam com questões de relevância pública, na forma de regulamento."},{"k":"par","r":"§ 1º","t":"Os estudos, as investigações, os levantamentos e os projetos vinculados à contratação e de utilidade para a licitação, realizados pela Administração ou com a sua autorização, estarão à disposição dos interessados, e o vencedor da licitação deverá ressarcir os dispêndios correspondentes, conforme especificado no edital."},{"k":"par","r":"§ 2º","t":"A realização, pela iniciativa privada, de estudos, investigações, levantamentos e projetos em decorrência do procedimento de manifestação de interesse previsto no caput deste artigo:"},{"k":"inc","r":"I","t":"não atribuirá ao realizador direito de preferência no processo licitatório;"},{"k":"inc","r":"II","t":"não obrigará o poder público a realizar licitação;"},{"k":"inc","r":"III","t":"não implicará, por si só, direito a ressarcimento de valores envolvidos em sua elaboração;"},{"k":"inc","r":"IV","t":"será remunerada somente pelo vencedor da licitação, vedada, em qualquer hipótese, a cobrança de valores do poder público."},{"k":"par","r":"§ 3º","t":"Para aceitação dos produtos e serviços de que trata o caput deste artigo, a Administração deverá elaborar parecer fundamentado com a demonstração de que o produto ou serviço entregue é adequado e suficiente à compreensão do objeto, de que as premissas adotadas são compatíveis com as reais necessidades do órgão e de que a metodologia proposta é a que propicia maior economia e vantagem entre as demais possíveis."},{"k":"par","r":"§ 4º","t":"O procedimento previsto no caput deste artigo poderá ser restrito a startups, assim considerados os microempreendedores individuais, as microempresas e as empresas de pequeno porte, de natureza emergente e com grande potencial, que se dediquem à pesquisa, ao desenvolvimento e à implementação de novos produtos ou serviços baseados em soluções tecnológicas inovadoras que possam causar alto impacto, exigida, na seleção definitiva da inovação, validação prévia fundamentada em métricas objetivas, de modo a demonstrar o atendimento das necessidades da Administração."}]},{"k":"sec","t":"Seção V","s":"Do Sistema de Registro de Preços"},{"k":"art","n":"82","id":"a82","p":[{"k":"cap","r":"","t":"O edital de licitação para registro de preços observará as regras gerais desta Lei e deverá dispor sobre:"},{"k":"inc","r":"I","t":"as especificidades da licitação e de seu objeto, inclusive a quantidade máxima de cada item que poderá ser adquirida;"},{"k":"inc","r":"II","t":"a quantidade mínima a ser cotada de unidades de bens ou, no caso de serviços, de unidades de medida;"},{"k":"inc","r":"III","t":"a possibilidade de prever preços diferentes:"},{"k":"ali","r":"a)","t":"quando o objeto for realizado ou entregue em locais diferentes;"},{"k":"ali","r":"b)","t":"em razão da forma e do local de acondicionamento;"},{"k":"ali","r":"c)","t":"quando admitida cotação variável em razão do tamanho do lote;"},{"k":"ali","r":"d)","t":"por outros motivos justificados no processo;"},{"k":"inc","r":"IV","t":"a possibilidade de o licitante oferecer ou não proposta em quantitativo inferior ao máximo previsto no edital, obrigando-se nos limites dela;"},{"k":"inc","r":"V","t":"o critério de julgamento da licitação, que será o de menor preço ou o de maior desconto sobre tabela de preços praticada no mercado;"},{"k":"inc","r":"VI","t":"as condições para alteração de preços registrados;"},{"k":"inc","r":"VII","t":"o registro de mais de um fornecedor ou prestador de serviço, desde que aceitem cotar o objeto em preço igual ao do licitante vencedor, assegurada a preferência de contratação de acordo com a ordem de classificação;"},{"k":"inc","r":"VIII","t":"a vedação à participação do órgão ou entidade em mais de uma ata de registro de preços com o mesmo objeto no prazo de validade daquela de que já tiver participado, salvo na ocorrência de ata que tenha registrado quantitativo inferior ao máximo previsto no edital;"},{"k":"inc","r":"IX","t":"as hipóteses de cancelamento da ata de registro de preços e suas consequências."},{"k":"par","r":"§ 1º","t":"O critério de julgamento de menor preço por grupo de itens somente poderá ser adotado quando for demonstrada a inviabilidade de se promover a adjudicação por item e for evidenciada a sua vantagem técnica e econômica, e o critério de aceitabilidade de preços unitários máximos deverá ser indicado no edital."},{"k":"par","r":"§ 2º","t":"Na hipótese de que trata o § 1º deste artigo, observados os parâmetros estabelecidos nos §§ 1º, 2º e 3º do art. 23 desta Lei, a contratação posterior de item específico constante de grupo de itens exigirá prévia pesquisa de mercado e demonstração de sua vantagem para o órgão ou entidade."},{"k":"par","r":"§ 3º","t":"É permitido registro de preços com indicação limitada a unidades de contratação, sem indicação do total a ser adquirido, apenas nas seguintes situações:"},{"k":"inc","r":"I","t":"quando for a primeira licitação para o objeto e o órgão ou entidade não tiver registro de demandas anteriores;"},{"k":"inc","r":"II","t":"no caso de alimento perecível;"},{"k":"inc","r":"III","t":"no caso em que o serviço estiver integrado ao fornecimento de bens."},{"k":"par","r":"§ 4º","t":"Nas situações referidas no § 3º deste artigo, é obrigatória a indicação do valor máximo da despesa e é vedada a participação de outro órgão ou entidade na ata."},{"k":"par","r":"§ 5º","t":"O sistema de registro de preços poderá ser usado para a contratação de bens e serviços, inclusive de obras e serviços de engenharia, observadas as seguintes condições:"},{"k":"inc","r":"I","t":"realização prévia de ampla pesquisa de mercado;"},{"k":"inc","r":"II","t":"seleção de acordo com os procedimentos previstos em regulamento;"},{"k":"inc","r":"III","t":"desenvolvimento obrigatório de rotina de controle;"},{"k":"inc","r":"IV","t":"atualização periódica dos preços registrados;"},{"k":"inc","r":"V","t":"definição do período de validade do registro de preços;"},{"k":"inc","r":"VI","t":"inclusão, em ata de registro de preços, do licitante que aceitar cotar os bens ou serviços em preços iguais aos do licitante vencedor na sequência de classificação da licitação e inclusão do licitante que mantiver sua proposta original."},{"k":"par","r":"§ 6º","t":"O sistema de registro de preços poderá, na forma de regulamento, ser utilizado nas hipóteses de inexigibilidade e de dispensa de licitação para a aquisição de bens ou para a contratação de serviços por mais de um órgão ou entidade."}]},{"k":"art","n":"83","id":"a83","p":[{"k":"cap","r":"","t":"A existência de preços registrados implicará compromisso de fornecimento nas condições estabelecidas, mas não obrigará a Administração a contratar, facultada a realização de licitação específica para a aquisição pretendida, desde que devidamente motivada."}]},{"k":"art","n":"84","id":"a84","p":[{"k":"cap","r":"","t":"O prazo de vigência da ata de registro de preços será de 1 (um) ano e poderá ser prorrogado, por igual período, desde que comprovado o preço vantajoso."},{"k":"par","r":"Parágrafo único","t":"O contrato decorrente da ata de registro de preços terá sua vigência estabelecida em conformidade com as disposições nela contidas."}]},{"k":"art","n":"85","id":"a85","p":[{"k":"cap","r":"","t":"A Administração poderá contratar a execução de obras e serviços de engenharia pelo sistema de registro de preços, desde que atendidos os seguintes requisitos:"},{"k":"inc","r":"I","t":"existência de projeto padronizado, sem complexidade técnica e operacional;"},{"k":"inc","r":"II","t":"necessidade permanente ou frequente de obra ou serviço a ser contratado."}]},{"k":"art","n":"86","id":"a86","p":[{"k":"cap","r":"","t":"O órgão ou entidade gerenciadora deverá, na fase preparatória do processo licitatório, para fins de registro de preços, realizar procedimento público de intenção de registro de preços para, nos termos de regulamento, possibilitar, pelo prazo mínimo de 8 (oito) dias úteis, a participação de outros órgãos ou entidades na respectiva ata e determinar a estimativa total de quantidades da contratação."},{"k":"par","r":"§ 1º","t":"O procedimento previsto no caput deste artigo será dispensável quando o órgão ou entidade gerenciadora for o único contratante."},{"k":"par","r":"§ 2º","t":"Se não participarem do procedimento previsto no caput deste artigo, os órgãos e entidades poderão aderir à ata de registro de preços na condição de não participantes, observados os seguintes requisitos:"},{"k":"inc","r":"I","t":"apresentação de justificativa da vantagem da adesão, inclusive em situações de provável desabastecimento ou descontinuidade de serviço público;"},{"k":"inc","r":"II","t":"demonstração de que os valores registrados estão compatíveis com os valores praticados pelo mercado na forma do art. 23 desta Lei;"},{"k":"inc","r":"III","t":"prévias consulta e aceitação do órgão ou entidade gerenciadora e do fornecedor."},{"k":"par","r":"§ 3º","t":"A faculdade de aderir à ata de registro de preços na condição de não participante poderá ser exercida:","n":["(Redação dada pela Lei nº 14.770, de 2023)"]},{"k":"inc","r":"I","t":"por órgãos e entidades da Administração Pública federal, estadual, distrital e municipal, relativamente a ata de registro de preços de órgão ou entidade gerenciadora federal, estadual ou distrital; ou","n":["(Incluído pela Lei nº 14.770, de 2023)"]},{"k":"inc","r":"II","t":"por órgãos e entidades da Administração Pública municipal, relativamente a ata de registro de preços de órgão ou entidade gerenciadora municipal, desde que o sistema de registro de preços tenha sido formalizado mediante licitação.","n":["(Incluído pela Lei nº 14.770, de 2023)"]},{"k":"par","r":"§ 4º","t":"As aquisições ou as contratações adicionais a que se refere o § 2º deste artigo não poderão exceder, por órgão ou entidade, a 50% (cinquenta por cento) dos quantitativos dos itens do instrumento convocatório registrados na ata de registro de preços para o órgão gerenciador e para os órgãos participantes."},{"k":"par","r":"§ 5º","t":"O quantitativo decorrente das adesões à ata de registro de preços a que se refere o § 2º deste artigo não poderá exceder, na totalidade, ao dobro do quantitativo de cada item registrado na ata de registro de preços para o órgão gerenciador e órgãos participantes, independentemente do número de órgãos não participantes que aderirem."},{"k":"par","r":"§ 6º","t":"A adesão à ata de registro de preços de órgão ou entidade gerenciadora do Poder Executivo federal por órgãos e entidades da Administração Pública estadual, distrital e municipal poderá ser exigida para fins de transferências voluntárias, não ficando sujeita ao limite de que trata o § 5º deste artigo se destinada à execução descentralizada de programa ou projeto federal e comprovada a compatibilidade dos preços registrados com os valores praticados no mercado na forma do art. 23 desta Lei."},{"k":"par","r":"§ 7º","t":"Para aquisição emergencial de medicamentos e material de consumo médico-hospitalar por órgãos e entidades da Administração Pública federal, estadual, distrital e municipal, a adesão à ata de registro de preços gerenciada pelo Ministério da Saúde não estará sujeita ao limite de que trata o § 5º deste artigo."},{"k":"par","r":"§ 8º","t":"Será vedada aos órgãos e entidades da Administração Pública federal a adesão à ata de registro de preços gerenciada por órgão ou entidade estadual, distrital ou municipal."}]},{"k":"sec","t":"Seção VI","s":"Do Registro Cadastral"},{"k":"art","n":"87","id":"a87","p":[{"k":"cap","r":"","t":"Para os fins desta Lei, os órgãos e entidades da Administração Pública deverão utilizar o sistema de registro cadastral unificado disponível no Portal Nacional de Contratações Públicas (PNCP), para efeito de cadastro unificado de licitantes e de contratados, na forma estabelecida em regulamento do Poder Executivo federal.","n":["(Incluído pela Lei nº 15.266, de 2025)"]},{"k":"par","r":"§ 1º","t":"O sistema de registro cadastral unificado será público e deverá ser amplamente divulgado e estar permanentemente aberto aos interessados, e será obrigatória a realização de chamamento público pela internet, no mínimo anualmente, para atualização dos registros existentes e para ingresso de novos interessados."},{"k":"par","r":"§ 2º","t":"É proibida a exigência, pelo órgão ou entidade licitante, de registro cadastral complementar para acesso a edital e anexos."},{"k":"par","r":"§ 3º","t":"A Administração poderá realizar licitação restrita a fornecedores cadastrados, atendidos os critérios, as condições e os limites estabelecidos em regulamento, bem como a ampla publicidade dos procedimentos para o cadastramento."},{"k":"par","r":"§ 4º","t":"Na hipótese a que se refere o § 3º deste artigo, será admitido fornecedor que realize seu cadastro dentro do prazo previsto no edital para apresentação de propostas."}]},{"k":"art","n":"88","id":"a88","p":[{"k":"cap","r":"","t":"Ao requerer, a qualquer tempo, inscrição no cadastro ou a sua atualização, o interessado fornecerá os elementos necessários exigidos para habilitação previstos nesta Lei."},{"k":"par","r":"§ 1º","t":"O inscrito, considerada sua área de atuação, será classificado por categorias, subdivididas em grupos, segundo a qualificação técnica e econômico-financeira avaliada, de acordo com regras objetivas divulgadas em sítio eletrônico oficial."},{"k":"par","r":"§ 2º","t":"Ao inscrito será fornecido certificado, renovável sempre que atualizar o registro."},{"k":"par","r":"§ 3º","t":"A atuação do contratado no cumprimento de obrigações assumidas será avaliada pelo contratante, que emitirá documento comprobatório da avaliação realizada, com menção ao seu desempenho na execução contratual, baseado em indicadores objetivamente definidos e aferidos, e a eventuais penalidades aplicadas, o que constará do registro cadastral em que a inscrição for realizada."},{"k":"par","r":"§ 4º","t":"A anotação do cumprimento de obrigações pelo contratado, de que trata o § 3º deste artigo, será condicionada à implantação e à regulamentação do cadastro de atesto de cumprimento de obrigações, apto à realização do registro de forma objetiva, em atendimento aos princípios da impessoalidade, da igualdade, da isonomia, da publicidade e da transparência, de modo a possibilitar a implementação de medidas de incentivo aos licitantes que possuírem ótimo desempenho anotado em seu registro cadastral."},{"k":"par","r":"§ 5º","t":"A qualquer tempo poderá ser alterado, suspenso ou cancelado o registro de inscrito que deixar de satisfazer exigências determinadas por esta Lei ou por regulamento."},{"k":"par","r":"§ 6º","t":"O interessado que requerer o cadastro na forma do caput deste artigo poderá participar de processo licitatório até a decisão da Administração, e a celebração do contrato ficará condicionada à emissão do certificado referido no § 2º deste artigo."}]},{"k":"cap","t":"TÍTULO III","s":"DOS CONTRATOS ADMINISTRATIVOS"},{"k":"cap","t":"CAPÍTULO I","s":"DA FORMALIZAÇÃO DOS CONTRATOS"},{"k":"art","n":"89","id":"a89","p":[{"k":"cap","r":"","t":"Os contratos de que trata esta Lei regular-se-ão pelas suas cláusulas e pelos preceitos de direito público, e a eles serão aplicados, supletivamente, os princípios da teoria geral dos contratos e as disposições de direito privado."},{"k":"par","r":"§ 1º","t":"Todo contrato deverá mencionar os nomes das partes e os de seus representantes, a finalidade, o ato que autorizou sua lavratura, o número do processo da licitação ou da contratação direta e a sujeição dos contratantes às normas desta Lei e às cláusulas contratuais."},{"k":"par","r":"§ 2º","t":"Os contratos deverão estabelecer com clareza e precisão as condições para sua execução, expressas em cláusulas que definam os direitos, as obrigações e as responsabilidades das partes, em conformidade com os termos do edital de licitação e os da proposta vencedora ou com os termos do ato que autorizou a contratação direta e os da respectiva proposta."}]},{"k":"art","n":"90","id":"a90","p":[{"k":"cap","r":"","t":"A Administração convocará regularmente o licitante vencedor para assinar o termo de contrato ou para aceitar ou retirar o instrumento equivalente, dentro do prazo e nas condições estabelecidas no edital de licitação, sob pena de decair o direito à contratação, sem prejuízo das sanções previstas nesta Lei."},{"k":"par","r":"§ 1º","t":"O prazo de convocação poderá ser prorrogado 1 (uma) vez, por igual período, mediante solicitação da parte durante seu transcurso, devidamente justificada, e desde que o motivo apresentado seja aceito pela Administração."},{"k":"par","r":"§ 2º","t":"Será facultado à Administração, quando o convocado não assinar o termo de contrato ou não aceitar ou não retirar o instrumento equivalente no prazo e nas condições estabelecidas, convocar os licitantes remanescentes, na ordem de classificação, para a celebração do contrato nas condições propostas pelo licitante vencedor."},{"k":"par","r":"§ 3º","t":"Decorrido o prazo de validade da proposta indicado no edital sem convocação para a contratação, ficarão os licitantes liberados dos compromissos assumidos."},{"k":"par","r":"§ 4º","t":"Na hipótese de nenhum dos licitantes aceitar a contratação nos termos do § 2º deste artigo, a Administração, observados o valor estimado e sua eventual atualização nos termos do edital, poderá:"},{"k":"inc","r":"I","t":"convocar os licitantes remanescentes para negociação, na ordem de classificação, com vistas à obtenção de preço melhor, mesmo que acima do preço do adjudicatário;"},{"k":"inc","r":"II","t":"adjudicar e celebrar o contrato nas condições ofertadas pelos licitantes remanescentes, atendida a ordem classificatória, quando frustrada a negociação de melhor condição."},{"k":"par","r":"§ 5º","t":"A recusa injustificada do adjudicatário em assinar o contrato ou em aceitar ou retirar o instrumento equivalente no prazo estabelecido pela Administração caracterizará o descumprimento total da obrigação assumida e o sujeitará às penalidades legalmente estabelecidas e à imediata perda da garantia de proposta em favor do órgão ou entidade licitante."},{"k":"par","r":"§ 6º","t":"A regra do § 5º não se aplicará aos licitantes remanescentes convocados na forma do inciso I do § 4º deste artigo."},{"k":"par","r":"§ 7º","t":"Será facultada à Administração a convocação dos demais licitantes classificados para a contratação de remanescente de obra, de serviço ou de fornecimento em consequência de rescisão contratual, observados os mesmos critérios estabelecidos nos §§ 2º e 4º deste artigo."},{"k":"par","r":"§ 8º","t":"Na situação de que trata o § 7º deste artigo, é autorizado o aproveitamento, em favor da nova contratada, de eventual saldo a liquidar inscrito em despesas empenhadas ou em restos a pagar não processados.","n":["(Incluído pela Lei nº 14.770, de 2023)"]},{"k":"par","r":"§ 9º","t":"Se frustradas as providências dos §§ 2º e 4º, o saldo de que trata o § 8º deste artigo poderá ser computado como efetiva disponibilidade para nova licitação, desde que identificada vantajosidade para a administração pública e mantido o objeto programado.","n":["(Incluído pela Lei nº 14.770, de 2023)"]}]},{"k":"art","n":"91","id":"a91","p":[{"k":"cap","r":"","t":"Os contratos e seus aditamentos terão forma escrita e serão juntados ao processo que tiver dado origem à contratação, divulgados e mantidos à disposição do público em sítio eletrônico oficial."},{"k":"par","r":"§ 1º","t":"Será admitida a manutenção em sigilo de contratos e de termos aditivos quando imprescindível à segurança da sociedade e do Estado, nos termos da legislação que regula o acesso à informação."},{"k":"par","r":"§ 2º","t":"Contratos relativos a direitos reais sobre imóveis serão formalizados por escritura pública lavrada em notas de tabelião, cujo teor deverá ser divulgado e mantido à disposição do público em sítio eletrônico oficial."},{"k":"par","r":"§ 3º","t":"Será admitida a forma eletrônica na celebração de contratos e de termos aditivos, atendidas as exigências previstas em regulamento."},{"k":"par","r":"§ 4º","t":"Antes de formalizar ou prorrogar o prazo de vigência do contrato, a Administração deverá verificar a regularidade fiscal do contratado, consultar o Cadastro Nacional de Empresas Inidôneas e Suspensas (Ceis) e o Cadastro Nacional de Empresas Punidas (Cnep), emitir as certidões negativas de inidoneidade, de impedimento e de débitos trabalhistas e juntá-las ao respectivo processo."}]},{"k":"art","n":"92","id":"a92","p":[{"k":"cap","r":"","t":"São necessárias em todo contrato cláusulas que estabeleçam:"},{"k":"inc","r":"I","t":"o objeto e seus elementos característicos;"},{"k":"inc","r":"II","t":"a vinculação ao edital de licitação e à proposta do licitante vencedor ou ao ato que tiver autorizado a contratação direta e à respectiva proposta;"},{"k":"inc","r":"III","t":"a legislação aplicável à execução do contrato, inclusive quanto aos casos omissos;"},{"k":"inc","r":"IV","t":"o regime de execução ou a forma de fornecimento;"},{"k":"inc","r":"V","t":"o preço e as condições de pagamento, os critérios, a data-base e a periodicidade do reajustamento de preços e os critérios de atualização monetária entre a data do adimplemento das obrigações e a do efetivo pagamento;"},{"k":"inc","r":"VI","t":"os critérios e a periodicidade da medição, quando for o caso, e o prazo para liquidação e para pagamento;"},{"k":"inc","r":"VII","t":"os prazos de início das etapas de execução, conclusão, entrega, observação e recebimento definitivo, quando for o caso;"},{"k":"inc","r":"VIII","t":"o crédito pelo qual correrá a despesa, com a indicação da classificação funcional programática e da categoria econômica;"},{"k":"inc","r":"IX","t":"a matriz de risco, quando for o caso;"},{"k":"inc","r":"X","t":"o prazo para resposta ao pedido de repactuação de preços, quando for o caso;"},{"k":"inc","r":"XI","t":"o prazo para resposta ao pedido de restabelecimento do equilíbrio econômico-financeiro, quando for o caso;"},{"k":"inc","r":"XII","t":"as garantias oferecidas para assegurar sua plena execução, quando exigidas, inclusive as que forem oferecidas pelo contratado no caso de antecipação de valores a título de pagamento;"},{"k":"inc","r":"XIII","t":"o prazo de garantia mínima do objeto, observados os prazos mínimos estabelecidos nesta Lei e nas normas técnicas aplicáveis, e as condições de manutenção e assistência técnica, quando for o caso;"},{"k":"inc","r":"XIV","t":"os direitos e as responsabilidades das partes, as penalidades cabíveis e os valores das multas e suas bases de cálculo;"},{"k":"inc","r":"XV","t":"as condições de importação e a data e a taxa de câmbio para conversão, quando for o caso;"},{"k":"inc","r":"XVI","t":"a obrigação do contratado de manter, durante toda a execução do contrato, em compatibilidade com as obrigações por ele assumidas, todas as condições exigidas para a habilitação na licitação, ou para a qualificação, na contratação direta;"},{"k":"inc","r":"XVII","t":"a obrigação de o contratado cumprir as exigências de reserva de cargos prevista em lei, bem como em outras normas específicas, para pessoa com deficiência, para reabilitado da Previdência Social e para aprendiz;"},{"k":"inc","r":"XVIII","t":"o modelo de gestão do contrato, observados os requisitos definidos em regulamento;"},{"k":"inc","r":"XIX","t":"os casos de extinção."},{"k":"par","r":"§ 1º","t":"Os contratos celebrados pela Administração Pública com pessoas físicas ou jurídicas, inclusive as domiciliadas no exterior, deverão conter cláusula que declare competente o foro da sede da Administração para dirimir qualquer questão contratual, ressalvadas as seguintes hipóteses:"},{"k":"inc","r":"I","t":"licitação internacional para a aquisição de bens e serviços cujo pagamento seja feito com o produto de financiamento concedido por organismo financeiro internacional de que o Brasil faça parte ou por agência estrangeira de cooperação;"},{"k":"inc","r":"II","t":"contratação com empresa estrangeira para a compra de equipamentos fabricados e entregues no exterior precedida de autorização do Chefe do Poder Executivo;"},{"k":"inc","r":"III","t":"aquisição de bens e serviços realizada por unidades administrativas com sede no exterior."},{"k":"par","r":"§ 2º","t":"De acordo com as peculiaridades de seu objeto e de seu regime de execução, o contrato conterá cláusula que preveja período antecedente à expedição da ordem de serviço para verificação de pendências, liberação de áreas ou adoção de outras providências cabíveis para a regularidade do início de sua execução."},{"k":"par","r":"§ 3º","t":"Independentemente do prazo de duração, o contrato deverá conter cláusula que estabeleça o índice de reajustamento de preço, com data-base vinculada à data do orçamento estimado, e poderá ser estabelecido mais de um índice específico ou setorial, em conformidade com a realidade de mercado dos respectivos insumos."},{"k":"par","r":"§ 4º","t":"Nos contratos de serviços contínuos, observado o interregno mínimo de 1 (um) ano, o critério de reajustamento de preços será por:"},{"k":"inc","r":"I","t":"reajustamento em sentido estrito, quando não houver regime de dedicação exclusiva de mão de obra ou predominância de mão de obra, mediante previsão de índices específicos ou setoriais;"},{"k":"inc","r":"II","t":"repactuação, quando houver regime de dedicação exclusiva de mão de obra ou predominância de mão de obra, mediante demonstração analítica da variação dos custos."},{"k":"par","r":"§ 5º","t":"Nos contratos de obras e serviços de engenharia, sempre que compatível com o regime de execução, a medição será mensal."},{"k":"par","r":"§ 6º","t":"Nos contratos para serviços contínuos com regime de dedicação exclusiva de mão de obra ou com predominância de mão de obra, o prazo para resposta ao pedido de repactuação de preços será preferencialmente de 1 (um) mês, contado da data do fornecimento da documentação prevista no § 6º do art. 135 desta Lei."},{"k":"par","r":"§ 7º","t":"Para efeito do disposto nesta Lei, consideram-se como adimplemento da obrigação contratual a prestação do serviço, a realização da obra ou a entrega do bem, ou parcela destes, bem como qualquer outro evento contratual a cuja ocorrência esteja vinculada a emissão de documento de cobrança.","n":["(Incluído pela Lei nº 14.770, de 2023)"]}]},{"k":"art","n":"93","id":"a93","p":[{"k":"cap","r":"","t":"Nas contratações de projetos ou de serviços técnicos especializados, inclusive daqueles que contemplem o desenvolvimento de programas e aplicações de internet para computadores, máquinas, equipamentos e dispositivos de tratamento e de comunicação da informação (software) - e a respectiva documentação técnica associada -, o autor deverá ceder todos os direitos patrimoniais a eles relativos para a Administração Pública, hipótese em que poderão ser livremente utilizados e alterados por ela em outras ocasiões, sem necessidade de nova autorização de seu autor."},{"k":"par","r":"§ 1º","t":"Quando o projeto se referir a obra imaterial de caráter tecnológico, insuscetível de privilégio, a cessão dos direitos a que se refere o caput deste artigo incluirá o fornecimento de todos os dados, documentos e elementos de informação pertinentes à tecnologia de concepção, desenvolvimento, fixação em suporte físico de qualquer natureza e aplicação da obra."},{"k":"par","r":"§ 2º","t":"É facultado à Administração Pública deixar de exigir a cessão de direitos a que se refere o caput deste artigo quando o objeto da contratação envolver atividade de pesquisa e desenvolvimento de caráter científico, tecnológico ou de inovação, considerados os princípios e os mecanismos instituídos pela Lei nº 10.973, de 2 de dezembro de 2004."},{"k":"par","r":"§ 3º","t":"Na hipótese de posterior alteração do projeto pela Administração Pública, o autor deverá ser comunicado, e os registros serão promovidos nos órgãos ou entidades competentes."}]},{"k":"art","n":"94","id":"a94","p":[{"k":"cap","r":"","t":"A divulgação no Portal Nacional de Contratações Públicas (PNCP) é condição indispensável para a eficácia do contrato e de seus aditamentos e deverá ocorrer nos seguintes prazos, contados da data de sua assinatura:"},{"k":"inc","r":"I","t":"20 (vinte) dias úteis, no caso de licitação;"},{"k":"inc","r":"II","t":"10 (dez) dias úteis, no caso de contratação direta."},{"k":"par","r":"§ 1º","t":"Os contratos celebrados em caso de urgência terão eficácia a partir de sua assinatura e deverão ser publicados nos prazos previstos nos incisos I e II do caput deste artigo, sob pena de nulidade."},{"k":"par","r":"§ 2º","t":"A divulgação de que trata o caput deste artigo, quando referente à contratação de profissional do setor artístico por inexigibilidade, deverá identificar os custos do cachê do artista, dos músicos ou da banda, quando houver, do transporte, da hospedagem, da infraestrutura, da logística do evento e das demais despesas específicas."},{"k":"par","r":"§ 3º","t":"No caso de obras, a Administração divulgará em sítio eletrônico oficial, em até 25 (vinte e cinco) dias úteis após a assinatura do contrato, os quantitativos e os preços unitários e totais que contratar e, em até 45 (quarenta e cinco) dias úteis após a conclusão do contrato, os quantitativos executados e os preços praticados."},{"k":"par","r":"§ 4º","t":"","n":["(VETADO)"],"rev":1},{"k":"par","r":"§ 5º","t":"","n":["(VETADO)"],"rev":1}]},{"k":"art","n":"95","id":"a95","p":[{"k":"cap","r":"","t":"O instrumento de contrato é obrigatório, salvo nas seguintes hipóteses, em que a Administração poderá substituí-lo por outro instrumento hábil, como carta-contrato, nota de empenho de despesa, autorização de compra ou ordem de execução de serviço:"},{"k":"inc","r":"I","t":"dispensa de licitação em razão de valor;"},{"k":"inc","r":"II","t":"compras com entrega imediata e integral dos bens adquiridos e dos quais não resultem obrigações futuras, inclusive quanto a assistência técnica, independentemente de seu valor."},{"k":"par","r":"§ 1º","t":"Às hipóteses de substituição do instrumento de contrato, aplica-se, no que couber, o disposto no art. 92 desta Lei."},{"k":"par","r":"§ 2º","t":"É nulo e de nenhum efeito o contrato verbal com a Administração, salvo o de pequenas compras ou o de prestação de serviços de pronto pagamento, assim entendidos aqueles de valor não superior a R$ 10.000,00 (dez mil reais).","n":["(Vide Decreto nº 12.343, de 2024)","(Vide Decreto nº 12.807, de 2025)"]}]},{"k":"cap","t":"CAPÍTULO II","s":"DAS GARANTIAS"},{"k":"art","n":"96","id":"a96","p":[{"k":"cap","r":"","t":"A critério da autoridade competente, em cada caso, poderá ser exigida, mediante previsão no edital, prestação de garantia nas contratações de obras, serviços e fornecimentos."},{"k":"par","r":"§ 1º","t":"Caberá ao contratado optar por uma das seguintes modalidades de garantia:"},{"k":"inc","r":"I","t":"caução em dinheiro ou em títulos da dívida pública emitidos sob a forma escritural, mediante registro em sistema centralizado de liquidação e de custódia autorizado pelo Banco Central do Brasil, e avaliados por seus valores econômicos, conforme definido pelo Ministério da Economia;"},{"k":"inc","r":"II","t":"seguro-garantia;"},{"k":"inc","r":"III","t":"fiança bancária emitida por banco ou instituição financeira devidamente autorizada a operar no País pelo Banco Central do Brasil."},{"k":"inc","r":"IV","t":"título de capitalização custeado por pagamento único, com resgate pelo valor total.","n":["(Incluído pela Lei nº 14.770, de 2023)"]},{"k":"par","r":"§ 2º","t":"Na hipótese de suspensão do contrato por ordem ou inadimplemento da Administração, o contratado ficará desobrigado de renovar a garantia ou de endossar a apólice de seguro até a ordem de reinício da execução ou o adimplemento pela Administração."},{"k":"par","r":"§ 3º","t":"O edital fixará prazo mínimo de 1 (um) mês, contado da data de homologação da licitação e anterior à assinatura do contrato, para a prestação da garantia pelo contratado quando optar pela modalidade prevista no inciso II do § 1º deste artigo."}]},{"k":"art","n":"97","id":"a97","p":[{"k":"cap","r":"","t":"O seguro-garantia tem por objetivo garantir o fiel cumprimento das obrigações assumidas pelo contratado perante à Administração, inclusive as multas, os prejuízos e as indenizações decorrentes de inadimplemento, observadas as seguintes regras nas contratações regidas por esta Lei:"},{"k":"inc","r":"I","t":"o prazo de vigência da apólice será igual ou superior ao prazo estabelecido no contrato principal e deverá acompanhar as modificações referentes à vigência deste mediante a emissão do respectivo endosso pela seguradora;"},{"k":"inc","r":"II","t":"o seguro-garantia continuará em vigor mesmo se o contratado não tiver pago o prêmio nas datas convencionadas."},{"k":"par","r":"Parágrafo único","t":"Nos contratos de execução continuada ou de fornecimento contínuo de bens e serviços, será permitida a substituição da apólice de seguro-garantia na data de renovação ou de aniversário, desde que mantidas as mesmas condições e coberturas da apólice vigente e desde que nenhum período fique descoberto, ressalvado o disposto no § 2º do art. 96 desta Lei."}]},{"k":"art","n":"98","id":"a98","p":[{"k":"cap","r":"","t":"Nas contratações de obras, serviços e fornecimentos, a garantia poderá ser de até 5% (cinco por cento) do valor inicial do contrato, autorizada a majoração desse percentual para até 10% (dez por cento), desde que justificada mediante análise da complexidade técnica e dos riscos envolvidos."},{"k":"par","r":"Parágrafo único","t":"Nas contratações de serviços e fornecimentos contínuos com vigência superior a 1 (um) ano, assim como nas subsequentes prorrogações, será utilizado o valor anual do contrato para definição e aplicação dos percentuais previstos no caput deste artigo."}]},{"k":"art","n":"99","id":"a99","p":[{"k":"cap","r":"","t":"Nas contratações de obras e serviços de engenharia de grande vulto, poderá ser exigida a prestação de garantia, na modalidade seguro-garantia, com cláusula de retomada prevista no art. 102 desta Lei, em percentual equivalente a até 30% (trinta por cento) do valor inicial do contrato."}]},{"k":"art","n":"100","id":"a100","p":[{"k":"cap","r":"","t":"A garantia prestada pelo contratado será liberada ou restituída após a fiel execução do contrato ou após a sua extinção por culpa exclusiva da Administração e, quando em dinheiro, atualizada monetariamente."}]},{"k":"art","n":"101","id":"a101","p":[{"k":"cap","r":"","t":"Nos casos de contratos que impliquem a entrega de bens pela Administração, dos quais o contratado ficará depositário, o valor desses bens deverá ser acrescido ao valor da garantia."}]},{"k":"art","n":"102","id":"a102","p":[{"k":"cap","r":"","t":"Na contratação de obras e serviços de engenharia, o edital poderá exigir a prestação da garantia na modalidade seguro-garantia e prever a obrigação de a seguradora, em caso de inadimplemento pelo contratado, assumir a execução e concluir o objeto do contrato, hipótese em que:"},{"k":"inc","r":"I","t":"a seguradora deverá firmar o contrato, inclusive os aditivos, como interveniente anuente e poderá:"},{"k":"ali","r":"a)","t":"ter livre acesso às instalações em que for executado o contrato principal;"},{"k":"ali","r":"b)","t":"acompanhar a execução do contrato principal;"},{"k":"ali","r":"c)","t":"ter acesso a auditoria técnica e contábil;"},{"k":"ali","r":"d)","t":"requerer esclarecimentos ao responsável técnico pela obra ou pelo fornecimento;"},{"k":"inc","r":"II","t":"a emissão de empenho em nome da seguradora, ou a quem ela indicar para a conclusão do contrato, será autorizada desde que demonstrada sua regularidade fiscal;"},{"k":"inc","r":"III","t":"a seguradora poderá subcontratar a conclusão do contrato, total ou parcialmente."},{"k":"par","r":"Parágrafo único","t":"Na hipótese de inadimplemento do contratado, serão observadas as seguintes disposições:"},{"k":"inc","r":"I","t":"caso a seguradora execute e conclua o objeto do contrato, estará isenta da obrigação de pagar a importância segurada indicada na apólice;"},{"k":"inc","r":"II","t":"caso a seguradora não assuma a execução do contrato, pagará a integralidade da importância segurada indicada na apólice."}]},{"k":"cap","t":"CAPÍTULO III","s":"DA ALOCAÇÃO DE RISCOS"},{"k":"art","n":"103","id":"a103","p":[{"k":"cap","r":"","t":"O contrato poderá identificar os riscos contratuais previstos e presumíveis e prever matriz de alocação de riscos, alocando-os entre contratante e contratado, mediante indicação daqueles a serem assumidos pelo setor público ou pelo setor privado ou daqueles a serem compartilhados."},{"k":"par","r":"§ 1º","t":"A alocação de riscos de que trata o caput deste artigo considerará, em compatibilidade com as obrigações e os encargos atribuídos às partes no contrato, a natureza do risco, o beneficiário das prestações a que se vincula e a capacidade de cada setor para melhor gerenciá-lo."},{"k":"par","r":"§ 2º","t":"Os riscos que tenham cobertura oferecida por seguradoras serão preferencialmente transferidos ao contratado."},{"k":"par","r":"§ 3º","t":"A alocação dos riscos contratuais será quantificada para fins de projeção dos reflexos de seus custos no valor estimado da contratação."},{"k":"par","r":"§ 4º","t":"A matriz de alocação de riscos definirá o equilíbrio econômico-financeiro inicial do contrato em relação a eventos supervenientes e deverá ser observada na solução de eventuais pleitos das partes."},{"k":"par","r":"§ 5º","t":"Sempre que atendidas as condições do contrato e da matriz de alocação de riscos, será considerado mantido o equilíbrio econômico-financeiro, renunciando as partes aos pedidos de restabelecimento do equilíbrio relacionados aos riscos assumidos, exceto no que se refere:"},{"k":"inc","r":"I","t":"às alterações unilaterais determinadas pela Administração, nas hipóteses do inciso I do caput do art. 124 desta Lei;"},{"k":"inc","r":"II","t":"ao aumento ou à redução, por legislação superveniente, dos tributos diretamente pagos pelo contratado em decorrência do contrato."},{"k":"par","r":"§ 6º","t":"Na alocação de que trata o caput deste artigo, poderão ser adotados métodos e padrões usualmente utilizados por entidades públicas e privadas, e os ministérios e secretarias supervisores dos órgãos e das entidades da Administração Pública poderão definir os parâmetros e o detalhamento dos procedimentos necessários a sua identificação, alocação e quantificação financeira."}]},{"k":"cap","t":"CAPÍTULO IV","s":"DAS PRERROGATIVAS DA ADMINISTRAÇÃO"},{"k":"art","n":"104","id":"a104","p":[{"k":"cap","r":"","t":"O regime jurídico dos contratos instituído por esta Lei confere à Administração, em relação a eles, as prerrogativas de:"},{"k":"inc","r":"I","t":"modificá-los, unilateralmente, para melhor adequação às finalidades de interesse público, respeitados os direitos do contratado;"},{"k":"inc","r":"II","t":"extingui-los, unilateralmente, nos casos especificados nesta Lei;"},{"k":"inc","r":"III","t":"fiscalizar sua execução;"},{"k":"inc","r":"IV","t":"aplicar sanções motivadas pela inexecução total ou parcial do ajuste;"},{"k":"inc","r":"V","t":"ocupar provisoriamente bens móveis e imóveis e utilizar pessoal e serviços vinculados ao objeto do contrato nas hipóteses de:"},{"k":"ali","r":"a)","t":"risco à prestação de serviços essenciais;"},{"k":"ali","r":"b)","t":"necessidade de acautelar apuração administrativa de faltas contratuais pelo contratado, inclusive após extinção do contrato."},{"k":"par","r":"§ 1º","t":"As cláusulas econômico-financeiras e monetárias dos contratos não poderão ser alteradas sem prévia concordância do contratado."},{"k":"par","r":"§ 2º","t":"Na hipótese prevista no inciso I do caput deste artigo, as cláusulas econômico-financeiras do contrato deverão ser revistas para que se mantenha o equilíbrio contratual."}]},{"k":"cap","t":"CAPÍTULO V","s":"DA DURAÇÃO DOS CONTRATOS"},{"k":"art","n":"105","id":"a105","p":[{"k":"cap","r":"","t":"A duração dos contratos regidos por esta Lei será a prevista em edital, e deverão ser observadas, no momento da contratação e a cada exercício financeiro, a disponibilidade de créditos orçamentários, bem como a previsão no plano plurianual, quando ultrapassar 1 (um) exercício financeiro."},{"k":"par","r":"Parágrafo único","t":"Não serão objeto de cancelamento automático os restos a pagar vinculados a contratos de duração plurianual, senão depois de encerrada a vigência destes, nem os vinculados a contratos rescindidos, nos casos dos §§ 8º e 9º do art. 90 desta Lei.","n":["(Incluído pela Lei nº 14.770, de 2023)"]}]},{"k":"art","n":"106","id":"a106","p":[{"k":"cap","r":"","t":"A Administração poderá celebrar contratos com prazo de até 5 (cinco) anos nas hipóteses de serviços e fornecimentos contínuos, observadas as seguintes diretrizes:"},{"k":"inc","r":"I","t":"a autoridade competente do órgão ou entidade contratante deverá atestar a maior vantagem econômica vislumbrada em razão da contratação plurianual;"},{"k":"inc","r":"II","t":"a Administração deverá atestar, no início da contratação e de cada exercício, a existência de créditos orçamentários vinculados à contratação e a vantagem em sua manutenção;"},{"k":"inc","r":"III","t":"a Administração terá a opção de extinguir o contrato, sem ônus, quando não dispuser de créditos orçamentários para sua continuidade ou quando entender que o contrato não mais lhe oferece vantagem."},{"k":"par","r":"§ 1º","t":"A extinção mencionada no inciso III do caput deste artigo ocorrerá apenas na próxima data de aniversário do contrato e não poderá ocorrer em prazo inferior a 2 (dois) meses, contado da referida data."},{"k":"par","r":"§ 2º","t":"Aplica-se o disposto neste artigo ao aluguel de equipamentos e à utilização de programas de informática."}]},{"k":"art","n":"107","id":"a107","p":[{"k":"cap","r":"","t":"Os contratos de serviços e fornecimentos contínuos poderão ser prorrogados sucessivamente, respeitada a vigência máxima decenal, desde que haja previsão em edital e que a autoridade competente ateste que as condições e os preços permanecem vantajosos para a Administração, permitida a negociação com o contratado ou a extinção contratual sem ônus para qualquer das partes."}]},{"k":"art","n":"108","id":"a108","p":[{"k":"cap","r":"","t":"A Administração poderá celebrar contratos com prazo de até 10 (dez) anos nas hipóteses previstas nas alíneas “f” e “g” do inciso IV e nos incisos V, VI, XII e XVI do caput do art. 75 desta Lei."}]},{"k":"art","n":"109","id":"a109","p":[{"k":"cap","r":"","t":"A Administração poderá estabelecer a vigência por prazo indeterminado nos contratos em que seja usuária de serviço público oferecido em regime de monopólio, desde que comprovada, a cada exercício financeiro, a existência de créditos orçamentários vinculados à contratação."}]},{"k":"art","n":"110","id":"a110","p":[{"k":"cap","r":"","t":"Na contratação que gere receita e no contrato de eficiência que gere economia para a Administração, os prazos serão de:"},{"k":"inc","r":"I","t":"até 10 (dez) anos, nos contratos sem investimento;"},{"k":"inc","r":"II","t":"até 35 (trinta e cinco) anos, nos contratos com investimento, assim considerados aqueles que impliquem a elaboração de benfeitorias permanentes, realizadas exclusivamente a expensas do contratado, que serão revertidas ao patrimônio da Administração Pública ao término do contrato."}]},{"k":"art","n":"111","id":"a111","p":[{"k":"cap","r":"","t":"Na contratação que previr a conclusão de escopo predefinido, o prazo de vigência será automaticamente prorrogado quando seu objeto não for concluído no período firmado no contrato."},{"k":"par","r":"Parágrafo único","t":"Quando a não conclusão decorrer de culpa do contratado:"},{"k":"inc","r":"I","t":"o contratado será constituído em mora, aplicáveis a ele as respectivas sanções administrativas;"},{"k":"inc","r":"II","t":"a Administração poderá optar pela extinção do contrato e, nesse caso, adotará as medidas admitidas em lei para a continuidade da execução contratual."}]},{"k":"art","n":"112","id":"a112","p":[{"k":"cap","r":"","t":"Os prazos contratuais previstos nesta Lei não excluem nem revogam os prazos contratuais previstos em lei especial."}]},{"k":"art","n":"113","id":"a113","p":[{"k":"cap","r":"","t":"O contrato firmado sob o regime de fornecimento e prestação de serviço associado terá sua vigência máxima definida pela soma do prazo relativo ao fornecimento inicial ou à entrega da obra com o prazo relativo ao serviço de operação e manutenção, este limitado a 5 (cinco) anos contados da data de recebimento do objeto inicial, autorizada a prorrogação na forma do art. 107 desta Lei."}]},{"k":"art","n":"114","id":"a114","p":[{"k":"cap","r":"","t":"O contrato que previr a operação continuada de sistemas estruturantes de tecnologia da informação poderá ter vigência máxima de 15 (quinze) anos."}]},{"k":"cap","t":"CAPÍTULO VI","s":"DA EXECUÇÃO DOS CONTRATOS"},{"k":"art","n":"115","id":"a115","p":[{"k":"cap","r":"","t":"O contrato deverá ser executado fielmente pelas partes, de acordo com as cláusulas avençadas e as normas desta Lei, e cada parte responderá pelas consequências de sua inexecução total ou parcial."},{"k":"par","r":"§ 1º","t":"É proibido à Administração retardar imotivadamente a execução de obra ou serviço, ou de suas parcelas, inclusive na hipótese de posse do respectivo chefe do Poder Executivo ou de novo titular no órgão ou entidade contratante."},{"k":"par","r":"§ 2º","t":"","n":["(VETADO)"],"rev":1},{"k":"par","r":"§ 3º","t":"","n":["(VETADO)"],"rev":1},{"k":"par","r":"§ 4º","t":"Nas contratações de obras e serviços de engenharia, sempre que a responsabilidade pelo licenciamento ambiental for da Administração, a manifestação prévia ou licença prévia, quando cabíveis, deverão ser obtidas antes da divulgação do edital.","n":["(Promulgação partes vetadas)"]},{"k":"par","r":"§ 5º","t":"Em caso de impedimento, ordem de paralisação ou suspensão do contrato, o cronograma de execução será prorrogado automaticamente pelo tempo correspondente, anotadas tais circunstâncias mediante simples apostila."},{"k":"par","r":"§ 6º","t":"Nas contratações de obras, verificada a ocorrência do disposto no § 5º deste artigo por mais de 1 (um) mês, a Administração deverá divulgar, em sítio eletrônico oficial e em placa a ser afixada em local da obra de fácil visualização pelos cidadãos, aviso público de obra paralisada, com o motivo e o responsável pela inexecução temporária do objeto do contrato e a data prevista para o reinício da sua execução."},{"k":"par","r":"§ 7º","t":"Os textos com as informações de que trata o § 6º deste artigo deverão ser elaborados pela Administração."}]},{"k":"art","n":"116","id":"a116","p":[{"k":"cap","r":"","t":"Ao longo de toda a execução do contrato, o contratado deverá cumprir a reserva de cargos prevista em lei para pessoa com deficiência, para reabilitado da Previdência Social ou para aprendiz, bem como as reservas de cargos previstas em outras normas específicas."},{"k":"par","r":"Parágrafo único","t":"Sempre que solicitado pela Administração, o contratado deverá comprovar o cumprimento da reserva de cargos a que se refere o caput deste artigo, com a indicação dos empregados que preencherem as referidas vagas."}]},{"k":"art","n":"117","id":"a117","p":[{"k":"cap","r":"","t":"A execução do contrato deverá ser acompanhada e fiscalizada por 1 (um) ou mais fiscais do contrato, representantes da Administração especialmente designados conforme requisitos estabelecidos no art. 7º desta Lei, ou pelos respectivos substitutos, permitida a contratação de terceiros para assisti-los e subsidiá-los com informações pertinentes a essa atribuição."},{"k":"par","r":"§ 1º","t":"O fiscal do contrato anotará em registro próprio todas as ocorrências relacionadas à execução do contrato, determinando o que for necessário para a regularização das faltas ou dos defeitos observados."},{"k":"par","r":"§ 2º","t":"O fiscal do contrato informará a seus superiores, em tempo hábil para a adoção das medidas convenientes, a situação que demandar decisão ou providência que ultrapasse sua competência."},{"k":"par","r":"§ 3º","t":"O fiscal do contrato será auxiliado pelos órgãos de assessoramento jurídico e de controle interno da Administração, que deverão dirimir dúvidas e subsidiá-lo com informações relevantes para prevenir riscos na execução contratual."},{"k":"par","r":"§ 4º","t":"Na hipótese da contratação de terceiros prevista no caput deste artigo, deverão ser observadas as seguintes regras:"},{"k":"inc","r":"I","t":"a empresa ou o profissional contratado assumirá responsabilidade civil objetiva pela veracidade e pela precisão das informações prestadas, firmará termo de compromisso de confidencialidade e não poderá exercer atribuição própria e exclusiva de fiscal de contrato;"},{"k":"inc","r":"II","t":"a contratação de terceiros não eximirá de responsabilidade o fiscal do contrato, nos limites das informações recebidas do terceiro contratado."}]},{"k":"art","n":"118","id":"a118","p":[{"k":"cap","r":"","t":"O contratado deverá manter preposto aceito pela Administração no local da obra ou do serviço para representá-lo na execução do contrato."}]},{"k":"art","n":"119","id":"a119","p":[{"k":"cap","r":"","t":"O contratado será obrigado a reparar, corrigir, remover, reconstruir ou substituir, a suas expensas, no total ou em parte, o objeto do contrato em que se verificarem vícios, defeitos ou incorreções resultantes de sua execução ou de materiais nela empregados."}]},{"k":"art","n":"120","id":"a120","p":[{"k":"cap","r":"","t":"O contratado será responsável pelos danos causados diretamente à Administração ou a terceiros em razão da execução do contrato, e não excluirá nem reduzirá essa responsabilidade a fiscalização ou o acompanhamento pelo contratante."}]},{"k":"art","n":"121","id":"a121","p":[{"k":"cap","r":"","t":"Somente o contratado será responsável pelos encargos trabalhistas, previdenciários, fiscais e comerciais resultantes da execução do contrato."},{"k":"par","r":"§ 1º","t":"A inadimplência do contratado em relação aos encargos trabalhistas, fiscais e comerciais não transferirá à Administração a responsabilidade pelo seu pagamento e não poderá onerar o objeto do contrato nem restringir a regularização e o uso das obras e das edificações, inclusive perante o registro de imóveis, ressalvada a hipótese prevista no § 2º deste artigo."},{"k":"par","r":"§ 2º","t":"Exclusivamente nas contratações de serviços contínuos com regime de dedicação exclusiva de mão de obra, a Administração responderá solidariamente pelos encargos previdenciários e subsidiariamente pelos encargos trabalhistas se comprovada falha na fiscalização do cumprimento das obrigações do contratado."},{"k":"par","r":"§ 3º","t":"Nas contratações de serviços contínuos com regime de dedicação exclusiva de mão de obra, para assegurar o cumprimento de obrigações trabalhistas pelo contratado, a Administração, mediante disposição em edital ou em contrato, poderá, entre outras medidas:"},{"k":"inc","r":"I","t":"exigir caução, fiança bancária ou contratação de seguro-garantia com cobertura para verbas rescisórias inadimplidas;"},{"k":"inc","r":"II","t":"condicionar o pagamento à comprovação de quitação das obrigações trabalhistas vencidas relativas ao contrato;"},{"k":"inc","r":"III","t":"efetuar o depósito de valores em conta vinculada;"},{"k":"inc","r":"IV","t":"em caso de inadimplemento, efetuar diretamente o pagamento das verbas trabalhistas, que serão deduzidas do pagamento devido ao contratado;"},{"k":"inc","r":"V","t":"estabelecer que os valores destinados a férias, a décimo terceiro salário, a ausências legais e a verbas rescisórias dos empregados do contratado que participarem da execução dos serviços contratados serão pagos pelo contratante ao contratado somente na ocorrência do fato gerador."},{"k":"par","r":"§ 4º","t":"Os valores depositados na conta vinculada a que se refere o inciso III do § 3º deste artigo são absolutamente impenhoráveis."},{"k":"par","r":"§ 5º","t":"O recolhimento das contribuições previdenciárias observará o disposto no art. 31 da Lei nº 8.212, de 24 de julho de 1991."}]},{"k":"art","n":"122","id":"a122","p":[{"k":"cap","r":"","t":"Na execução do contrato e sem prejuízo das responsabilidades contratuais e legais, o contratado poderá subcontratar partes da obra, do serviço ou do fornecimento até o limite autorizado, em cada caso, pela Administração."},{"k":"par","r":"§ 1º","t":"O contratado apresentará à Administração documentação que comprove a capacidade técnica do subcontratado, que será avaliada e juntada aos autos do processo correspondente."},{"k":"par","r":"§ 2º","t":"Regulamento ou edital de licitação poderão vedar, restringir ou estabelecer condições para a subcontratação."},{"k":"par","r":"§ 3º","t":"Será vedada a subcontratação de pessoa física ou jurídica, se aquela ou os dirigentes desta mantiverem vínculo de natureza técnica, comercial, econômica, financeira, trabalhista ou civil com dirigente do órgão ou entidade contratante ou com agente público que desempenhe função na licitação ou atue na fiscalização ou na gestão do contrato, ou se deles forem cônjuge, companheiro ou parente em linha reta, colateral, ou por afinidade, até o terceiro grau, devendo essa proibição constar expressamente do edital de licitação."}]},{"k":"art","n":"123","id":"a123","p":[{"k":"cap","r":"","t":"A Administração terá o dever de explicitamente emitir decisão sobre todas as solicitações e reclamações relacionadas à execução dos contratos regidos por esta Lei, ressalvados os requerimentos manifestamente impertinentes, meramente protelatórios ou de nenhum interesse para a boa execução do contrato."},{"k":"par","r":"Parágrafo único","t":"Salvo disposição legal ou cláusula contratual que estabeleça prazo específico, concluída a instrução do requerimento, a Administração terá o prazo de 1 (um) mês para decidir, admitida a prorrogação motivada por igual período."}]},{"k":"cap","t":"CAPÍTULO VII","s":"DA ALTERAÇÃO DOS CONTRATOS E DOS PREÇOS"},{"k":"art","n":"124","id":"a124","p":[{"k":"cap","r":"","t":"Os contratos regidos por esta Lei poderão ser alterados, com as devidas justificativas, nos seguintes casos:"},{"k":"inc","r":"I","t":"unilateralmente pela Administração:"},{"k":"ali","r":"a)","t":"quando houver modificação do projeto ou das especificações, para melhor adequação técnica a seus objetivos;"},{"k":"ali","r":"b)","t":"quando for necessária a modificação do valor contratual em decorrência de acréscimo ou diminuição quantitativa de seu objeto, nos limites permitidos por esta Lei;"},{"k":"inc","r":"II","t":"por acordo entre as partes:"},{"k":"ali","r":"a)","t":"quando conveniente a substituição da garantia de execução;"},{"k":"ali","r":"b)","t":"quando necessária a modificação do regime de execução da obra ou do serviço, bem como do modo de fornecimento, em face de verificação técnica da inaplicabilidade dos termos contratuais originários;"},{"k":"ali","r":"c)","t":"quando necessária a modificação da forma de pagamento por imposição de circunstâncias supervenientes, mantido o valor inicial atualizado e vedada a antecipação do pagamento em relação ao cronograma financeiro fixado sem a correspondente contraprestação de fornecimento de bens ou execução de obra ou serviço;"},{"k":"ali","r":"d)","t":"para restabelecer o equilíbrio econômico-financeiro inicial do contrato em caso de força maior, caso fortuito ou fato do príncipe ou em decorrência de fatos imprevisíveis ou previsíveis de consequências incalculáveis, que inviabilizem a execução do contrato tal como pactuado, respeitada, em qualquer caso, a repartição objetiva de risco estabelecida no contrato."},{"k":"par","r":"§ 1º","t":"Se forem decorrentes de falhas de projeto, as alterações de contratos de obras e serviços de engenharia ensejarão apuração de responsabilidade do responsável técnico e adoção das providências necessárias para o ressarcimento dos danos causados à Administração."},{"k":"par","r":"§ 2º","t":"Será aplicado o disposto na alínea “d” do inciso II do caput deste artigo às contratações de obras e serviços de engenharia, quando a execução for obstada pelo atraso na conclusão de procedimentos de desapropriação, desocupação, servidão administrativa ou licenciamento ambiental, por circunstâncias alheias ao contratado."}]},{"k":"art","n":"125","id":"a125","p":[{"k":"cap","r":"","t":"Nas alterações unilaterais a que se refere o inciso I do caput do art. 124 desta Lei, o contratado será obrigado a aceitar, nas mesmas condições contratuais, acréscimos ou supressões de até 25% (vinte e cinco por cento) do valor inicial atualizado do contrato que se fizerem nas obras, nos serviços ou nas compras, e, no caso de reforma de edifício ou de equipamento, o limite para os acréscimos será de 50% (cinquenta por cento)."}]},{"k":"art","n":"126","id":"a126","p":[{"k":"cap","r":"","t":"As alterações unilaterais a que se refere o inciso I do caput do art. 124 desta Lei não poderão transfigurar o objeto da contratação."}]},{"k":"art","n":"127","id":"a127","p":[{"k":"cap","r":"","t":"Se o contrato não contemplar preços unitários para obras ou serviços cujo aditamento se fizer necessário, esses serão fixados por meio da aplicação da relação geral entre os valores da proposta e o do orçamento-base da Administração sobre os preços referenciais ou de mercado vigentes na data do aditamento, respeitados os limites estabelecidos no art. 125 desta Lei."}]},{"k":"art","n":"128","id":"a128","p":[{"k":"cap","r":"","t":"Nas contratações de obras e serviços de engenharia, a diferença percentual entre o valor global do contrato e o preço global de referência não poderá ser reduzida em favor do contratado em decorrência de aditamentos que modifiquem a planilha orçamentária."}]},{"k":"art","n":"129","id":"a129","p":[{"k":"cap","r":"","t":"Nas alterações contratuais para supressão de obras, bens ou serviços, se o contratado já houver adquirido os materiais e os colocado no local dos trabalhos, estes deverão ser pagos pela Administração pelos custos de aquisição regularmente comprovados e monetariamente reajustados, podendo caber indenização por outros danos eventualmente decorrentes da supressão, desde que regularmente comprovados."}]},{"k":"art","n":"130","id":"a130","p":[{"k":"cap","r":"","t":"Caso haja alteração unilateral do contrato que aumente ou diminua os encargos do contratado, a Administração deverá restabelecer, no mesmo termo aditivo, o equilíbrio econômico-financeiro inicial."}]},{"k":"art","n":"131","id":"a131","p":[{"k":"cap","r":"","t":"A extinção do contrato não configurará óbice para o reconhecimento do desequilíbrio econômico- financeiro, hipótese em que será concedida indenização por meio de termo indenizatório."},{"k":"par","r":"Parágrafo único","t":"O pedido de restabelecimento do equilíbrio econômico-financeiro deverá ser formulado durante a vigência do contrato e antes de eventual prorrogação nos termos do art. 107 desta Lei."}]},{"k":"art","n":"132","id":"a132","p":[{"k":"cap","r":"","t":"A formalização do termo aditivo é condição para a execução, pelo contratado, das prestações determinadas pela Administração no curso da execução do contrato, salvo nos casos de justificada necessidade de antecipação de seus efeitos, hipótese em que a formalização deverá ocorrer no prazo máximo de 1 (um) mês."}]},{"k":"art","n":"133","id":"a133","p":[{"k":"cap","r":"","t":"Nas hipóteses em que for adotada a contratação integrada ou semi-integrada, é vedada a alteração dos valores contratuais, exceto nos seguintes casos:"},{"k":"inc","r":"I","t":"para restabelecimento do equilíbrio econômico-financeiro decorrente de caso fortuito ou força maior;"},{"k":"inc","r":"II","t":"por necessidade de alteração do projeto ou das especificações para melhor adequação técnica aos objetivos da contratação, a pedido da Administração, desde que não decorrente de erros ou omissões por parte do contratado, observados os limites estabelecidos no art. 125 desta Lei;"},{"k":"inc","r":"III","t":"por necessidade de alteração do projeto nas contratações semi-integradas, nos termos do § 5º do art. 46 desta Lei;"},{"k":"inc","r":"IV","t":"por ocorrência de evento superveniente alocado na matriz de riscos como de responsabilidade da Administração."}]},{"k":"art","n":"134","id":"a134","p":[{"k":"cap","r":"","t":"Os preços contratados serão alterados, para mais ou para menos, conforme o caso, se houver, após a data da apresentação da proposta, criação, alteração ou extinção de quaisquer tributos ou encargos legais ou a superveniência de disposições legais, com comprovada repercussão sobre os preços contratados."}]},{"k":"art","n":"135","id":"a135","p":[{"k":"cap","r":"","t":"Os preços dos contratos para serviços contínuos com regime de dedicação exclusiva de mão de obra ou com predominância de mão de obra serão repactuados para manutenção do equilíbrio econômico-financeiro, mediante demonstração analítica da variação dos custos contratuais, com data vinculada:"},{"k":"inc","r":"I","t":"à da apresentação da proposta, para custos decorrentes do mercado;"},{"k":"inc","r":"II","t":"ao acordo, à convenção coletiva ou ao dissídio coletivo ao qual a proposta esteja vinculada, para os custos de mão de obra."},{"k":"par","r":"§ 1º","t":"A Administração não se vinculará às disposições contidas em acordos, convenções ou dissídios coletivos de trabalho que tratem de matéria não trabalhista, de pagamento de participação dos trabalhadores nos lucros ou resultados do contratado, ou que estabeleçam direitos não previstos em lei, como valores ou índices obrigatórios de encargos sociais ou previdenciários, bem como de preços para os insumos relacionados ao exercício da atividade."},{"k":"par","r":"§ 2º","t":"É vedado a órgão ou entidade contratante vincular-se às disposições previstas nos acordos, convenções ou dissídios coletivos de trabalho que tratem de obrigações e direitos que somente se aplicam aos contratos com a Administração Pública."},{"k":"par","r":"§ 3º","t":"A repactuação deverá observar o interregno mínimo de 1 (um) ano, contado da data da apresentação da proposta ou da data da última repactuação."},{"k":"par","r":"§ 4º","t":"A repactuação poderá ser dividida em tantas parcelas quantas forem necessárias, observado o princípio da anualidade do reajuste de preços da contratação, podendo ser realizada em momentos distintos para discutir a variação de custos que tenham sua anualidade resultante em datas diferenciadas, como os decorrentes de mão de obra e os decorrentes dos insumos necessários à execução dos serviços."},{"k":"par","r":"§ 5º","t":"Quando a contratação envolver mais de uma categoria profissional, a repactuação a que se refere o inciso II do caput deste artigo poderá ser dividida em tantos quantos forem os acordos, convenções ou dissídios coletivos de trabalho das categorias envolvidas na contratação."},{"k":"par","r":"§ 6º","t":"A repactuação será precedida de solicitação do contratado, acompanhada de demonstração analítica da variação dos custos, por meio de apresentação da planilha de custos e formação de preços, ou do novo acordo, convenção ou sentença normativa que fundamenta a repactuação."}]},{"k":"art","n":"136","id":"a136","p":[{"k":"cap","r":"","t":"Registros que não caracterizam alteração do contrato podem ser realizados por simples apostila, dispensada a celebração de termo aditivo, como nas seguintes situações:"},{"k":"inc","r":"I","t":"variação do valor contratual para fazer face ao reajuste ou à repactuação de preços previstos no próprio contrato;"},{"k":"inc","r":"II","t":"atualizações, compensações ou penalizações financeiras decorrentes das condições de pagamento previstas no contrato;"},{"k":"inc","r":"III","t":"alterações na razão ou na denominação social do contratado;"},{"k":"inc","r":"IV","t":"empenho de dotações orçamentárias."}]},{"k":"cap","t":"CAPÍTULO VIII","s":"DAS HIPÓTESES DE EXTINÇÃO DOS CONTRATOS"},{"k":"art","n":"137","id":"a137","p":[{"k":"cap","r":"","t":"Constituirão motivos para extinção do contrato, a qual deverá ser formalmente motivada nos autos do processo, assegurados o contraditório e a ampla defesa, as seguintes situações:"},{"k":"inc","r":"I","t":"não cumprimento ou cumprimento irregular de normas editalícias ou de cláusulas contratuais, de especificações, de projetos ou de prazos;"},{"k":"inc","r":"II","t":"desatendimento das determinações regulares emitidas pela autoridade designada para acompanhar e fiscalizar sua execução ou por autoridade superior;"},{"k":"inc","r":"III","t":"alteração social ou modificação da finalidade ou da estrutura da empresa que restrinja sua capacidade de concluir o contrato;"},{"k":"inc","r":"IV","t":"decretação de falência ou de insolvência civil, dissolução da sociedade ou falecimento do contratado;"},{"k":"inc","r":"V","t":"caso fortuito ou força maior, regularmente comprovados, impeditivos da execução do contrato;"},{"k":"inc","r":"VI","t":"atraso na obtenção da licença ambiental, ou impossibilidade de obtê-la, ou alteração substancial do anteprojeto que dela resultar, ainda que obtida no prazo previsto;"},{"k":"inc","r":"VII","t":"atraso na liberação das áreas sujeitas a desapropriação, a desocupação ou a servidão administrativa, ou impossibilidade de liberação dessas áreas;"},{"k":"inc","r":"VIII","t":"razões de interesse público, justificadas pela autoridade máxima do órgão ou da entidade contratante;"},{"k":"inc","r":"IX","t":"não cumprimento das obrigações relativas à reserva de cargos prevista em lei, bem como em outras normas específicas, para pessoa com deficiência, para reabilitado da Previdência Social ou para aprendiz."},{"k":"par","r":"§ 1º","t":"Regulamento poderá especificar procedimentos e critérios para verificação da ocorrência dos motivos previstos no caput deste artigo."},{"k":"par","r":"§ 2º","t":"O contratado terá direito à extinção do contrato nas seguintes hipóteses:"},{"k":"inc","r":"I","t":"supressão, por parte da Administração, de obras, serviços ou compras que acarrete modificação do valor inicial do contrato além do limite permitido no art. 125 desta Lei;"},{"k":"inc","r":"II","t":"suspensão de execução do contrato, por ordem escrita da Administração, por prazo superior a 3 (três) meses;"},{"k":"inc","r":"III","t":"repetidas suspensões que totalizem 90 (noventa) dias úteis, independentemente do pagamento obrigatório de indenização pelas sucessivas e contratualmente imprevistas desmobilizações e mobilizações e outras previstas;"},{"k":"inc","r":"IV","t":"atraso superior a 2 (dois) meses, contado da emissão da nota fiscal, dos pagamentos ou de parcelas de pagamentos devidos pela Administração por despesas de obras, serviços ou fornecimentos;"},{"k":"inc","r":"V","t":"não liberação pela Administração, nos prazos contratuais, de área, local ou objeto, para execução de obra, serviço ou fornecimento, e de fontes de materiais naturais especificadas no projeto, inclusive devido a atraso ou descumprimento das obrigações atribuídas pelo contrato à Administração relacionadas a desapropriação, a desocupação de áreas públicas ou a licenciamento ambiental."},{"k":"par","r":"§ 3º","t":"As hipóteses de extinção a que se referem os incisos II, III e IV do § 2º deste artigo observarão as seguintes disposições:"},{"k":"inc","r":"I","t":"não serão admitidas em caso de calamidade pública, de grave perturbação da ordem interna ou de guerra, bem como quando decorrerem de ato ou fato que o contratado tenha praticado, do qual tenha participado ou para o qual tenha contribuído;"},{"k":"inc","r":"II","t":"assegurarão ao contratado o direito de optar pela suspensão do cumprimento das obrigações assumidas até a normalização da situação, admitido o restabelecimento do equilíbrio econômico-financeiro do contrato, na forma da alínea “d” do inciso II do caput do art. 124 desta Lei."},{"k":"par","r":"§ 4º","t":"Os emitentes das garantias previstas no art. 96 desta Lei deverão ser notificados pelo contratante quanto ao início de processo administrativo para apuração de descumprimento de cláusulas contratuais."}]},{"k":"art","n":"138","id":"a138","p":[{"k":"cap","r":"","t":"A extinção do contrato poderá ser:"},{"k":"inc","r":"I","t":"determinada por ato unilateral e escrito da Administração, exceto no caso de descumprimento decorrente de sua própria conduta;"},{"k":"inc","r":"II","t":"consensual, por acordo entre as partes, por conciliação, por mediação ou por comitê de resolução de disputas, desde que haja interesse da Administração;"},{"k":"inc","r":"III","t":"determinada por decisão arbitral, em decorrência de cláusula compromissória ou compromisso arbitral, ou por decisão judicial."},{"k":"par","r":"§ 1º","t":"A extinção determinada por ato unilateral da Administração e a extinção consensual deverão ser precedidas de autorização escrita e fundamentada da autoridade competente e reduzidas a termo no respectivo processo."},{"k":"par","r":"§ 2º","t":"Quando a extinção decorrer de culpa exclusiva da Administração, o contratado será ressarcido pelos prejuízos regularmente comprovados que houver sofrido e terá direito a:"},{"k":"inc","r":"I","t":"devolução da garantia;"},{"k":"inc","r":"II","t":"pagamentos devidos pela execução do contrato até a data de extinção;"},{"k":"inc","r":"III","t":"pagamento do custo da desmobilização."}]},{"k":"art","n":"139","id":"a139","p":[{"k":"cap","r":"","t":"A extinção determinada por ato unilateral da Administração poderá acarretar, sem prejuízo das sanções previstas nesta Lei, as seguintes consequências:"},{"k":"inc","r":"I","t":"assunção imediata do objeto do contrato, no estado e local em que se encontrar, por ato próprio da Administração;"},{"k":"inc","r":"II","t":"ocupação e utilização do local, das instalações, dos equipamentos, do material e do pessoal empregados na execução do contrato e necessários à sua continuidade;"},{"k":"inc","r":"III","t":"execução da garantia contratual para:"},{"k":"ali","r":"a)","t":"ressarcimento da Administração Pública por prejuízos decorrentes da não execução;"},{"k":"ali","r":"b)","t":"pagamento de verbas trabalhistas, fundiárias e previdenciárias, quando cabível;"},{"k":"ali","r":"c)","t":"pagamento das multas devidas à Administração Pública;"},{"k":"ali","r":"d)","t":"exigência da assunção da execução e da conclusão do objeto do contrato pela seguradora, quando cabível;"},{"k":"inc","r":"IV","t":"retenção dos créditos decorrentes do contrato até o limite dos prejuízos causados à Administração Pública e das multas aplicadas."},{"k":"par","r":"§ 1º","t":"A aplicação das medidas previstas nos incisos I e II do caput deste artigo ficará a critério da Administração, que poderá dar continuidade à obra ou ao serviço por execução direta ou indireta."},{"k":"par","r":"§ 2º","t":"Na hipótese do inciso II do caput deste artigo, o ato deverá ser precedido de autorização expressa do ministro de Estado, do secretário estadual ou do secretário municipal competente, conforme o caso."}]},{"k":"cap","t":"CAPÍTULO IX","s":"DO RECEBIMENTO DO OBJETO DO CONTRATO"},{"k":"art","n":"140","id":"a140","p":[{"k":"cap","r":"","t":"O objeto do contrato será recebido:"},{"k":"inc","r":"I","t":"em se tratando de obras e serviços:"},{"k":"ali","r":"a)","t":"provisoriamente, pelo responsável por seu acompanhamento e fiscalização, mediante termo detalhado, quando verificado o cumprimento das exigências de caráter técnico;"},{"k":"ali","r":"b)","t":"definitivamente, por servidor ou comissão designada pela autoridade competente, mediante termo detalhado que comprove o atendimento das exigências contratuais;"},{"k":"inc","r":"II","t":"em se tratando de compras:"},{"k":"ali","r":"a)","t":"provisoriamente, de forma sumária, pelo responsável por seu acompanhamento e fiscalização, com verificação posterior da conformidade do material com as exigências contratuais;"},{"k":"ali","r":"b)","t":"definitivamente, por servidor ou comissão designada pela autoridade competente, mediante termo detalhado que comprove o atendimento das exigências contratuais."},{"k":"par","r":"§ 1º","t":"O objeto do contrato poderá ser rejeitado, no todo ou em parte, quando estiver em desacordo com o contrato."},{"k":"par","r":"§ 2º","t":"O recebimento provisório ou definitivo não excluirá a responsabilidade civil pela solidez e pela segurança da obra ou serviço nem a responsabilidade ético-profissional pela perfeita execução do contrato, nos limites estabelecidos pela lei ou pelo contrato."},{"k":"par","r":"§ 3º","t":"Os prazos e os métodos para a realização dos recebimentos provisório e definitivo serão definidos em regulamento ou no contrato."},{"k":"par","r":"§ 4º","t":"Salvo disposição em contrário constante do edital ou de ato normativo, os ensaios, os testes e as demais provas para aferição da boa execução do objeto do contrato exigidos por normas técnicas oficiais correrão por conta do contratado."},{"k":"par","r":"§ 5º","t":"Em se tratando de projeto de obra, o recebimento definitivo pela Administração não eximirá o projetista ou o consultor da responsabilidade objetiva por todos os danos causados por falha de projeto."},{"k":"par","r":"§ 6º","t":"Em se tratando de obra, o recebimento definitivo pela Administração não eximirá o contratado, pelo prazo mínimo de 5 (cinco) anos, admitida a previsão de prazo de garantia superior no edital e no contrato, da responsabilidade objetiva pela solidez e pela segurança dos materiais e dos serviços executados e pela funcionalidade da construção, da reforma, da recuperação ou da ampliação do bem imóvel, e, em caso de vício, defeito ou incorreção identificados, o contratado ficará responsável pela reparação, pela correção, pela reconstrução ou pela substituição necessárias."}]},{"k":"cap","t":"CAPÍTULO X","s":"DOS PAGAMENTOS"},{"k":"art","n":"141","id":"a141","p":[{"k":"cap","r":"","t":"No dever de pagamento pela Administração, será observada a ordem cronológica para cada fonte diferenciada de recursos, subdividida nas seguintes categorias de contratos:"},{"k":"inc","r":"I","t":"fornecimento de bens;"},{"k":"inc","r":"II","t":"locações;"},{"k":"inc","r":"III","t":"prestação de serviços;"},{"k":"inc","r":"IV","t":"realização de obras."},{"k":"par","r":"§ 1º","t":"A ordem cronológica referida no caput deste artigo poderá ser alterada, mediante prévia justificativa da autoridade competente e posterior comunicação ao órgão de controle interno da Administração e ao tribunal de contas competente, exclusivamente nas seguintes situações:"},{"k":"inc","r":"I","t":"grave perturbação da ordem, situação de emergência ou calamidade pública;"},{"k":"inc","r":"II","t":"pagamento a microempresa, empresa de pequeno porte, agricultor familiar, produtor rural pessoa física, microempreendedor individual e sociedade cooperativa, desde que demonstrado o risco de descontinuidade do cumprimento do objeto do contrato;"},{"k":"inc","r":"III","t":"pagamento de serviços necessários ao funcionamento dos sistemas estruturantes, desde que demonstrado o risco de descontinuidade do cumprimento do objeto do contrato;"},{"k":"inc","r":"IV","t":"pagamento de direitos oriundos de contratos em caso de falência, recuperação judicial ou dissolução da empresa contratada;"},{"k":"inc","r":"V","t":"pagamento de contrato cujo objeto seja imprescindível para assegurar a integridade do patrimônio público ou para manter o funcionamento das atividades finalísticas do órgão ou entidade, quando demonstrado o risco de descontinuidade da prestação de serviço público de relevância ou o cumprimento da missão institucional."},{"k":"par","r":"§ 2º","t":"A inobservância imotivada da ordem cronológica referida no caput deste artigo ensejará a apuração de responsabilidade do agente responsável, cabendo aos órgãos de controle a sua fiscalização."},{"k":"par","r":"§ 3º","t":"O órgão ou entidade deverá disponibilizar, mensalmente, em seção específica de acesso à informação em seu sítio na internet, a ordem cronológica de seus pagamentos, bem como as justificativas que fundamentarem a eventual alteração dessa ordem."}]},{"k":"art","n":"142","id":"a142","p":[{"k":"cap","r":"","t":"Disposição expressa no edital ou no contrato poderá prever pagamento em conta vinculada ou pagamento pela efetiva comprovação do fato gerador."},{"k":"par","r":"Parágrafo único","t":"","n":["(VETADO)"],"rev":1}]},{"k":"art","n":"143","id":"a143","p":[{"k":"cap","r":"","t":"No caso de controvérsia sobre a execução do objeto, quanto a dimensão, qualidade e quantidade, a parcela incontroversa deverá ser liberada no prazo previsto para pagamento."}]},{"k":"art","n":"144","id":"a144","p":[{"k":"cap","r":"","t":"Na contratação de obras, fornecimentos e serviços, inclusive de engenharia, poderá ser estabelecida remuneração variável vinculada ao desempenho do contratado, com base em metas, padrões de qualidade, critérios de sustentabilidade ambiental e prazos de entrega definidos no edital de licitação e no contrato."},{"k":"par","r":"§ 1º","t":"O pagamento poderá ser ajustado em base percentual sobre o valor economizado em determinada despesa, quando o objeto do contrato visar à implantação de processo de racionalização, hipótese em que as despesas correrão à conta dos mesmos créditos orçamentários, na forma de regulamentação específica."},{"k":"par","r":"§ 2º","t":"A utilização de remuneração variável será motivada e respeitará o limite orçamentário fixado pela Administração para a contratação."}]},{"k":"art","n":"145","id":"a145","p":[{"k":"cap","r":"","t":"Não será permitido pagamento antecipado, parcial ou total, relativo a parcelas contratuais vinculadas ao fornecimento de bens, à execução de obras ou à prestação de serviços."},{"k":"par","r":"§ 1º","t":"A antecipação de pagamento somente será permitida se propiciar sensível economia de recursos ou se representar condição indispensável para a obtenção do bem ou para a prestação do serviço, hipótese que deverá ser previamente justificada no processo licitatório e expressamente prevista no edital de licitação ou instrumento formal de contratação direta."},{"k":"par","r":"§ 2º","t":"A Administração poderá exigir a prestação de garantia adicional como condição para o pagamento antecipado."},{"k":"par","r":"§ 3º","t":"Caso o objeto não seja executado no prazo contratual, o valor antecipado deverá ser devolvido."}]},{"k":"art","n":"146","id":"a146","p":[{"k":"cap","r":"","t":"No ato de liquidação da despesa, os serviços de contabilidade comunicarão aos órgãos da administração tributária as características da despesa e os valores pagos, conforme o disposto no art. 63 da Lei nº 4.320, de 17 de março de 1964."}]},{"k":"cap","t":"CAPÍTULO XI","s":"DA NULIDADE DOS CONTRATOS"},{"k":"art","n":"147","id":"a147","p":[{"k":"cap","r":"","t":"Constatada irregularidade no procedimento licitatório ou na execução contratual, caso não seja possível o saneamento, a decisão sobre a suspensão da execução ou sobre a declaração de nulidade do contrato somente será adotada na hipótese em que se revelar medida de interesse público, com avaliação, entre outros, dos seguintes aspectos:"},{"k":"inc","r":"I","t":"impactos econômicos e financeiros decorrentes do atraso na fruição dos benefícios do objeto do contrato;"},{"k":"inc","r":"II","t":"riscos sociais, ambientais e à segurança da população local decorrentes do atraso na fruição dos benefícios do objeto do contrato;"},{"k":"inc","r":"III","t":"motivação social e ambiental do contrato;"},{"k":"inc","r":"IV","t":"custo da deterioração ou da perda das parcelas executadas;"},{"k":"inc","r":"V","t":"despesa necessária à preservação das instalações e dos serviços já executados;"},{"k":"inc","r":"VI","t":"despesa inerente à desmobilização e ao posterior retorno às atividades;"},{"k":"inc","r":"VII","t":"medidas efetivamente adotadas pelo titular do órgão ou entidade para o saneamento dos indícios de irregularidades apontados;"},{"k":"inc","r":"VIII","t":"custo total e estágio de execução física e financeira dos contratos, dos convênios, das obras ou das parcelas envolvidas;"},{"k":"inc","r":"IX","t":"fechamento de postos de trabalho diretos e indiretos em razão da paralisação;"},{"k":"inc","r":"X","t":"custo para realização de nova licitação ou celebração de novo contrato;"},{"k":"inc","r":"XI","t":"custo de oportunidade do capital durante o período de paralisação."},{"k":"par","r":"Parágrafo único","t":"Caso a paralisação ou anulação não se revele medida de interesse público, o poder público deverá optar pela continuidade do contrato e pela solução da irregularidade por meio de indenização por perdas e danos, sem prejuízo da apuração de responsabilidade e da aplicação de penalidades cabíveis."}]},{"k":"art","n":"148","id":"a148","p":[{"k":"cap","r":"","t":"A declaração de nulidade do contrato administrativo requererá análise prévia do interesse público envolvido, na forma do art. 147 desta Lei, e operará retroativamente, impedindo os efeitos jurídicos que o contrato deveria produzir ordinariamente e desconstituindo os já produzidos."},{"k":"par","r":"§ 1º","t":"Caso não seja possível o retorno à situação fática anterior, a nulidade será resolvida pela indenização por perdas e danos, sem prejuízo da apuração de responsabilidade e aplicação das penalidades cabíveis."},{"k":"par","r":"§ 2º","t":"Ao declarar a nulidade do contrato, a autoridade, com vistas à continuidade da atividade administrativa, poderá decidir que ela só tenha eficácia em momento futuro, suficiente para efetuar nova contratação, por prazo de até 6 (seis) meses, prorrogável uma única vez."}]},{"k":"art","n":"149","id":"a149","p":[{"k":"cap","r":"","t":"A nulidade não exonerará a Administração do dever de indenizar o contratado pelo que houver executado até a data em que for declarada ou tornada eficaz, bem como por outros prejuízos regularmente comprovados, desde que não lhe seja imputável, e será promovida a responsabilização de quem lhe tenha dado causa."}]},{"k":"art","n":"150","id":"a150","p":[{"k":"cap","r":"","t":"Nenhuma contratação será feita sem a caracterização adequada de seu objeto e sem a indicação dos créditos orçamentários para pagamento das parcelas contratuais vincendas no exercício em que for realizada a contratação, sob pena de nulidade do ato e de responsabilização de quem lhe tiver dado causa."}]},{"k":"cap","t":"CAPÍTULO XII","s":"DOS MEIOS ALTERNATIVOS DE RESOLUÇÃO DE CONTROVÉRSIAS"},{"k":"art","n":"151","id":"a151","p":[{"k":"cap","r":"","t":"Nas contratações regidas por esta Lei, poderão ser utilizados meios alternativos de prevenção e resolução de controvérsias, notadamente a conciliação, a mediação, o comitê de resolução de disputas e a arbitragem."},{"k":"par","r":"Parágrafo único","t":"Será aplicado o disposto no caput deste artigo às controvérsias relacionadas a direitos patrimoniais disponíveis, como as questões relacionadas ao restabelecimento do equilíbrio econômico-financeiro do contrato, ao inadimplemento de obrigações contratuais por quaisquer das partes e ao cálculo de indenizações."}]},{"k":"art","n":"152","id":"a152","p":[{"k":"cap","r":"","t":"A arbitragem será sempre de direito e observará o princípio da publicidade."}]},{"k":"art","n":"153","id":"a153","p":[{"k":"cap","r":"","t":"Os contratos poderão ser aditados para permitir a adoção dos meios alternativos de resolução de controvérsias."}]},{"k":"art","n":"154","id":"a154","p":[{"k":"cap","r":"","t":"O processo de escolha dos árbitros, dos colegiados arbitrais e dos comitês de resolução de disputas observará critérios isonômicos, técnicos e transparentes."}]},{"k":"cap","t":"TÍTULO IV","s":"DAS IRREGULARIDADES"},{"k":"cap","t":"CAPÍTULO I","s":"DAS INFRAÇÕES E SANÇÕES ADMINISTRATIVAS"},{"k":"art","n":"155","id":"a155","p":[{"k":"cap","r":"","t":"O licitante ou o contratado será responsabilizado administrativamente pelas seguintes infrações:"},{"k":"inc","r":"I","t":"dar causa à inexecução parcial do contrato;"},{"k":"inc","r":"II","t":"dar causa à inexecução parcial do contrato que cause grave dano à Administração, ao funcionamento dos serviços públicos ou ao interesse coletivo;"},{"k":"inc","r":"III","t":"dar causa à inexecução total do contrato;"},{"k":"inc","r":"IV","t":"deixar de entregar a documentação exigida para o certame;"},{"k":"inc","r":"V","t":"não manter a proposta, salvo em decorrência de fato superveniente devidamente justificado;"},{"k":"inc","r":"VI","t":"não celebrar o contrato ou não entregar a documentação exigida para a contratação, quando convocado dentro do prazo de validade de sua proposta;"},{"k":"inc","r":"VII","t":"ensejar o retardamento da execução ou da entrega do objeto da licitação sem motivo justificado;"},{"k":"inc","r":"VIII","t":"apresentar declaração ou documentação falsa exigida para o certame ou prestar declaração falsa durante a licitação ou a execução do contrato;"},{"k":"inc","r":"IX","t":"fraudar a licitação ou praticar ato fraudulento na execução do contrato;"},{"k":"inc","r":"X","t":"comportar-se de modo inidôneo ou cometer fraude de qualquer natureza;"},{"k":"inc","r":"XI","t":"praticar atos ilícitos com vistas a frustrar os objetivos da licitação;"},{"k":"inc","r":"XII","t":"praticar ato lesivo previsto no art. 5º da Lei nº 12.846, de 1º de agosto de 2013."}]},{"k":"art","n":"156","id":"a156","p":[{"k":"cap","r":"","t":"Serão aplicadas ao responsável pelas infrações administrativas previstas nesta Lei as seguintes sanções:"},{"k":"inc","r":"I","t":"advertência;"},{"k":"inc","r":"II","t":"multa;"},{"k":"inc","r":"III","t":"impedimento de licitar e contratar;"},{"k":"inc","r":"IV","t":"declaração de inidoneidade para licitar ou contratar."},{"k":"par","r":"§ 1º","t":"Na aplicação das sanções serão considerados:"},{"k":"inc","r":"I","t":"a natureza e a gravidade da infração cometida;"},{"k":"inc","r":"II","t":"as peculiaridades do caso concreto;"},{"k":"inc","r":"III","t":"as circunstâncias agravantes ou atenuantes;"},{"k":"inc","r":"IV","t":"os danos que dela provierem para a Administração Pública;"},{"k":"inc","r":"V","t":"a implantação ou o aperfeiçoamento de programa de integridade, conforme normas e orientações dos órgãos de controle."},{"k":"par","r":"§ 2º","t":"A sanção prevista no inciso I do caput deste artigo será aplicada exclusivamente pela infração administrativa prevista no inciso I do caput do art. 155 desta Lei, quando não se justificar a imposição de penalidade mais grave."},{"k":"par","r":"§ 3º","t":"A sanção prevista no inciso II do caput deste artigo, calculada na forma do edital ou do contrato, não poderá ser inferior a 0,5% (cinco décimos por cento) nem superior a 30% (trinta por cento) do valor do contrato licitado ou celebrado com contratação direta e será aplicada ao responsável por qualquer das infrações administrativas previstas no art. 155 desta Lei."},{"k":"par","r":"§ 4º","t":"A sanção prevista no inciso III do caput deste artigo será aplicada ao responsável pelas infrações administrativas previstas nos incisos II, III, IV, V, VI e VII do caput do art. 155 desta Lei, quando não se justificar a imposição de penalidade mais grave, e impedirá o responsável de licitar ou contratar no âmbito da Administração Pública direta e indireta do ente federativo que tiver aplicado a sanção, pelo prazo máximo de 3 (três) anos."},{"k":"par","r":"§ 5º","t":"A sanção prevista no inciso IV do caput deste artigo será aplicada ao responsável pelas infrações administrativas previstas nos incisos VIII, IX, X, XI e XII do caput do art. 155 desta Lei, bem como pelas infrações administrativas previstas nos incisos II, III, IV, V, VI e VII do caput do referido artigo que justifiquem a imposição de penalidade mais grave que a sanção referida no § 4º deste artigo, e impedirá o responsável de licitar ou contratar no âmbito da Administração Pública direta e indireta de todos os entes federativos, pelo prazo mínimo de 3 (três) anos e máximo de 6 (seis) anos."},{"k":"par","r":"§ 6º","t":"A sanção estabelecida no inciso IV do caput deste artigo será precedida de análise jurídica e observará as seguintes regras:"},{"k":"inc","r":"I","t":"quando aplicada por órgão do Poder Executivo, será de competência exclusiva de ministro de Estado, de secretário estadual ou de secretário municipal e, quando aplicada por autarquia ou fundação, será de competência exclusiva da autoridade máxima da entidade;"},{"k":"inc","r":"II","t":"quando aplicada por órgãos dos Poderes Legislativo e Judiciário, pelo Ministério Público e pela Defensoria Pública no desempenho da função administrativa, será de competência exclusiva de autoridade de nível hierárquico equivalente às autoridades referidas no inciso I deste parágrafo, na forma de regulamento."},{"k":"par","r":"§ 7º","t":"As sanções previstas nos incisos I, III e IV do caput deste artigo poderão ser aplicadas cumulativamente com a prevista no inciso II do caput deste artigo."},{"k":"par","r":"§ 8º","t":"Se a multa aplicada e as indenizações cabíveis forem superiores ao valor de pagamento eventualmente devido pela Administração ao contratado, além da perda desse valor, a diferença será descontada da garantia prestada ou será cobrada judicialmente."},{"k":"par","r":"§ 9º","t":"A aplicação das sanções previstas no caput deste artigo não exclui, em hipótese alguma, a obrigação de reparação integral do dano causado à Administração Pública."}]},{"k":"art","n":"157","id":"a157","p":[{"k":"cap","r":"","t":"Na aplicação da sanção prevista no inciso II do caput do art. 156 desta Lei, será facultada a defesa do interessado no prazo de 15 (quinze) dias úteis, contado da data de sua intimação."}]},{"k":"art","n":"158","id":"a158","p":[{"k":"cap","r":"","t":"A aplicação das sanções previstas nos incisos III e IV do caput do art. 156 desta Lei requererá a instauração de processo de responsabilização, a ser conduzido por comissão composta de 2 (dois) ou mais servidores estáveis, que avaliará fatos e circunstâncias conhecidos e intimará o licitante ou o contratado para, no prazo de 15 (quinze) dias úteis, contado da data de intimação, apresentar defesa escrita e especificar as provas que pretenda produzir."},{"k":"par","r":"§ 1º","t":"Em órgão ou entidade da Administração Pública cujo quadro funcional não seja formado de servidores estatutários, a comissão a que se refere o caput deste artigo será composta de 2 (dois) ou mais empregados públicos pertencentes aos seus quadros permanentes, preferencialmente com, no mínimo, 3 (três) anos de tempo de serviço no órgão ou entidade."},{"k":"par","r":"§ 2º","t":"Na hipótese de deferimento de pedido de produção de novas provas ou de juntada de provas julgadas indispensáveis pela comissão, o licitante ou o contratado poderá apresentar alegações finais no prazo de 15 (quinze) dias úteis, contado da data da intimação."},{"k":"par","r":"§ 3º","t":"Serão indeferidas pela comissão, mediante decisão fundamentada, provas ilícitas, impertinentes, desnecessárias, protelatórias ou intempestivas."},{"k":"par","r":"§ 4º","t":"A prescrição ocorrerá em 5 (cinco) anos, contados da ciência da infração pela Administração, e será:"},{"k":"inc","r":"I","t":"interrompida pela instauração do processo de responsabilização a que se refere o caput deste artigo;"},{"k":"inc","r":"II","t":"suspensa pela celebração de acordo de leniência previsto na Lei nº 12.846, de 1º de agosto de 2013;"},{"k":"inc","r":"III","t":"suspensa por decisão judicial que inviabilize a conclusão da apuração administrativa."}]},{"k":"art","n":"159","id":"a159","p":[{"k":"cap","r":"","t":"Os atos previstos como infrações administrativas nesta Lei ou em outras leis de licitações e contratos da Administração Pública que também sejam tipificados como atos lesivos na Lei nº 12.846, de 1º de agosto de 2013, serão apurados e julgados conjuntamente, nos mesmos autos, observados o rito procedimental e a autoridade competente definidos na referida Lei."},{"k":"par","r":"Parágrafo único","t":"","n":["(VETADO)"],"rev":1}]},{"k":"art","n":"160","id":"a160","p":[{"k":"cap","r":"","t":"A personalidade jurídica poderá ser desconsiderada sempre que utilizada com abuso do direito para facilitar, encobrir ou dissimular a prática dos atos ilícitos previstos nesta Lei ou para provocar confusão patrimonial, e, nesse caso, todos os efeitos das sanções aplicadas à pessoa jurídica serão estendidos aos seus administradores e sócios com poderes de administração, a pessoa jurídica sucessora ou a empresa do mesmo ramo com relação de coligação ou controle, de fato ou de direito, com o sancionado, observados, em todos os casos, o contraditório, a ampla defesa e a obrigatoriedade de análise jurídica prévia."}]},{"k":"art","n":"161","id":"a161","p":[{"k":"cap","r":"","t":"Os órgãos e entidades dos Poderes Executivo, Legislativo e Judiciário de todos os entes federativos deverão, no prazo máximo 15 (quinze) dias úteis, contado da data de aplicação da sanção, informar e manter atualizados os dados relativos às sanções por eles aplicadas, para fins de publicidade no Cadastro Nacional de Empresas Inidôneas e Suspensas (Ceis) e no Cadastro Nacional de Empresas Punidas (Cnep), instituídos no âmbito do Poder Executivo federal."},{"k":"par","r":"Parágrafo único","t":"Para fins de aplicação das sanções previstas nos incisos I, II, III e IV do caput do art. 156 desta Lei, o Poder Executivo regulamentará a forma de cômputo e as consequências da soma de diversas sanções aplicadas a uma mesma empresa e derivadas de contratos distintos."}]},{"k":"art","n":"162","id":"a162","p":[{"k":"cap","r":"","t":"O atraso injustificado na execução do contrato sujeitará o contratado a multa de mora, na forma prevista em edital ou em contrato."},{"k":"par","r":"Parágrafo único","t":"A aplicação de multa de mora não impedirá que a Administração a converta em compensatória e promova a extinção unilateral do contrato com a aplicação cumulada de outras sanções previstas nesta Lei."}]},{"k":"art","n":"163","id":"a163","p":[{"k":"cap","r":"","t":"É admitida a reabilitação do licitante ou contratado perante a própria autoridade que aplicou a penalidade, exigidos, cumulativamente:"},{"k":"inc","r":"I","t":"reparação integral do dano causado à Administração Pública;"},{"k":"inc","r":"II","t":"pagamento da multa;"},{"k":"inc","r":"III","t":"transcurso do prazo mínimo de 1 (um) ano da aplicação da penalidade, no caso de impedimento de licitar e contratar, ou de 3 (três) anos da aplicação da penalidade, no caso de declaração de inidoneidade;"},{"k":"inc","r":"IV","t":"cumprimento das condições de reabilitação definidas no ato punitivo;"},{"k":"inc","r":"V","t":"análise jurídica prévia, com posicionamento conclusivo quanto ao cumprimento dos requisitos definidos neste artigo."},{"k":"par","r":"Parágrafo único","t":"A sanção pelas infrações previstas nos incisos VIII e XII do caput do art. 155 desta Lei exigirá, como condição de reabilitação do licitante ou contratado, a implantação ou aperfeiçoamento de programa de integridade pelo responsável.","n":["(Regulamento)"]}]},{"k":"cap","t":"CAPÍTULO II","s":"DAS IMPUGNAÇÕES, DOS PEDIDOS DE ESCLARECIMENTO E DOS RECURSOS"},{"k":"art","n":"164","id":"a164","p":[{"k":"cap","r":"","t":"Qualquer pessoa é parte legítima para impugnar edital de licitação por irregularidade na aplicação desta Lei ou para solicitar esclarecimento sobre os seus termos, devendo protocolar o pedido até 3 (três) dias úteis antes da data de abertura do certame."},{"k":"par","r":"Parágrafo único","t":"A resposta à impugnação ou ao pedido de esclarecimento será divulgada em sítio eletrônico oficial no prazo de até 3 (três) dias úteis, limitado ao último dia útil anterior à data da abertura do certame."}]},{"k":"art","n":"165","id":"a165","p":[{"k":"cap","r":"","t":"Dos atos da Administração decorrentes da aplicação desta Lei cabem:"},{"k":"inc","r":"I","t":"recurso, no prazo de 3 (três) dias úteis, contado da data de intimação ou de lavratura da ata, em face de:"},{"k":"ali","r":"a)","t":"ato que defira ou indefira pedido de pré-qualificação de interessado ou de inscrição em registro cadastral, sua alteração ou cancelamento;"},{"k":"ali","r":"b)","t":"julgamento das propostas;"},{"k":"ali","r":"c)","t":"ato de habilitação ou inabilitação de licitante;"},{"k":"ali","r":"d)","t":"anulação ou revogação da licitação;"},{"k":"ali","r":"e)","t":"extinção do contrato, quando determinada por ato unilateral e escrito da Administração;"},{"k":"inc","r":"II","t":"pedido de reconsideração, no prazo de 3 (três) dias úteis, contado da data de intimação, relativamente a ato do qual não caiba recurso hierárquico."},{"k":"par","r":"§ 1º","t":"Quanto ao recurso apresentado em virtude do disposto nas alíneas “b” e “c” do inciso I do caput deste artigo, serão observadas as seguintes disposições:"},{"k":"inc","r":"I","t":"a intenção de recorrer deverá ser manifestada imediatamente, sob pena de preclusão, e o prazo para apresentação das razões recursais previsto no inciso I do caput deste artigo será iniciado na data de intimação ou de lavratura da ata de habilitação ou inabilitação ou, na hipótese de adoção da inversão de fases prevista no § 1º do art. 17 desta Lei, da ata de julgamento;"},{"k":"inc","r":"II","t":"a apreciação dar-se-á em fase única."},{"k":"par","r":"§ 2º","t":"O recurso de que trata o inciso I do caput deste artigo será dirigido à autoridade que tiver editado o ato ou proferido a decisão recorrida, que, se não reconsiderar o ato ou a decisão no prazo de 3 (três) dias úteis, encaminhará o recurso com a sua motivação à autoridade superior, a qual deverá proferir sua decisão no prazo máximo de 10 (dez) dias úteis, contado do recebimento dos autos."},{"k":"par","r":"§ 3º","t":"O acolhimento do recurso implicará invalidação apenas de ato insuscetível de aproveitamento."},{"k":"par","r":"§ 4º","t":"O prazo para apresentação de contrarrazões será o mesmo do recurso e terá início na data de intimação pessoal ou de divulgação da interposição do recurso."},{"k":"par","r":"§ 5º","t":"Será assegurado ao licitante vista dos elementos indispensáveis à defesa de seus interesses."}]},{"k":"art","n":"166","id":"a166","p":[{"k":"cap","r":"","t":"Da aplicação das sanções previstas nos incisos I, II e III do caput do art. 156 desta Lei caberá recurso no prazo de 15 (quinze) dias úteis, contado da data da intimação."},{"k":"par","r":"Parágrafo único","t":"O recurso de que trata o caput deste artigo será dirigido à autoridade que tiver proferido a decisão recorrida, que, se não a reconsiderar no prazo de 5 (cinco) dias úteis, encaminhará o recurso com sua motivação à autoridade superior, a qual deverá proferir sua decisão no prazo máximo de 20 (vinte) dias úteis, contado do recebimento dos autos."}]},{"k":"art","n":"167","id":"a167","p":[{"k":"cap","r":"","t":"Da aplicação da sanção prevista no inciso IV do caput do art. 156 desta Lei caberá apenas pedido de reconsideração, que deverá ser apresentado no prazo de 15 (quinze) dias úteis, contado da data da intimação, e decidido no prazo máximo de 20 (vinte) dias úteis, contado do seu recebimento."}]},{"k":"art","n":"168","id":"a168","p":[{"k":"cap","r":"","t":"O recurso e o pedido de reconsideração terão efeito suspensivo do ato ou da decisão recorrida até que sobrevenha decisão final da autoridade competente."},{"k":"par","r":"Parágrafo único","t":"Na elaboração de suas decisões, a autoridade competente será auxiliada pelo órgão de assessoramento jurídico, que deverá dirimir dúvidas e subsidiá-la com as informações necessárias."}]},{"k":"cap","t":"CAPÍTULO III","s":"DO CONTROLE DAS CONTRATAÇÕES"},{"k":"art","n":"169","id":"a169","p":[{"k":"cap","r":"","t":"As contratações públicas deverão submeter-se a práticas contínuas e permanentes de gestão de riscos e de controle preventivo, inclusive mediante adoção de recursos de tecnologia da informação, e, além de estar subordinadas ao controle social, sujeitar-se-ão às seguintes linhas de defesa:"},{"k":"inc","r":"I","t":"primeira linha de defesa, integrada por servidores e empregados públicos, agentes de licitação e autoridades que atuam na estrutura de governança do órgão ou entidade;"},{"k":"inc","r":"II","t":"segunda linha de defesa, integrada pelas unidades de assessoramento jurídico e de controle interno do próprio órgão ou entidade;"},{"k":"inc","r":"III","t":"terceira linha de defesa, integrada pelo órgão central de controle interno da Administração e pelo tribunal de contas."},{"k":"par","r":"§ 1º","t":"Na forma de regulamento, a implementação das práticas a que se refere o caput deste artigo será de responsabilidade da alta administração do órgão ou entidade e levará em consideração os custos e os benefícios decorrentes de sua implementação, optando-se pelas medidas que promovam relações íntegras e confiáveis, com segurança jurídica para todos os envolvidos, e que produzam o resultado mais vantajoso para a Administração, com eficiência, eficácia e efetividade nas contratações públicas."},{"k":"par","r":"§ 2º","t":"Para a realização de suas atividades, os órgãos de controle deverão ter acesso irrestrito aos documentos e às informações necessárias à realização dos trabalhos, inclusive aos documentos classificados pelo órgão ou entidade nos termos da Lei nº 12.527, de 18 de novembro de 2011, e o órgão de controle com o qual foi compartilhada eventual informação sigilosa tornar-se-á corresponsável pela manutenção do seu sigilo."},{"k":"par","r":"§ 3º","t":"Os integrantes das linhas de defesa a que se referem os incisos I, II e III do caput deste artigo observarão o seguinte:"},{"k":"inc","r":"I","t":"quando constatarem simples impropriedade formal, adotarão medidas para o seu saneamento e para a mitigação de riscos de sua nova ocorrência, preferencialmente com o aperfeiçoamento dos controles preventivos e com a capacitação dos agentes públicos responsáveis;"},{"k":"inc","r":"II","t":"quando constatarem irregularidade que configure dano à Administração, sem prejuízo das medidas previstas no inciso I deste § 3º, adotarão as providências necessárias para a apuração das infrações administrativas, observadas a segregação de funções e a necessidade de individualização das condutas, bem como remeterão ao Ministério Público competente cópias dos documentos cabíveis para a apuração dos ilícitos de sua competência."}]},{"k":"art","n":"170","id":"a170","p":[{"k":"cap","r":"","t":"Os órgãos de controle adotarão, na fiscalização dos atos previstos nesta Lei, critérios de oportunidade, materialidade, relevância e risco e considerarão as razões apresentadas pelos órgãos e entidades responsáveis e os resultados obtidos com a contratação, observado o disposto no § 3º do art. 169 desta Lei."},{"k":"par","r":"§ 1º","t":"As razões apresentadas pelos órgãos e entidades responsáveis deverão ser encaminhadas aos órgãos de controle até a conclusão da fase de instrução do processo e não poderão ser desentranhadas dos autos."},{"k":"par","r":"§ 2º","t":"A omissão na prestação das informações não impedirá as deliberações dos órgãos de controle nem retardará a aplicação de qualquer de seus prazos de tramitação e de deliberação."},{"k":"par","r":"§ 3º","t":"Os órgãos de controle desconsiderarão os documentos impertinentes, meramente protelatórios ou de nenhum interesse para o esclarecimento dos fatos."},{"k":"par","r":"§ 4º","t":"Qualquer licitante, contratado ou pessoa física ou jurídica poderá representar aos órgãos de controle interno ou ao tribunal de contas competente contra irregularidades na aplicação desta Lei."}]},{"k":"art","n":"171","id":"a171","p":[{"k":"cap","r":"","t":"Na fiscalização de controle será observado o seguinte:"},{"k":"inc","r":"I","t":"viabilização de oportunidade de manifestação aos gestores sobre possíveis propostas de encaminhamento que terão impacto significativo nas rotinas de trabalho dos órgãos e entidades fiscalizados, a fim de que eles disponibilizem subsídios para avaliação prévia da relação entre custo e benefício dessas possíveis proposições;"},{"k":"inc","r":"II","t":"adoção de procedimentos objetivos e imparciais e elaboração de relatórios tecnicamente fundamentados, baseados exclusivamente nas evidências obtidas e organizados de acordo com as normas de auditoria do respectivo órgão de controle, de modo a evitar que interesses pessoais e interpretações tendenciosas interfiram na apresentação e no tratamento dos fatos levantados;"},{"k":"inc","r":"III","t":"definição de objetivos, nos regimes de empreitada por preço global, empreitada integral, contratação semi- integrada e contratação integrada, atendidos os requisitos técnicos, legais, orçamentários e financeiros, de acordo com as finalidades da contratação, devendo, ainda, ser perquirida a conformidade do preço global com os parâmetros de mercado para o objeto contratado, considerada inclusive a dimensão geográfica."},{"k":"par","r":"§ 1º","t":"Ao suspender cautelarmente o processo licitatório, o tribunal de contas deverá pronunciar-se definitivamente sobre o mérito da irregularidade que tenha dado causa à suspensão no prazo de 25 (vinte e cinco) dias úteis, contado da data do recebimento das informações a que se refere o § 2º deste artigo, prorrogável por igual período uma única vez, e definirá objetivamente:"},{"k":"inc","r":"I","t":"as causas da ordem de suspensão;"},{"k":"inc","r":"II","t":"o modo como será garantido o atendimento do interesse público obstado pela suspensão da licitação, no caso de objetos essenciais ou de contratação por emergência."},{"k":"par","r":"§ 2º","t":"Ao ser intimado da ordem de suspensão do processo licitatório, o órgão ou entidade deverá, no prazo de 10 (dez) dias úteis, admitida a prorrogação:"},{"k":"inc","r":"I","t":"informar as medidas adotadas para cumprimento da decisão;"},{"k":"inc","r":"II","t":"prestar todas as informações cabíveis;"},{"k":"inc","r":"III","t":"proceder à apuração de responsabilidade, se for o caso."},{"k":"par","r":"§ 3º","t":"A decisão que examinar o mérito da medida cautelar a que se refere o § 1º deste artigo deverá definir as medidas necessárias e adequadas, em face das alternativas possíveis, para o saneamento do processo licitatório, ou determinar a sua anulação."},{"k":"par","r":"§ 4º","t":"O descumprimento do disposto no § 2º deste artigo ensejará a apuração de responsabilidade e a obrigação de reparação do prejuízo causado ao erário."}]},{"k":"art","n":"172","id":"a172","p":[{"k":"cap","r":"","t":"","n":["(VETADO)"],"rev":1}]},{"k":"art","n":"173","id":"a173","p":[{"k":"cap","r":"","t":"Os tribunais de contas deverão, por meio de suas escolas de contas, promover eventos de capacitação para os servidores efetivos e empregados públicos designados para o desempenho das funções essenciais à execução desta Lei, incluídos cursos presenciais e a distância, redes de aprendizagem, seminários e congressos sobre contratações públicas."}]},{"k":"cap","t":"TÍTULO V","s":"DISPOSIÇÕES GERAIS"},{"k":"cap","t":"CAPÍTULO I","s":"DO PORTAL NACIONAL DE CONTRATAÇÕES PÚBLICAS (PNCP)"},{"k":"art","n":"174","id":"a174","p":[{"k":"cap","r":"","t":"É criado o Portal Nacional de Contratações Públicas (PNCP), sítio eletrônico oficial destinado à:"},{"k":"inc","r":"I","t":"divulgação centralizada e obrigatória dos atos exigidos por esta Lei;"},{"k":"inc","r":"II","t":"realização facultativa das contratações pelos órgãos e entidades dos Poderes Executivo, Legislativo e Judiciário de todos os entes federativos."},{"k":"par","r":"§ 1º","t":"O PNCP será gerido pelo Comitê Gestor da Rede Nacional de Contratações Públicas, a ser presidido por representante indicado pelo Presidente da República e composto de:"},{"k":"inc","r":"I","t":"3 (três) representantes da União indicados pelo Presidente da República;"},{"k":"inc","r":"II","t":"2 (dois) representantes dos Estados e do Distrito Federal indicados pelo Conselho Nacional de Secretários de Estado da Administração;"},{"k":"inc","r":"III","t":"2 (dois) representantes dos Municípios indicados pela Confederação Nacional de Municípios."},{"k":"par","r":"§ 2º","t":"O PNCP conterá, entre outras, as seguintes informações acerca das contratações:"},{"k":"inc","r":"I","t":"planos de contratação anuais;"},{"k":"inc","r":"II","t":"catálogos eletrônicos de padronização;"},{"k":"inc","r":"III","t":"editais de credenciamento e de pré-qualificação, avisos de contratação direta e editais de licitação e respectivos anexos;"},{"k":"inc","r":"IV","t":"atas de registro de preços;"},{"k":"inc","r":"V","t":"contratos e termos aditivos;"},{"k":"inc","r":"VI","t":"notas fiscais eletrônicas, quando for o caso."},{"k":"par","r":"§ 3º","t":"O PNCP deverá, entre outras funcionalidades, oferecer:"},{"k":"inc","r":"I","t":"sistema de registro cadastral unificado;"},{"k":"inc","r":"II","t":"painel para consulta de preços, banco de preços em saúde e acesso à base nacional de notas fiscais eletrônicas;"},{"k":"inc","r":"III","t":"sistema de planejamento e gerenciamento de contratações, incluído o cadastro de atesto de cumprimento de obrigações previsto no § 4º do art. 88 desta Lei;"},{"k":"inc","r":"IV","t":"sistema eletrônico para a realização de sessões públicas;"},{"k":"inc","r":"V","t":"acesso ao Cadastro Nacional de Empresas Inidôneas e Suspensas (Ceis) e ao Cadastro Nacional de Empresas Punidas (Cnep);"},{"k":"inc","r":"VI","t":"sistema de gestão compartilhada com a sociedade de informações referentes à execução do contrato, que possibilite:"},{"k":"ali","r":"a)","t":"envio, registro, armazenamento e divulgação de mensagens de texto ou imagens pelo interessado previamente identificado;"},{"k":"ali","r":"b)","t":"acesso ao sistema informatizado de acompanhamento de obras a que se refere o inciso III do caput do art. 19 desta Lei;"},{"k":"ali","r":"c)","t":"comunicação entre a população e representantes da Administração e do contratado designados para prestar as informações e esclarecimentos pertinentes, na forma de regulamento;"},{"k":"ali","r":"d)","t":"divulgação, na forma de regulamento, de relatório final com informações sobre a consecução dos objetivos que tenham justificado a contratação e eventuais condutas a serem adotadas para o aprimoramento das atividades da Administração."},{"k":"inc","r":"VII","t":"o Sicx.","n":["(Incluído pela Lei nº 15.266, de 2025)"]},{"k":"par","r":"§ 3º-A","t":"As funcionalidades a que se refere o § 3º deste artigo serão os sistemas adotados e oferecidos pelo Poder Executivo federal.","n":["(Incluído pela Lei nº 15.266, de 2025)"]},{"k":"par","r":"§ 4º","t":"O PNCP adotará o formato de dados abertos e observará as exigências previstas na Lei nº 12.527, de 18 de novembro de 2011."},{"k":"par","r":"§ 5º","t":"","n":["(VETADO)"],"rev":1}]},{"k":"art","n":"175","id":"a175","p":[{"k":"cap","r":"","t":"Sem prejuízo do disposto no art. 174 desta Lei, os entes federativos poderão instituir sítio eletrônico oficial para divulgação complementar e realização das respectivas contratações."},{"k":"par","r":"§ 1º","t":"Desde que mantida a integração com o PNCP, as contratações poderão ser realizadas por meio de sistema eletrônico fornecido por pessoa jurídica de direito público ou privado, na forma de regulamento do Poder Executivo federal.","n":["(Redação dada pela Lei nº 15.266, de 2025)"]},{"k":"par","r":"§ 2º","t":"Até 31 de dezembro de 2023, os Municípios deverão realizar divulgação complementar de suas contratações mediante publicação de extrato de edital de licitação em jornal diário de grande circulação local.","n":["(Promulgação partes vetadas)"]}]},{"k":"art","n":"176","id":"a176","p":[{"k":"cap","r":"","t":"Os Municípios com até 20.000 (vinte mil) habitantes terão o prazo de 6 (seis) anos, contado da data de publicação desta Lei, para cumprimento:"},{"k":"inc","r":"I","t":"dos requisitos estabelecidos no art. 7º e no caput do art. 8º desta Lei;"},{"k":"inc","r":"II","t":"da obrigatoriedade de realização da licitação sob a forma eletrônica a que se refere o § 2º do art. 17 desta Lei;"},{"k":"inc","r":"III","t":"das regras relativas à divulgação em sítio eletrônico oficial."},{"k":"par","r":"Parágrafo único","t":"Enquanto não adotarem o PNCP, os Municípios a que se refere o caput deste artigo deverão:"},{"k":"inc","r":"I","t":"publicar, em diário oficial, as informações que esta Lei exige que sejam divulgadas em sítio eletrônico oficial, admitida a publicação de extrato;"},{"k":"inc","r":"II","t":"disponibilizar a versão física dos documentos em suas repartições, vedada a cobrança de qualquer valor, salvo o referente ao fornecimento de edital ou de cópia de documento, que não será superior ao custo de sua reprodução gráfica."}]},{"k":"cap","t":"CAPÍTULO II","s":"DAS ALTERAÇÕES LEGISLATIVAS"},{"k":"art","n":"177","id":"a177","p":[{"k":"cap","r":"","t":"O caput do art. 1.048 da Lei nº 13.105, de 16 de março de 2015 (Código de Processo Civil), passa a vigorar acrescido do seguinte inciso IV: (NR)"}]},{"k":"art","n":"178","id":"a178","p":[{"k":"cap","r":"","t":"O Título XI da Parte Especial do Decreto-Lei nº 2.848, de 7 de dezembro de 1940 (Código Penal), passa a vigorar acrescido do seguinte Capítulo II-B:"}]},{"k":"art","n":"179","id":"a179","p":[{"k":"cap","r":"","t":"Os incisos II e III do caput do art. 2º da Lei nº 8.987, de 13 de fevereiro de 1995, passam a vigorar com a seguinte redação: (NR)"}]},{"k":"art","n":"180","id":"a180","p":[{"k":"cap","r":"","t":"O caput do art. 10 da Lei nº 11.079, de 30 de dezembro de 2004, passa a vigorar com a seguinte redação: (NR)"}]},{"k":"cap","t":"CAPÍTULO III","s":"DISPOSIÇÕES TRANSITÓRIAS E FINAIS"},{"k":"art","n":"181","id":"a181","p":[{"k":"cap","r":"","t":"Os entes federativos instituirão centrais de compras, com o objetivo de realizar compras em grande escala, para atender a diversos órgãos e entidades sob sua competência e atingir as finalidades desta Lei."},{"k":"par","r":"Parágrafo único","t":"No caso dos Municípios com até 10.000 (dez mil) habitantes, serão preferencialmente constituídos consórcios públicos para a realização das atividades previstas no caput deste artigo, nos termos da Lei nº 11.107, de 6 de abril de 2005."}]},{"k":"art","n":"182","id":"a182","p":[{"k":"cap","r":"","t":"O Poder Executivo federal atualizará, a cada dia 1º de janeiro, pelo Índice Nacional de Preços ao Consumidor Amplo Especial (IPCA-E) ou por índice que venha a substituí-lo, os valores fixados por esta Lei, os quais serão divulgados no PNCP."}]},{"k":"art","n":"183","id":"a183","p":[{"k":"cap","r":"","t":"Os prazos previstos nesta Lei serão contados com exclusão do dia do começo e inclusão do dia do vencimento e observarão as seguintes disposições:"},{"k":"inc","r":"I","t":"os prazos expressos em dias corridos serão computados de modo contínuo;"},{"k":"inc","r":"II","t":"os prazos expressos em meses ou anos serão computados de data a data;"},{"k":"inc","r":"III","t":"nos prazos expressos em dias úteis, serão computados somente os dias em que ocorrer expediente administrativo no órgão ou entidade competente."},{"k":"par","r":"§ 1º","t":"Salvo disposição em contrário, considera-se dia do começo do prazo:"},{"k":"inc","r":"I","t":"o primeiro dia útil seguinte ao da disponibilização da informação na internet;"},{"k":"inc","r":"II","t":"a data de juntada aos autos do aviso de recebimento, quando a notificação for pelos correios."},{"k":"par","r":"§ 2º","t":"Considera-se prorrogado o prazo até o primeiro dia útil seguinte se o vencimento cair em dia em que não houver expediente, se o expediente for encerrado antes da hora normal ou se houver indisponibilidade da comunicação eletrônica."},{"k":"par","r":"§ 3º","t":"Na hipótese do inciso II do caput deste artigo, se no mês do vencimento não houver o dia equivalente àquele do início do prazo, considera-se como termo o último dia do mês."}]},{"k":"art","n":"184","id":"a184","p":[{"k":"cap","r":"","t":"Aplicam-se as disposições desta Lei, no que couber e na ausência de norma específica, aos convênios, acordos, ajustes e outros instrumentos congêneres celebrados por órgãos e entidades da Administração Pública, na forma estabelecida em regulamento do Poder Executivo federal."},{"k":"par","r":"§ 1º","t":"","n":["(VETADO)","(Incluído pela Lei nº 14.770, de 2023)"],"rev":1},{"k":"par","r":"§ 2º","t":"Quando, verificada qualquer das hipóteses da alínea d do inciso II do caput do art. 124 desta Lei, o valor global inicialmente pactuado demonstrar-se insuficiente para a execução do objeto, poderão ser:","n":["(Incluído pela Lei nº 14.770, de 2023)"]},{"k":"inc","r":"I","t":"utilizados saldos de recursos ou rendimentos de aplicação financeira;","n":["(Incluído pela Lei nº 14.770, de 2023)"]},{"k":"inc","r":"II","t":"aportados novos recursos pelo concedente;","n":["(Incluído pela Lei nº 14.770, de 2023)"]},{"k":"inc","r":"III","t":"reduzidas as metas e as etapas, desde que isso não comprometa a fruição ou a funcionalidade do objeto pactuado.","n":["(Incluído pela Lei nº 14.770, de 2023)"]},{"k":"par","r":"§ 3º","t":"São permitidos ajustes nos instrumentos celebrados com recursos de transferências voluntárias, para promover alterações em seu objeto, desde que:","n":["(Incluído pela Lei nº 14.770, de 2023)"]},{"k":"inc","r":"I","t":"isso não importe transposição, remanejamento ou transferência de recursos de uma categoria de programação para outra ou de um órgão para outro;","n":["(Incluído pela Lei nº 14.770, de 2023)"]},{"k":"inc","r":"II","t":"seja apresentada justificativa objetiva pelo convenente; e","n":["(Incluído pela Lei nº 14.770, de 2023)"]},{"k":"inc","r":"III","t":"quando se tratar de obra, seja mantido o que foi pactuado quanto a suas características.","n":["(Incluído pela Lei nº 14.770, de 2023)"]},{"k":"par","r":"§ 4º","t":"Os saldos remanescentes e os rendimentos financeiros auferidos na forma do § 1º deste artigo serão obrigatoriamente computados a crédito do convênio e aplicados no objeto de sua finalidade e na ampliação de meta, quando possível, sem prejuízo da funcionalidade do objeto pactuado, devendo constar de demonstrativo específico que integrará as prestações de contas do ajuste.","n":["(Incluído pela Lei nº 14.770, de 2023)"]}]},{"k":"art","n":"184-A","id":"a184A","p":[{"k":"cap","r":"","t":"À celebração, à execução, ao acompanhamento e à prestação de contas dos convênios, contratos de repasse e instrumentos congêneres em que for parte a União, com valor global de até R$ 1.500.000,00 (um milhão e quinhentos mil reais), aplicar-se-á o seguinte regime simplificado:","n":["(Incluído pela Lei nº 14.770, de 2023)","(Vide Decreto nº 12.343, de 2024)","(Vide Decreto nº 12.807, de 2025)"]},{"k":"inc","r":"I","t":"o plano de trabalho aprovado conterá parâmetros objetivos para caracterizar o cumprimento do objeto;","n":["(Incluído pela Lei nº 14.770, de 2023)"]},{"k":"inc","r":"II","t":"a minuta dos instrumentos deverá ser simplificada;","n":["(Incluído pela Lei nº 14.770, de 2023)"]},{"k":"inc","r":"III","t":"a liberação dos recursos dar-se-á em parcela única;","n":["(Incluído pela Lei nº 14.770, de 2023)"]},{"k":"inc","r":"IV","t":"a verificação da execução do objeto ocorrerá mediante visita de constatação da compatibilidade com o plano de trabalho.","n":["(Incluído pela Lei nº 14.770, de 2023)"]},{"k":"par","r":"§ 1º","t":"O acompanhamento pela concedente ou mandatária será realizado pela verificação dos boletins de medição e fotos georreferenciadas registradas pela empresa executora e pelo convenente do Transferegov e por vistorias in loco, realizadas considerando o marco de execução de 100% (cem por cento) do cronograma físico, podendo ocorrer outras vistorias, quando necessárias.","n":["(Incluído pela Lei nº 14.770, de 2023)"]},{"k":"par","r":"§ 2º","t":"Não haverá análise nem aceite de termo de referência, anteprojeto, projeto, orçamento, resultado do processo licitatório ou outro documento necessário para o início da execução do objeto, e caberá à concedente ou mandatária verificar o cumprimento do objeto pactuado ao final da execução do instrumento.","n":["(Incluído pela Lei nº 14.770, de 2023)"]},{"k":"par","r":"§ 3º","t":"Quando exigidos, os registros dos projetos de engenharia, dos documentos de titularidade de área, do licenciamento ambiental e do processo licitatório pelo convenente no Transferegov constituirão condição para a liberação da parcela única dos recursos de que trata o inciso III do caput deste artigo.","n":["(Incluído pela Lei nº 14.770, de 2023)"]},{"k":"par","r":"§ 4º","t":"O regime simplificado de que trata este artigo aplica-se aos convênios, contratos de repasse e instrumentos congêneres celebrados após a publicação desta Lei.","n":["(Incluído pela Lei nº 14.770, de 2023)"]}]},{"k":"art","n":"185","id":"a185","p":[{"k":"cap","r":"","t":"Aplicam-se às licitações e aos contratos regidos pela Lei nº 13.303, de 30 de junho de 2016, as disposições do Capítulo II-B do Título XI da Parte Especial do Decreto-Lei nº 2.848, de 7 de dezembro de 1940 (Código Penal)."}]},{"k":"art","n":"186","id":"a186","p":[{"k":"cap","r":"","t":"Aplicam-se as disposições desta Lei subsidiariamente à Lei nº 8.987, de 13 de fevereiro de 1995, à Lei nº 11.079, de 30 de dezembro de 2004, e à Lei nº 12.232, de 29 de abril de 2010."}]},{"k":"art","n":"187","id":"a187","p":[{"k":"cap","r":"","t":"Os Estados, o Distrito Federal e os Municípios poderão aplicar os regulamentos editados pela União para execução desta Lei."}]},{"k":"art","n":"188","id":"a188","p":[{"k":"cap","r":"","t":"","n":["(VETADO)"],"rev":1}]},{"k":"art","n":"189","id":"a189","p":[{"k":"cap","r":"","t":"Aplica-se esta Lei às hipóteses previstas na legislação que façam referência expressa à Lei nº 8.666, de 21 de junho de 1993, à Lei nº 10.520, de 17 de julho de 2002, e aos arts. 1º a 47-A da Lei nº 12.462, de 4 de agosto de 2011."}]},{"k":"art","n":"190","id":"a190","p":[{"k":"cap","r":"","t":"O contrato cujo instrumento tenha sido assinado antes da entrada em vigor desta Lei continuará a ser regido de acordo com as regras previstas na legislação revogada."},{"k":"par","r":"Parágrafo único","t":"","n":["(Revogado pela Medida Provisória nº 1.167, de 2023)","(Vigência encerrada)"],"rev":1}]},{"k":"art","n":"191","id":"a191","p":[{"k":"cap","r":"","t":"Até o decurso do prazo de que trata o inciso II do caput do art. 193, a Administração poderá optar por licitar ou contratar diretamente de acordo com esta Lei ou de acordo com as leis citadas no referido inciso, e a opção escolhida deverá ser indicada expressamente no edital ou no aviso ou instrumento de contratação direta, vedada a aplicação combinada desta Lei com as citadas no referido inciso."},{"k":"par","r":"Parágrafo único","t":"Na hipótese do caput deste artigo, se a Administração optar por licitar de acordo com as leis citadas no inciso II do caput do art. 193 desta Lei, o contrato respectivo será regido pelas regras nelas previstas durante toda a sua vigência."}]},{"k":"art","n":"192","id":"a192","p":[{"k":"cap","r":"","t":"O contrato relativo a imóvel do patrimônio da União ou de suas autarquias e fundações continuará regido pela legislação pertinente, aplicada esta Lei subsidiariamente."}]},{"k":"art","n":"193","id":"a193","p":[{"k":"cap","r":"","t":"Revogam-se:"},{"k":"inc","r":"I","t":"os arts. 89 a 108 da Lei nº 8.666, de 21 de junho de 1993, na data de publicação desta Lei;","n":["(Vigência encerrada)"]},{"k":"inc","r":"II","t":"em 30 de dezembro de 2023:","n":["(Redação dada pela Lei Complementar nº 198, de 2023)"]},{"k":"ali","r":"a)","t":"a Lei nº 8.666, de 21 de junho de 1993;","n":["(Redação dada pela Lei Complementar nº 198, de 2023)"]},{"k":"ali","r":"b)","t":"a Lei nº 10.520, de 17 de julho de 2002; e","n":["(Redação dada pela Lei Complementar nº 198, de 2023)"]},{"k":"ali","r":"c)","t":"os arts. 1º a 47-A da Lei nº 12.462, de 4 de agosto de 2011.","n":["(Redação dada pela Lei Complementar nº 198, de 2023)"]}]},{"k":"art","n":"194","id":"a194","p":[{"k":"cap","r":"","t":"Esta Lei entra em vigor na data de sua publicação."}]}]};
